window.ENAMED_LOCAL_QUESTION_BANK["15"] = {"block":15,"count":130,"questions":[{"id":"b15-q001","number":1,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Assinale a alternativa que corresponde ao tipo de hérnia mais comum que gera sintomas de refluxo gastroesofágico:","options":{"A":"Hérnia hiatal por deslizamento.","B":"Hérnia de Spiegel.","C":"Hérnia de Zenker.","D":"Hérnia epigástrica.","E":"Hérnia hiatal paraesofágica."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A hérnia hiatal por deslizamento (Tipo I) é a mais comum (cerca de 90% dos casos). Nela, a junção esofagogástrica e parte do estômago deslizam para o mediastino, comprometendo a função do esfíncter esofágico inferior e gerando sintomas de refluxo gastroesofágico.\nPor que as outras estão erradas:\nB: Hérnia de Spiegel ocorre na linha semilunar (abdome), sem relação com o refluxo.\nC: Hérnia de Zenker é uma hérnia faringoesofágica, causando regurgitação de alimentos não digeridos, não refluxo ácido.\nD: Hérnia epigástrica ocorre na linha alba, não tem relação com o trato gastrointestinal superior.\nE: Hérnia hiatal paraesofágica (Tipo II) tem o fundo gástrico herniado ao lado do esôfago, mas a junção permanece fixa, causando menos refluxo, porém com alto risco de estrangulamento.\nPonto de prova: Relação entre os tipos de hérnias e a fisiopatologia do refluxo gastroesofágico.\nFlashcard sugerido: Qual hérnia hiatal mais comum e associada à DRGE? Resposta: Hérnia hiatal por deslizamento (Tipo I).\nPérola: Deslizamento gera refluxo; paraesofágica estrangula.\nArmadilha: Confundir a hérnia paraesofágica com a por deslizamento.","tags":["Cirurgia","Cirurgia Geral","Refluxo Gastroesofágico","Hérnias","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Quase 9 em cada 10 hérnias no diafragma são do tipo em que uma parte do estômago escorrega para cima, o que estraga a válvula que segura o suco do estômago lá embaixo — por isso causa azia."},{"id":"b15-q002","number":2,"collectionBlock":15,"documentBlock":15,"area":"Saúde Coletiva","topic":"Ferramentas da APS","stem":"Considerando que a Política Nacional de Educação Permanente em Saúde (PNEPS), instituída no ano de 2004, representa um marco para a formação e trabalho em saúde no País, assinale a alternativa correta:","options":{"A":"A Política Nacional de Educação Permanente em Saúde estabelece a carga horária de duas horas, quinzenalmente, para atividades formativas, com o propósito de promover a transformação das práticas do trabalho em saúde.","B":"A Política Nacional de Educação Permanente em Saúde estabelece a carga horária de duas horas, quinzenalmente, para atividades formativas exclusivamente para médicos, com o propósito de promover a transformação das práticas do trabalho em saúde.","C":"Conforme a Lei nº 13.595/2018, que altera o exercício profissional dos Agentes Comunitários de Saúde e Agentes de Combate às Endemias, é vetado a estes profissionais a realização de ações de educação popular em saúde.","D":"O Programa Saúde com Agente é uma iniciativa do Governo Federal que passa a exigir a realização um curso de atualização de 120 horas para os Agentes Comunitários de Saúde a partir de 2022.","E":"O Programa Saúde com Agente irá prover a formação técnica dos Agentes Comunitários de Saúde e Agentes de Combate às Endemias em todo o País."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O Programa Saúde com Agente (instituído pela Lei nº 14.637/2023) prevê a provisão de formação técnica para os Agentes Comunitários de Saúde (ACS) e Agentes de Combate às Endemias (ACE) em todo o País.\nPor que as outras estão erradas:\nA/B: A PNEPS não estabelece uma carga horária fixa e obrigatória de 2 horas quinzenais para atividades formativas.\nC: É falso que agentes estão vetados de realizar educação popular em saúde; na verdade, é uma de suas atribuições.\nD: O curso de atualização de 120 horas não é uma exigência obrigatória a partir de 2022 para os ACS.\nPonto de prova: Diretrizes do Programa Saúde com Agente.\nFlashcard sugerido: O que o Programa Saúde com Agente provê para ACS e ACE? Resposta: Formação técnica em todo o País.\nPérola: Saúde com Agente = Formação técnica para ACS e ACE.\nArmadilha: Achar que a PNEPS impõe carga horária rígida de 2h quinzenais.","tags":["Saúde Coletiva","Gestão e Educação em Saúde","Educação Permanente em Saúde","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Esse programa do governo tem o papel de dar formação técnica para os agentes de saúde que visitam as casas das famílias, em todo o país."},{"id":"b15-q003","number":3,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções na Gravidez","stem":"Com relação à infecção por toxoplasmose na gravidez, assinale a alternativa correta.","options":{"A":"Na maior parte das vezes, a infecção aguda apresenta-se como síndrome mono-like e a infecção subclínica ocorre apenas em 10% dos casos.","B":"A presença de IgM positivo e IgG positivo com 26 semanas de gestação indica a realização de teste de avidez da IgG.","C":"O risco de transmissão vertical é diretamente proporcional à idade gestacional.","D":"Na presença de infecção aguda materna confirmada na gravidez, é necessário o tratamento com sulfadiazina, pirimetamina e ácido folínico.","E":"A infecção fetal pelo Toxoplasma gondii pode ser diagnosticada por ultrassonografia, pois 70% dos fetos apresentam alterações ultrassonográficas."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O risco de transmissão vertical da toxoplasmose aumenta progressivamente com a idade gestacional (sendo maior no 3º trimestre). No entanto, a gravidade da infecção fetal é inversamente proporcional (mais grave no 1º trimestre).\nPor que as outras estão erradas:\nA: A maioria das infecções agudas é assintomática (subclínica); a síndrome mono-like ocorre em minoria.\nB: Com 26 semanas, o teste de avidez perde utilidade (baixa avidez pode persistir por meses); indica-se amniocentese.\nD: O tratamento com sulfadiazina + pirimetamina + ácido folínico é para infecção fetal confirmada. Para materna aguda não confirmada no feto, usa-se espiramicina.\nE: Apenas cerca de 10% a 30% dos fetos apresentam alterações ultrassonográficas.\nPonto de prova: Relação entre idade gestacional, risco de transmissão e gravidade na toxoplasmose.\nFlashcard sugerido: O risco de transmissão vertical da toxoplasmose aumenta com a IG? Resposta: Sim, é diretamente proporcional à IG.\nPérola: Transmissão sobe com a IG, mas a gravidade desce.\nArmadilha: Achar que, como a gravidade é maior no 1º trimestre, a transmissão também é.","tags":["Clínica Médica","Infectologia","Toxoplasmose Gestacional","Toxoplasmose","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quanto mais tempo dura a gravidez, maior a chance desse micróbio passar da mãe para o bebê, mesmo que o perigo para o bebê seja maior quando a infecção acontece bem no início."},{"id":"b15-q004","number":4,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"G1P0A1 (note que a paridade correta seria 2G1Ab), idade gestacional de 9 semanas, volta à consulta de pré-natal trazendo os seguintes exames para toxoplasmose: IgG reagente e IgM reagente. Foi solicitado o teste de avidez IgG específico, que apresentou como resultado alta avidez. Nesse caso, devemos considerar:","options":{"A":"Infecção aguda.","B":"Infeção materna e fetal.","C":"Paciente suscetível.","D":"Infecção adquirida há menos de 4 meses.","E":"Infecção adquirida há mais de 4 meses."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Alta avidez do IgG indica que a infecção foi adquirida há mais de 4 meses (frequentemente mais de 12 a 16 semanas). Como a gestante está com 9 semanas, a infecção ocorreu antes da gestação, não havendo risco de transmissão vertical.\nPor que as outras estão erradas:\nA/B/C/D: Baixa avidez sugeriria infecção recente; suscetibilidade é IgG e IgM negativos; infecção materno-fetal não é confirmada apenas por sorologia materna.\nPonto de prova: Interpretação do teste de avidez de IgG na toxoplasmose.\nFlashcard sugerido: O que significa alta avidez de IgG na toxoplasmose? Resposta: Infecção há mais de 4 meses.\nPérola: Alta avidez = infecção velha (>4 meses).\nArmadilha: Confundir alta e baixa avidez.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando o exame mostra que os anticorpos da mãe já estão 'fortes e maduros' (alta avidez), isso quer dizer que ela pegou a doença há bastante tempo, antes mesmo de engravidar, então o bebê não corre risco."},{"id":"b15-q005","number":5,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher, 33 anos de idade, foi submetida a gastroplastia em *Y de Roux* para tratamento de obesidade mórbida, há 2 meses. Procura o serviço de urgência com queixa de disfagia, regurgitação de alimentos sólidos, há 1 mês, com piora progressiva. Ao exame físico: bom estado geral, desidratada, corada, abdome flácido e indolor à palpação. Qual é a principal hipótese diagnóstica?","options":{"A":"Transtorno alimentar (bulimia).","B":"Hérnia interna.","C":"Estenose da enteroentero anastomose.","D":"Estenose da gastroenteroanastomose."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Disfagia e regurgitação de alimentos sólidos, com piora progressiva 1 a 2 meses após bypass em Y de Roux, é a apresentação clássica de estenose da gastroenteroanastomose (anastomose entre o pouch gástrico e o jejuno).\nPor que as outras estão erradas:\nA: Bulimia não causa disfagia orgânica pós-cirúrgica.\nB: Hérnia interna causa dor abdominal em cólica, vômitos e obstrução, tipicamente após meses/anos, e não disfagia precoce.\nC: Estenose da enteroenteroanastomose causa obstrução intestinal distal, vômitos biliosos e distensão.\nPonto de prova: Complicações pós-bypass gástrico em Y de Roux.\nFlashcard sugerido: Disfagia e regurgitação pós-Y de Roux precoce indicam o quê? Resposta: Estenose da gastroenteroanastomose.\nPérola: Disfagia pós-bypass = estenose da gastroentero.\nArmadilha: Confundir com hérnia interna (que dá dor e obstrução).","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Obesidade","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois dessa cirurgia de emagrecimento, a ligação nova entre o estômago e o intestino pode ir estreitando aos poucos, dificultando a passagem da comida — por isso a comida sólida não desce direito."},{"id":"b15-q006","number":6,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Homem, 48 anos, com histórico de febre de início há 3 dias associada à dor lombar, calafrios, cefaleia, náuseas e vômitos, busca atendimento em unidade de pronto atendimento pela segunda vez após piora progressiva do quadro a despeito do uso de sintomáticos receitados previamente (ibuprofeno e paracetamol). Sem comorbidades conhecidas, refere a relação homoafetiva sem proteção com o parceiro fixo. Dá entrada em regular estado geral, febril (38,4°), hipotenso (85x40mmHg) e descorado. Levantando- se hipótese de meningite bacteriana aguda, assinale a alternativa correta sobre sua investigação diagnóstica:","options":{"A":"O sinal de Kernig se caracteriza pela flexão de ambos os joelhos ao se levantar a região nucal.","B":"O sinal de Brudziski é pesquisado com o paciente em decúbito dorsal horizontal elevando se um dos membros inferiores em extensão. É dito positivo quando o paciente flete ligeiramente o joelho contralateral.","C":"Para punção lombar, deve- se palpar as cristas ilíacas e, a seguir, traçar uma linha imaginária entre as duas margens superiores. Essa linha faz intersecção com os processos espinhosos da vértebra L4.","D":"A antissepsia do local de punção é facultativa, pois trata-se de superfície cutânea limpa.","E":"Durante a punção lombar, a maior resistência à inserção da agulha é conferida pela dura-máter."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A linha de Tuffier (linha imaginária traçada entre as margens superiores das cristas ilíacas) cruza o processo espinhoso de L4 ou o espaço L4-L5, que é o referencial anatômico padrão e seguro para a punção lombar.\nPor que as outras estão erradas:\nA: O sinal de Kernig é a resistência/pain à extensão do joelho com o quadril fletido a 90°.\nB: A descrição refere-se ao sinal de Brudzinski da perna (ou contralateral), e não o sinal de Brudzinski de pescoço (que é a flexão do pescoço gerando flexão de quadril/joelho).\nD: A antissepsia rigorosa é obrigatória.\nE: A duramáter é perfurada e oferece resistência, mas o ligamento amarelo também é uma referência de resistência. A questão foca no referencial ósseo.\nPonto de prova: Referenciais anatômicos e técnica de punção lombar.\nFlashcard sugerido: Linha entre cristas ilíacas cruza qual vértebra na punção lombar? Resposta: L4 (ou espaço L4-L5).\nPérola: Crista ilíaca aponta L4.\nArmadilha: Confundir os sinais de Kernig e Brudzinski.","tags":["Clínica Médica","Neurologia","Ibuprofeno","Paracetamol","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Para fazer a picadinha nas costas e coletar o líquido que envolve a medula, o médico usa como referência uma linha imaginária entre os ossos do quadril, que aponta para o lugar certo da coluna."},{"id":"b15-q007","number":7,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Assinale a alternativa com os agentes etiológicos mais comuns das meningites bacterianas em idosos:","options":{"A":"Neisseria meningitidis, Enteroccous faecium e Pseudomonas aeruginosa.","B":"Neisseria meningitidis, Streptococcus pneumoniae e Pseudomonas aeruginosa.","C":"Neisseria meningitidis, Streptococcus pneumoniae e Listeria monocytogenes.","D":"Neisseria meningitidis, Haemophilus influenzae e Listeria monocytogenes.","E":"Neisseria meningitidis, Staphylococcus aureus e Listeria monocytogenes."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Em idosos (>50 anos), os principais agentes etiológicos das meningites bacterianas são Streptococcus pneumoniae, Neisseria meningitidis e Listeria monocytogenes (devido à imunossenescência).\nPor que as outras estão erradas:\nA/B/D/E: Haemophilus influenzae, Staphylococcus aureus, Enterococcus e Pseudomonas não são os principais agentes em idosos imunocompetentes.\nPonto de prova: Epidemiologia das meningites bacterianas por faixa etária.\nFlashcard sugerido: Agentes mais comuns de meningite bacteriana em idosos? Resposta: S. pneumoniae, N. meningitidis e Listeria monocytogenes.\nPérola: Idoso tem Listeria.\nArmadilha: Esquecer a Listeria no idoso.","tags":["Clínica Médica","Medicina Interna","Meningite no Idoso","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Em pessoas mais velhas, além dos micróbios mais comuns, existe uma bactéria chamada Listeria que também costuma causar essa infecção nas membranas do cérebro."},{"id":"b15-semanais-q08","number":8,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Recém- nascido, filho de mãe sem pré- natal, nasceu de parto normal com 38 semanas de gestação, pequeno para a idade gestacional. Na maternidade, detectou- se a presença de persistência do canal arterial, o teste do reflexo vermelho apresentou opacidade bilateral e as emissões otoacústicas foram ausentes bilateralmente. Esses achados são sugestivos de qual infecção congênita?","options":{"A":"Toxoplasmose.","B":"Sífilis.","C":"Rubéola.","D":"Por citomegalovírus.","E":"Por herpes simplex."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A tríade clássica da Síndrome da Rubéola Congênita é: defeitos cardíacos (Persistência do Canal Arterial - PCA), alterações oculares (catarata, opacidade do reflexo vermelho) e surdez (alteração nas emissões otoacústicas).\nPor que as outras estão erradas:\nA: Toxoplasmose causa coriorretinite, calcificações cerebrais e hidrocefalia.\nB: Sífilis causa pseudoparalisia de Parrot, rinite e hepatite.\nD: CMV causa petéquias, calcificações periventriculares e microcefalia.\nPonto de prova: Síndromes de infecções congênitas (tríade da rubéola).\nFlashcard sugerido: RN com PCA, catarata e surdez tem qual infecção congênita? Resposta: Rubéola congênita.\nPérola: Rubéola: coração, olho e ouvido.\nArmadilha: Confundir com CMV ou toxoplasmose.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Assistência ao Parto","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Uma dor forte, de repente, atrás do olho, que dura só minutos mas se repete várias vezes ao dia, com olho vermelho e nariz entupido do mesmo lado, é tratada rapidinho respirando oxigênio puro."},{"id":"b15-q009","number":9,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Um homem, com 58 anos de idade, foi atendido em ambulatório de hospital secundário. Relatava dor e queimação epigástrica que aumentava após a ingestão de alimentos, acompanhada de plenitude pós-prandial. Realizou endoscopia digestiva alta que evidenciou úlcera com 5 mm de diâmetro na parede anterior do antro gástrico, na região pré-pilórica. Com base nos dados apresentados, assinale a alternativa que apresenta a conduta adequada a ser seguida:","options":{"A":"Solicitar endoscopia com biópsias seriadas para excluir neoplasia gástrica e pesquisar Helicobacter pylori.","B":"Indicar tratamento operatório pela localização da úlcera e risco de perfuração.","C":"Prescrever inibidor de secreção gástrica por 6 a 8 semanas e solicitar endoscopia com pesquisa de Helicobacter pylori, avaliando a cicatrização.","D":"Prescrever inibidor da secreção gástrica e tratar Helicobacter pylori empiricamente por sua prevalência em ulcerosos, evitando recidiva."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Toda úlcera gástrica exige biópsias seriadas para excluir neoplasia (câncer gástrico) e pesquisa de Helicobacter pylori, independentemente da aparência benigna.\nPor que as outras estão erradas:\nB: Cirurgia não é indicada de imediato sem tentativa de tratamento clínico, salvo complicações.\nC/D: Tratar empiricamente sem biopsiar úlcera gástrica é erro grave, pois pode mascarar um câncer.\nPonto de prova: Conduta endoscópica frente a úlcera gástrica.\nFlashcard sugerido: Conduta ao encontrar úlcera gástrica na endoscopia? Resposta: Biópsias seriadas para excluir neoplasia e pesquisar H. pylori.\nPérola: Úlcera gástrica sempre se biopsia.\nArmadilha: Tratar úlcera gástrica como se fosse duodenal (onde não se biopsia de rotina).","tags":["Clínica Médica","Medicina Interna","Endoscopia","Conduta Terapêutica","Assistência Hospitalar","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Sempre que se encontra uma ferida no estômago, o médico precisa tirar um pedacinho para examinar no microscópio, porque ela pode, às vezes, esconder um câncer."},{"id":"b15-q010","number":10,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma mulher com 28 anos de idade, primigesta, com 14 semanas de gestação, comparece à segunda consulta de pré-natal com resultado de exame de sorologia para toxoplasmose com IgG e IgM positivos. A paciente está assintomática. Nesse caso, a conduta médica adequada ao realizar o atendimento a essa gestante é:","options":{"A":"Prescrever imediatamente espiramicina e solicitar teste de avidez de IgG.","B":"Prescrever imediatamente espiramicina e solicitar nova sorologia em 1 mês.","C":"Tranquilizar a paciente, dizendo que se trata de infecção antiga e não solicitar mais sorologias.","D":"Tranquilizar a paciente, dizendo que pode se tratar de falso positivo e solicitar nova sorologia em 2 semanas."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Gestante com IgG e IgM positivos no 1º trimestre sem sorologias prévias requer teste de avidez de IgG para datar a infecção. Inicia-se espiramicina profilática imediatamente, pois não se pode descartar infecção aguda.\nPor que as outras estão erradas:\nB: Nova sorologia em 1 mês atrasa o diagnóstico e não afasta o risco imediato.\nC: Não se pode afirmar que é infecção antiga sem provar (avidez).\nD: Não é apenas falso positivo; exige investigação ativa.\nPonto de prova: Fluxograma de toxoplasmose gestacional (IgG/IgM + no 1º trimestre).\nFlashcard sugerido: Gestante com IgG e IgM + no 1º trimestre, o que fazer? Resposta: Iniciar espiramicina e solicitar teste de avidez de IgG.\nPérola: IgM + na gestante = Espiramicina + Avidez.\nArmadilha: Solicitar nova sorologia ao invés do teste de avidez.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando os dois exames de sangue da toxoplasmose dão positivos e não havia exame anterior para comparar, o médico já começa o remédio de proteção e pede um teste extra para saber se a infecção é recente ou antiga."},{"id":"b15-q011","number":11,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma gestante, com 28 anos de idade, na 14.a semana de gestação, primigesta, em consulta com equipe de Estratégia de Saúde da Família para avaliação de exames de pré- natal apresenta IgG e IgM reagentes para toxoplasmose, sem resultado de exames prévios. Solicitado teste de avidez de IgG na mesma amostra, com resultado “avidez forte”. A interpretação do resultado e a conduta são:","options":{"A":"infecção adquirida antes da gestação, sem necessidade de mais testes.","B":"infecção adquirida durante a gestação, iniciar espiramicina e manter até o parto.","C":"Imunidade remota, indicado repetir sorologia a cada 2 meses e no parto.","D":"Infecção recente, iniciar pirimetamina + sulfadiazina + ácido folínico e encaminhar para a referência de gestação de risco."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: \"Avidez forte\" (alta avidez) indica infecção há mais de 4 meses. Como a gestante está na 14ª semana, a infecção ocorreu antes da gestação, não havendo risco de transmissão vertical e não precisando de mais testes.\nPor que as outras estão erradas:\nB/C/D: Tratamentos ou repetições são desnecessários se a infecção é pré-gestacional.\nPonto de prova: Interpretação da avidez forte de IgG na gestação.\nFlashcard sugerido: Gestante com IgG/IgM + e alta avidez na 14ª semana. Conduta? Resposta: Infecção antes da gestação, sem necessidade de mais testes.\nPérola: Alta avidez no 1º trimestre = infecção antiga, dispensa tratamento.\nArmadilha: Achar que IgM positivo sempre exige tratamento.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Avidez de IgG","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Um resultado de exame que mostra 'anticorpos fortes e maduros' indica que a infecção aconteceu há muito tempo — antes da gravidez —, então não há perigo para o bebê e nenhum tratamento é necessário."},{"id":"b15-q012","number":12,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Paciente com queixa de pirose, azia e regurgitação procura orientações sobre um possível diagnóstico de Doença do Refluxo Gastroesofágico (DRGE) e tratamento. Assinale a alternativa que apresenta somente informações corretas que poderão ser fornecidas a esse paciente:","options":{"A":"O exame padrão-ouro para o diagnóstico é a endoscopia digestiva alta. A DRGE pode ser causada por hérnia hiatal do tipo I, chamada de hérnia de rolamento.","B":"O melhor exame para o diagnóstico é a manometria. A DRGE pode ser causada por hérnia hiatal do tipo II, chamada de hérnia por deslizamento.","C":"O melhor exame para o diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por hérnia hiatal do tipo II, conhecida como hérnia de rolamento.","D":"O melhor exame para o diagnóstico é a esofagografia. A DRGE pode ser causada por hérnia hiatal do tipo II, chamada de hérnia por rolamento.","E":"O exame padrão-ouro para diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por hérnia hiatal do tipo III, chamada de hérnia por deslizamento."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A pHmetria esofágica de 24h é o padrão-ouro para DRGE não erosiva (quando a endoscopia é normal). A hérnia hiatal Tipo II (paraesofágica) é conhecida como hérnia de rolamento.\nPor que as outras estão erradas:\nA: Endoscopia não é padrão-ouro (pode ser normal). Hérnia Tipo I é por deslizamento.\nB: Manometria avalia motilidade, não refluxo. Tipo II é paraesofágica (rolamento), não deslizamento.\nD: Esofagografia não é padrão-ouro.\nE: Hérnia Tipo III é mista.\nPonto de prova: Métodos diagnósticos da DRGE e classificação das hérnias hiatais.\nFlashcard sugerido: Qual o padrão-ouro para DRGE e qual hérnia é de \"rolamento\"? Resposta: pHmetria de 24h; Hérnia Tipo II (paraesofágica).\nPérola: Tipo I desliza; Tipo II rola.\nArmadilha: Achar que a hérnia mais comum (Tipo I) é a de rolamento.","tags":["Clínica Médica","Medicina Interna","Refluxo Gastroesofágico","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Existe um exame que mede o ácido subindo pelo esôfago durante 24 horas, e uma hérnia em que parte do estômago rola para o lado do esôfago, chamada de hérnia de rolamento."},{"id":"b15-q013","number":13,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Mulher, 27 anos, há 1 ano foi submetida à derivação gástrica em Y de Roux para tratamento de obesidade. Refere perda de 40 kg neste período. Procura o Serviço de Emergência devido à dor abdominal intensa, em cólica difusa, com início há 4 horas. Relata náuseas, porém sem vômitos. Nega melhora com analgésicos. Ao exame clínico, encontra-se em posição antálgica, FC 122 bpm, abdome pouco distendido, doloroso em hipocôndrio esquerdo, sem sinais de irritação peritoneal e com ruídos hidroaéreos aumentados em frequência. Exames laboratoriais: Hb 11,2 g/dL; Ht 38%; Leucograma 17.223/mm3 ; PCR 17 mg/L; Ureia 90 mg/dL; Creatinina 1,7 mg/dL. Tomografia de abdome apresentada abaixo. Qual deve ser a conduta, além de hidratação e analgesia?","options":{"A":"Trombólise.","B":"Sonda gástrica e observação.","C":"Dilatação endoscópica da anastomose.","D":"Tratamento operatório."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: D.\nPor que está certa: Pós-bypass em Y de Roux (após perda de peso) com dor em cólica intensa, taquicardia e achados de obstrução fechada exige tratamento operatório de urgência (videolaparoscopia), pois o quadro sugere hérnia interna estrangulada.\nPor que as outras estão erradas:\nA/B/C: Trombólise, sonda gástrica ou dilatação endoscópica não tratam obstrução intestinal por hérnia interna, que é uma emergência cirúrgica.\nPonto de prova: Complicação tardia do bypass em Y de Roux (hérnia interna).\nFlashcard sugerido: Dor cólica intensa e taquicardia pós-Y de Roux tardio indica o quê? Resposta: Hérnia interna, tratar cirurgicamente.\nPérola: Pós-Y de Roux com dor e taqui = Hérnia interna.\nArmadilha: Achar que é uma simples cólica funcional e não operar.","tags":["Clínica Médica","Nefrologia","Cirurgia Bariátrica","Obesidade","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois da cirurgia de emagrecimento, um pedaço do intestino pode ficar preso e torcido dentro de um buraco formado pela própria cirurgia, causando dor forte — isso só se resolve operando de novo."},{"id":"b15-q014","number":14,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Senhora de 47 anos de idade, tabagista, obesa e etilista social, é atendida no ambulatório por dispepsia há vários anos. Já fez tratamento para erradicação de Helicobacter pylori, há muito tempo. Não fez controle. Sempre teve “dor de estômago”, mas agora queixa- se de perda ponderal significativa no último mês. O fator de risco a que este tumor está mais comumente relacionado é:","options":{"A":"Etilismo.","B":"Infecção por H. pylori.","C":"Obesidade.","D":"Tabagismo."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A infecção por Helicobacter pylori é o principal fator de risco ambiental para adenocarcinoma gástrico tipo intestinal.\nPor que as outras estão erradas:\nA/C/D: Etilismo, obesidade e tabagismo são fatores de risco para outras neoplasias (esôfago, etc.), mas o H. pylori é o mais fortemente associado ao câncer gástrico.\nPonto de prova: Fatores de risco para câncer gástrico.\nFlashcard sugerido: Principal fator de risco ambiental para adenocarcinoma gástrico? Resposta: Infecção por Helicobacter pylori.\nPérola: H. pylori é o rei do câncer gástrico.\nArmadilha: Achar que tabagismo ou etilismo superam o H. pylori.","tags":["Clínica Médica","Oncologia","Tabagismo","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Uma bactéria chamada H. pylori, que vive no estômago, é a principal responsável por causar esse tipo de câncer no estômago."},{"id":"b15-q015","number":15,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Ricardo, 23 anos, comparece à consulta com queixa de pirose e dor epigástrica. Refere que os sintomas são frequentes, ocorrendo mais de 3 vezes por semana, há cerca de 6 meses. Refere que já deixou de tomar café, refrigerantes e comer alimentos gordurosos; mesmo assim, os sintomas persistiram. Assinale a alternativa que apresenta a melhor conduta diante desse paciente:","options":{"A":"Realizar uma pHmetria esofágica para confirmar o diagnóstico de DRGE (Doença do Refluxo Gastroesofágico).","B":"Prescrever antiácidos como hidróxido de alumínio para alívio dos sintomas, uma vez que os sintomas são leves.","C":"Iniciar um inibidor de bomba de prótons (PPI) por 8 semanas.","D":"Solicitar endoscopia digestiva alta, uma vez que esse paciente tem sinais de alarme.","E":"Prescrever B2-agonista seletivo, pois este alivia os sintomas e previne esôfago de Barrett."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Paciente com sintomas típicos de DRGE (pirose > 2x/sem) sem sinais de alarme deve iniciar empiricamente IBP por 4-8 semanas.\nPor que as outras estão erradas:\nA: pHmetria é para casos atípicos ou refratários.\nB: Antiácidos são para alívio sintomático esporádico.\nD: Sem sinais de alarme, não precisa de endoscopia de início em paciente jovem.\nE: B2-agonista não tem role na DRGE.\nPonto de prova: Manejo inicial da DRGE típica sem alarme.\nFlashcard sugerido: Conduta inicial para DRGE típica sem sinais de alarme? Resposta: IBP por 8 semanas.\nPérola: DRGE típica sem alarme = IBP empírico.\nArmadilha: Pedir endoscopia desnecessariamente.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando alguém sente azia frequente sem sinais preocupantes, o primeiro remédio a tentar é um comprimido que reduz o ácido do estômago, tomado por cerca de dois meses."},{"id":"b15-q016","number":16,"collectionBlock":15,"documentBlock":15,"area":"Saúde Coletiva","topic":"Ferramentas da APS","stem":"A Política Nacional de Educação Permanente em Saúde (PNEPS) compreende que a transformação nos serviços, no ensino e na condução do sistema de saúde:","options":{"A":"Tem como eixo a atualização das equipes quanto às condutas clínicas e terapêuticas em consonância com os mais recentes estudos científicos de cada especialidade médica.","B":"Deve contribuir para a melhora da relação entre as pessoas, principal problema da falta de resolutividade dos serviços, em particular, da APS.","C":"Expressa a compreensão de que a transformação nos serviços, no ensino e na condução do sistema de saúde depende fundamentalmente do aprimoramento técnico que deve ser permanente.","D":"Constitui-se em um trabalho articulado entre o sistema de saúde, em suas esferas de gestão e as instituições formadoras, com vistas à construção de uma saúde que diga respeito aos seus usuários e valorize os atores sociais do trabalho."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A PNEPS constitui um trabalho articulado entre a gestão do SUS e as instituições formadoras para transformar práticas e valorizar os atores sociais do trabalho em saúde.\nPor que as outras estão erradas:\nA/B/C: A PNEPS não foca apenas em atualização técnica, mas sim na transformação das práticas e da gestão, buscando integralidade e significância para os trabalhadores.\nPonto de prova: Conceito de Educação Permanente em Saúde.\nFlashcard sugerido: O que prega a PNEPS? Resposta: Trabalho articulado entre sistema de saúde e instituições formadoras.\nPérola: EPS conecta gestão e ensino para transformar o trabalho.\nArmadilha: Reduzir a EPS a simples cursos de atualização clínica.","tags":["Saúde Coletiva","Gestão e Educação em Saúde","Educação Permanente em Saúde","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Essa política de saúde quer unir quem cuida das pessoas com quem ensina os profissionais, para melhorar como o sistema de saúde funciona para todo mundo."},{"id":"b15-q017","number":17,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Primigesta com 38 semanas de idade gestacional é admitida no Centro Obstétrico. Realizou seis consultas pré-natais e não apresenta histórico de doenças prévias. Com 14 semanas de idade gestacional, apresentou VDRL de 1:64, tendo recebido três doses de Penicilina Benzatina, 2.400.000UI, com intervalo de uma semana entre cada dose. Parceiro não tratou sífilis por ter VDRL não reagente. Com 30 semanas de idade gestacional, apresentou título de VDRL de 1:16. Na admissão apresentava título de VDRL de 1:8. O parto foi vaginal e o recém-nascido (RN) é assintomático ao exame físico. Nesse caso, é correto presumir que se trata de mãe com sífilis:","options":{"A":"Adequadamente tratada. Solicitar VDRL em sangue periférico para o RN. Indicado tratamento para o RN com penicilina cristalina se exame reagente para qualquer titulação.","B":"Adequadamente tratada. Solicitar VDRL em sangue periférico para o RN. Indicado tratamento com penicilina cristalina para o RN se exame reagente com titulação pelo menos 2x maior que a materna.","C":"Inadequadamente tratada. Solicitar VDRL em sangue periférico para o RN. Indicado tratamento com penicilina cristalina para o RN se exame reagente com titulação pelo menos 4x maior que a materna.","D":"Inadequadamente tratada. Deve- se solicitar VDRL em sangue periférico para o RN, RaioX ossos longos e coleta de líquor com pesquisa de VDRL. Indicado tratamento com penicilina cristalina para o RN com exame reagente para qualquer titulação."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A mãe foi adequadamente tratada (3 doses de Penicilina Benzatina, com queda dos títulos de 1:64 para 1:8). O RN assintomático deve ter VDRL colhido em sangue periférico. Se for reagente, só se trata se o título for pelo menos 2x maior que o materno.\nPor que as outras estão erradas:\nA: Não se trata \"qualquer titulação\", o título do RN deve ser no mínimo 2x maior que o da mãe para justificar tratamento.\nC/D: A mãe não foi inadequadamente tratada; a queda do VDRL atesta a resposta terapêutica.\nPonto de prova: Conduta neonatal na sífilis com mãe adequadamente tratada e RN assintomático.\nFlashcard sugerido: Mãe tratada e RN assintomático, quando tratar RN? Resposta: Se VDRL do RN for pelo menos 2x maior que o materno.\nPérola: RN assintomático de mãe tratada: só trata se VDRL dobrar o da mãe.\nArmadilha: Tratar o RN com qualquer título positivo.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sífilis","Assistência ao Parto","Interpretação de Exames","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Assar bem a carne até ficar bem quente por dentro mata o parasita da toxoplasmose escondido nela, por isso essa é uma das formas de proteger o bebê durante a gravidez."},{"id":"b15-q018","number":18,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher de 44 anos, no 3º dia de pós- operatório de gastroplastia em Y de Roux por videolaparoscopia para tratamento de obesidade mórbida (IMC 44 Kg/ m2). Ao exame físico apresenta- se taquicárdica (frequência cardíaca: 140bpm), PA 140 x 85 mmHg, eupneica, murmúrios vesiculares diminuídos nas bases, abdome flácido sem sinais de irritação peritoneal. **Exames laboratoriais:** Hb: 13g/dL; Ht: 42%; Leucograma: 17,33mil/mm3; Creatinina: 1,5g/dL; Ureia: 78g/dL; PCR: 140g/dL. Qual é a principal hipótese diagnóstica e conduta?","options":{"A":"Hérnia interna (Petersen), laparoscopia.","B":"Atelectasia pulmonar, fisioterapia respiratória.","C":"Tromboembolismo pulmonar, anticoagulação terapêutica.","D":"Deiscência de anastomose, tomografia de abdome."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Febre alta, taquicardia (FC > 120bpm), descoração e PCR muito elevada (> 100 mg/L) no 3º PO de bypass são altamente sugestivos de deiscência de anastomose (fístula). A conduta é TC de abdome para confirmação.\nPor que as outras estão erradas:\nA/C: Hérnia interna e TEP não costumam causar PCR tão alta e febre no 3º PO.\nB: Atelectasia causa febre, mas não taquicardia extrema e PCR 140.\nPonto de prova: Complicações pós-bypass gástrico e interpretação de PCR.\nFlashcard sugerido: 3º PO de bypass, taquicardia e PCR > 100 indicam o quê? Resposta: Deiscência de anastomose; solicitar TC.\nPérola: PO de bypass + FC alta + PCR alto = Fístula!\nArmadilha: Atribuir a febre e taquicardia apenas a atelectasia.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Obesidade","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Se o exame de sangue mostra que a mãe respondeu bem ao remédio (os anticorpos caíram bastante) e o bebê nasceu sem sintomas, ele precisa fazer um exame de sangue e só recebe tratamento se o resultado for bem mais alto que o da mãe."},{"id":"b15-q019","number":19,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Quanto ao Helicobacter pylori nas doenças dispépticas, assinale a alternativa correspondente ao tratamento que faz parte da primeira linha.","options":{"A":"Levofloxacina e bismuto","B":"Testes fenotípicos ou genotípicos de susceptibilidade antimicrobiana","C":"Inibidor da bomba de prótons, doxiciclina e tetraciclina","D":"Inibidor da bomba de prótons isoladamente, até cessarem os sintomas","E":"Inibidor da bomba de prótons, amoxicilina e claritromicina"},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O esquema de primeira linha padrão para erradicação do H. pylori é IBP + Amoxicilina + Claritromicina por 14 dias.\nPor que as outras estão erradas:\nA/B/D: Levofloxacino e Bismuto são esquemas de segunda linha ou terapia de resgate.\nC: Doxiciclina com tetraciclina não é o esquema padrão isolado.\nPonto de prova: Esquema de erradicação do H. pylori.\nFlashcard sugerido: Qual o esquema de 1ª linha para H. pylori? Resposta: IBP + Amoxicilina + Claritromicina por 14 dias.\nPérola: H. pylori 1ª linha: IBP, Amox e Claritro.\nArmadilha: Usar levofloxacino logo de início.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Depois da cirurgia de emagrecimento, se a barriga fica bem inchada e dolorida e a pessoa fica com febre e coração acelerado, é sinal de que a costura entre o estômago e o intestino pode estar vazando — por isso é preciso fazer uma tomografia rápido."},{"id":"b15-q020","number":20,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Homem, 28 anos, previamente hígido, vem à consulta na unidade básica de saúde com queixa de tosse associada frequentemente à pirose e às vezes à regurgitação. O quadro iniciou há 4 semanas e o paciente nega emagrecimento, febre, melena, hematêmese ou disfagia. Exame físico sem particularidades. Além de educação do paciente e de medidas comportamentais, está indicado iniciar com e, caso não haja melhora dos sintomas, deve-se realizar:","options":{"A":"Inibidores de relaxamento transitório do esfincter esofagiano inferior - Phmetria de 24horas.","B":"Bloqueadores dos receptores H2 da histamina - endoscopia digestiva alta.","C":"Inibidores da bomba de prótons - Phmetria de 24 horas.","D":"Pró-cinéticos - endoscopia digestiva alta."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Paciente com DRGE típica (pirose/regurgitação) e atípica (tosse) sem sinais de alarme. Inicia-se IBP. Se os sintomas persistirem (refratários), a próxima etapa é a pHmetria esofágica (suspenso o IBP).\nPor que as outras estão erradas:\nA: Inibidores de relaxamento do EEI não são primeira linha.\nB: Bloqueadores H2 são menos potentes.\nD: Pró-cinéticos não são primeira linha.\nPonto de prova: Manejo de DRGE e conduta em caso de falha terapêutica.\nFlashcard sugerido: DRGE não respondeu ao IBP. Próximo passo? Resposta: pHmetria de 24 horas.\nPérola: IBP falhou? Mande a pHmetria.\nArmadilha: Pedir endoscopia de imediato em paciente jovem sem alarme.","tags":["Clínica Médica","Gastroenterologia","Tosse","Hemorragia Digestiva","Interpretação de Exames","Atenção Primária"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Para tratar essa bactéria do estômago, o médico geralmente usa um remédio que reduz o ácido junto com dois antibióticos diferentes, tudo ao mesmo tempo."},{"id":"b15-q021","number":21,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Pedro é recém- nascido a termo, com peso de nascimento de 3 Kg, filho de mãe que descobriu HIV na 20ª semana de gestação. Iniciou uso de TARV, assim que teve o diagnóstico. No momento do Parto, não havia registro da Carga Viral, após o início da TARV. Qual a conduta mais adequada com Pedro na maternidade e seguimento:","options":{"A":"Coletar CV na sala de parto, aguardar resultado para iniciar TARV profilática por via oral e encaminhar para seguimento, com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida.","B":"Coletar CV na sala de parto, iniciar AZT, 3TC e RAL por via oral e encaminhar para seguimento com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida.","C":"Coletar CV na sala de parto, iniciar AZT por via oral e encaminhar para seguimento com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida.","D":"Coletar CV na sala de parto, iniciar AZT, NVP por via oral e encaminhar para seguimento com coleta de nova CV com: 14 dias, na 6ª e 12ª semana de vida."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Mãe diagnosticada na gestação, sem registro de carga viral (CV) no periparto (risco assumido como moderado/alto pela ausência de comprovação de supressão). O esquema profilático para RN de risco alto/moderado é AZT + 3TC + RAL por 28 dias.\nPor que as outras estão erradas:\nC/D: AZT isolado ou com NVP é para baixo risco (CV indetectável garantida).\nPonto de prova: Profilaxia da TV do HIV em RN com risco desconhecido/alto.\nFlashcard sugerido: RN de mãe HIV+ sem CV no parto, qual profilaxia? Resposta: AZT + 3TC + Raltegravir.\nPérola: Sem CV no parto = Risco alto = AZT+3TC+RAL.\nArmadilha: Usar NVP em vez de RAL para alto risco.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quem tem azia quase todo dia, sem sinais de alerta como perda de peso ou dificuldade de engolir, deve começar tomando remédio para reduzir o ácido; se não melhorar, faz-se um exame que mede o ácido subindo pelo esôfago."},{"id":"b15-q022","number":22,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"A educação popular é um instrumento que possibilita a abordagem integral na assistência à saúde. Ela parte da concepção de que todas as pessoas têm saberes e experiências acumuladas. Por isso, as ações educativas fundamentais nesse pressuposto devem:","options":{"A":"Valorizar o conhecimento científico e tradicional, reforçando a importância de ações individuais.","B":"Construir um saber dialogado e participativo, fortalecendo o protagonismo social das pessoas envolvidas.","C":"Repassar o saber biomédico para a população, identificando, de forma objetiva, as patologias individuais.","D":"Reforçar o conhecimento dos profissionais de saúde, valorizando o papel professoral da equipe."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A educação popular visa construir um saber dialogado e participativo, fortalecendo o protagonismo social, afastando-se da mera transmissão vertical de conhecimento biomédico.\nPor que as outras estão erradas:\nA/C/D: Reforçam o modelo biomédico tradicional e o papel professoral, contradizendo a educação popular.\nPonto de prova: Conceitos de Educação Popular em Saúde.\nFlashcard sugerido: Qual a essência da educação popular em saúde? Resposta: Saber dialogado e protagonismo social.\nPérola: Educação popular é diálogo, não aula.\nArmadilha: Achar que educação popular é apenas repassar saberes médicos.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando não se sabe se a carga viral da mãe estava controlada no parto, o bebê recebe três remédios de proteção contra o HIV, por segurança extra."},{"id":"b15-q023","number":23,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Primigesta de 24 anos, vendedora, compareceu a unidade de saúde da família (USF) com os resultados de exames solicitados na primeira consulta de pré-natal, realizada havia quatro semanas, ao final do primeiro trimestre de gestação. Estava com idade gestacional de 16 semanas. Negou queixas e referiu estar em uso regular do ácido fólico e do sulfato ferroso prescritos. Disse estar preocupada com o resultado do exame de toxoplasmose. O médico verificou que a gestante apresentava IgG reagente e IgM não reagente para toxoplasmose. Assinale a opção que indica, respectivamente, o que o exame sugere e a conduta a ser tomada.","options":{"A":"Possivelmente um falso-positivo para toxoplasmose; repetir os exames e encaminhar a paciente para acompanhamento no pré-natal de alto risco. B C D","B":"Compatibilidade com toxoplasmose aguda; iniciar o tratamento específico e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","C":"Toxoplasmose pregressa; tranquilizar a paciente de que não há motivos de preocupação e orientá- la a continuar o acompanhamento habitual no pré-natal na USF.","D":"Suscetibilidade à toxoplasmose; orientar a paciente sobre medidas de prevenção e indicar que ela continue o acompanhamento no pré-natal na USF."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: IgG reagente e IgM não reagente indicam toxoplasmose pregressa (imunidade). A gestante está imune, não há risco fetal, e deve continuar o pré-natal habitual na USF.\nPor que as outras estão erradas:\nA/B/D: Não há infecção aguda nem suscetibilidade que exija medidas especiais.\nPonto de prova: Interpretação de sorologia para toxoplasmose na gestação.\nFlashcard sugerido: IgG + e IgM - na gestante indica o quê? Resposta: Toxoplasmose pregressa (imune).\nPérola: IgG + e IgM - = Passou, tá imune.\nArmadilha: Considerar infecção aguda ou pedir avidez.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Ensinar sobre saúde funciona melhor quando é uma conversa de mão dupla, valorizando o que as pessoas já sabem, em vez de só passar informação de cima para baixo."},{"id":"b15-q024","number":24,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Meningites","stem":"Uma paciente com 24 anos, estudante de medicina, procura atendimento no ambulatório de uma universidade com história de febre não aferida e mal- estar generalizado iniciados há cerca de 48 horas. Conta que hoje começou a apresentar cefaleia intensa, motivo de sua procura por assistência. Informa ter tido varicela e rubéola quando criança. Refere ter sido vacinada na infância e que, quando entrou na faculdade, tomou uma dose de dT e da vacina para hepatite B, mas não completou o esquema. Nega vacinação em campanhas, pois teve rubéola na infância. Ao exame físico, apresenta frequência respiratória de 24 incursões respiratórias por minuto, frequência cardíaca de 100 batimentos por minuto, pressão arterial de 120 × 80 mmHg, temperatura axilar de 38,8 °C; mucosas normocoradas, hipohidratadas (+1/ +4), escleróticas anictéricas; aparelho respiratório: murmúrio vesicular universalmente audível, ausência de ruídos adventícios; aparelho cardiovascular: ritmo cardíaco regular em dois tempos, bulhas normofonéticas, sem sopros ou atritos; abdome: flácido, peristáltico, sem visceromegalias. No exame neurológico está acordada, lúcida, movimenta os quatro membros, sem déficit focal aparente, com rigidez de nuca (+3/+4), sinal de Kernig e sinal de Brudzinski presentes. Não foram observadas lesões cutâneas ou mucosas. Na fundoscopia ocular: nervos óticos bem visualizados, sem alterações. Com relação à abordagem diagnóstica, assinale a opção correta.","options":{"A":"A coleta de líquido cefalorraquidiano deverá ser realizada através de punção suboccipital, pois há contraindicação para realização de punção na região lombar.","B":"O exame microscópico do líquido cefalorraquidiano, utilizando- se a coloração de Gram, que evidencie bastonetes Gram negativos, confirma o diagnóstico de meningite pneumocócica.","C":"A punção liquórica com exame da bioquímica do líquido cefalorraquidiano deverá ser realizada, pois permitirá a distinção entre infecção bacteriana e viral, o que orientará a conduta terapêutica.","D":"A paciente deverá ser submetida a um exame de imagem antes da realização da coleta de líquido cefalorraquidiano para exame diagnóstico, pois há contraindicação para realização de punção lombar."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A punção liquórica (bioquímica) permite distinguir infecção bacteriana de viral através da análise de células, glicose e proteínas, orientando a conduta. Sem sinais de focalização ou comprometimento de consciência, a PL pode ser feita sem imagem prévia.\nPor que as outras estão erradas:\nA/D: Não há indicação de punção suboccipital nem de neuroimagem prévia, pois o exame neurológico está normal.\nB: Pneumococo é coco Gram positivo, não bastonete.\nPonto de prova: Indicações de punção lombar e de imagem prévia em meningite.\nFlashcard sugerido: Quando pedir imagem antes de punção lombar? Resposta: Se houver focalização neurológica, rebaixamento de consciência ou crises.\nPérola: Neurológico normal, manda a agulha!\nArmadilha: Achar que toda PL precisa de TC prévia.","tags":["Pediatria","Saúde da Criança","Sinais Meníngeos","Síndrome Febril","Interpretação de Exames","Pediatria Ambulatorial"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Quando um exame de sangue mostra que a mãe já teve a doença há muito tempo (os anticorpos são antigos e fortes), ela está protegida e o bebê não corre perigo, então a gravidez segue normalmente."},{"id":"b15-q025","number":25,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Uma mulher com 40 anos é encaminhada da unidade básica de saúde para o ambulatório de referência em neurologia devido a cefaleia. Relata que apresenta episódios de cefaleia hemicraniana, acompanhada de náuseas e escotomas visuais, desde a adolescência, e que, aos 30 anos, fez tratamento com propranolol por 1 ano, o que reduziu significativamente o número de crises de cefaleia, que passaram a ocorrer 1 a 2 vezes no mês. Acrescenta que, no entanto, há 3 meses, a frequência dos episódios aumentou; tornaram- se diários, com despertares noturnos devido a dor, aumento da intensidade e, no momento, descreve a cefaleia como holocraniana. Nessa situação, a conduta adequada para o caso deve ser:","options":{"A":"Realizar punção lombar.","B":"Reiniciar o uso de propranolol.","C":"Solicitar ressonância magnética de encéfalo.","D":"Iniciar tratamento com amitriptilina ou outro tricíclico."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Mudança no padrão da cefaleia (tornou-se diária), despertar noturno e piora progressiva são \"red flags\" (sinais de alarme), exigindo investigação com imagem (Ressonância Magnética).\nPor que as outras estão erradas:\nA/D: Punção lombar ou amitriptilina não são condutas iniciais antes de excluir causa secundária.\nB: Propranolol não trata a dor e ignora as red flags.\nPonto de prova: Sinais de alarme (red flags) em cefaleias.\nFlashcard sugerido: Cefaleia com despertar noturno e mudança de padrão. O que fazer? Resposta: Solicitar neuroimagem (RM).\nPérola: Dor que acorda de noite é causa secundária até prova em contrário.\nArmadilha: Tratar como exacerbação de enxaqueca.","tags":["Clínica Médica","Neurologia","Cefaleia","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando a médica não encontra alteração ao examinar o paciente, ela pode colher o líquido da coluna com segurança, para saber se a infecção é causada por bactéria ou por vírus e assim escolher o tratamento certo."},{"id":"b15-q026","number":26,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Um homem com 38 anos foi encaminhado ao ambulatório de referência em infectologia do seu município devido a episódios de cefaleia, confusão mental e febre (até 38,5 °C) ocorridos há cerca de uma semana, tendo havido perda de peso no último mês (peso habitual = 70 kg). Ele relata que, no dia anterior, iniciou com rebaixamento do nível de consciência, encontrando- se letárgico no momento da consulta. Nega tosse ou diarreia. Os familiares contam que o paciente é tabagista e que faz consumo excessivo de bebida alcoólica. Os exames iniciais mostraram leucócitos: 3.200/mm3 , com 69% de neutrófilos, 21% de linfócitos e 10% de eosinófilos; anemia hipocrômica, microcítica, com anisocitose; plaquetas normais; velocidade de hemossedimentação: 120 mm na 1ª hora; ureia, creatinina, TGO/AST, TGP/ALT, eletrólitos normais. Foi realizada a análise do líquido cefalorraquidiano (LCR), que mostrou 200 leucócitos/ mm3 , com 78% de linfócitos, níveis elevados de proteína, baixos níveis de glicose e tinta nanquim negativa. Considerando-se o quadro descrito, a hipótese diagnóstica pertinente ao caso é de:","options":{"A":"Meningite tuberculosa.","B":"Meningite bacteriana.","C":"Neurocriptococose.","D":"Meningite viral."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: LCR com linfocitose, hipoglicorraquia severa e hiperproteinorraquia em paciente com AIDS e etilismo sugere fortemente meningite tuberculosa. A tinta nanquim negativa afasta criptococose.\nPor que as outras estão erradas:\nB: Bacteriana teria predomínio de neutrófilos.\nC: Neurocriptococose tem tinta nanquim positiva.\nD: Viral tem glicose normal e proteína menos elevada.\nPonto de prova: Diagnóstico diferencial de LCR na AIDS.\nFlashcard sugerido: AIDS + LCR linfocítico + glicose muito baixa + tinta nanquim negativo = ? Resposta: Meningite tuberculosa.\nPérola: Glicose lá embaixo, proteína lá em cima, linfócito: TB ou Fúngica. Nanquim negou, logo TB.\nArmadilha: Achar que no HIV só se pensa em cripto.","tags":["Clínica Médica","Neurologia","Cefaleia","Anemia","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Uma dor de cabeça que muda de padrão e passa a acordar a pessoa de madrugada é um sinal de alerta e precisa de exame de imagem para descobrir a causa, e não deve ser tratada só como uma crise mais forte de enxaqueca de sempre."},{"id":"b15-q028","number":28,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Paciente, 37 anos, sexo masculino, etilista pesado, deu entrada no PS com quadro de cefaleia, febre e confusão mental. Após exame físico e coleta de exames laboratoriais e de imagem, chegou-se ao diagnóstico de meningite bacteriana. Dentre as seguintes etiologias, qual é o agente etiológico mais importante em pacientes imunossuprimidos e principalmente nos etilistas?","options":{"A":"Listeria monocytogenes.","B":"Enterovírus.","C":"Vírus da caxumba.","D":"Streptococcus do grupo B.","E":"Citomegalovírus."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Listeria monocytogenes é um importante agente de meningite em pacientes imunossuprimidos, idosos, neonatos e especialmente em etilistas.\nPor que as outras estão erradas:\nB/C/E: Enterovírus, caxumba e CMV causam meningites virais (linfocíticas).\nD: Estreptococo do grupo B afeta mais neonatos.\nPonto de prova: Etiologia da meningite em etilistas/imunossuprimidos.\nFlashcard sugerido: Qual agente de meningite é comum em etilistas e imunossuprimidos? Resposta: Listeria monocytogenes.\nPérola: Bêbado e imunossuprimido: cuidado com a Listeria.\nArmadilha: Pensar apenas em S. pneumoniae.","tags":["Clínica Médica","Neurologia","Cefaleia","Síndrome Febril","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"No líquido da coluna dessa pessoa apareceram bem menos células de defesa e menos açúcar do que o normal, o que combina com uma infecção causada pelo bacilo da tuberculose, não com fungo (que daria outro exame positivo)."},{"id":"b15-q029","number":29,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Paciente masculino, 32 anos, procura pronto- socorro devido à algia intensa em região orbitária à direita, associada à hiperemia conjuntival, lacrimejamento e com congestão nasal ipsilateral. O paciente relata 3 crises nas últimas 12 horas e que os episódios duram alguns minutos. Refere ter feito uso de analgésicos simples, sem melhora das queixas. Nega história prévia semelhante. Quais o provável diagnóstico e o tratamento de escolha para esse caso?","options":{"A":"Cefaleia em salva: oxigênio.","B":"Cefaleia em salva: opioide.","C":"Cefaleia tensional: anti-inflamatórios.","D":"Cefaleia crônica diária: opioide.","E":"Enxaqueca: agonistas do receptor 5-HT."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Cefaleia unilateral periorbitária, de curta duração (minutos), múltiplas vezes ao dia, com sintomas autonômicos ipsilaterais é o quadro clássico de Cefaleia em Salvas. O tratamento abortivo de escolha é oxigênio 100%.\nPor que as outras estão erradas:\nB/D: Opioides não são efetivos.\nC: Tensional não tem sintomas autonômicos e é bilateral.\nE: Enxaqueca dura de 4 a 72h e não tem essa frequência diária repetida.\nPonto de prova: Diagnóstico e tratamento da Cefaleia em Salvas.\nFlashcard sugerido: Tratamento abortivo da cefaleia em salvas? Resposta: Oxigênio a 100%.\nPérola: Salva de dor no olho = O2 a 100%.\nArmadilha: Prescrever analgésicos comuns (que não funcionam).","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Pessoas que bebem muito álcool ou têm as defesas do corpo enfraquecidas correm risco extra de uma bactéria chamada Listeria causar infecção nas membranas do cérebro."},{"id":"b15-q030","number":30,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Um homem de 49 anos procura atendimento com queixa de dor epigástrica e retroesternal em queimação, diária, nos últimos 5 meses. Relata que esses sintomas parecem agravar-se quando se deita e após terminar as refeições. Ele nega disfagia ou perda de peso. Refere tosse e rouquidão pela manhã nos últimos meses. O paciente fez uso, por conta própria, de um medicamento inibidor da bomba de prótons por 1 mês, com melhora parcial dos sintomas. Ele refere ingesta ocasional de bebidas alcóolicas, mas não fuma. Ao exame físico, observa- se obesidade grau 2 e não são identificadas anormalidades cardiopulmonares ou abdominais. Considerando esse caso clínico, assinale a opção que apresenta o exame mais adequado para confirmação diagnóstica:","options":{"A":"pHmetria esofágica prolongada.","B":"Endoscopia digestiva alta.","C":"Esofagografia baritada.","D":"Manometria esofágica."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Sintomas extraesofágicos (tosse, rouquidão) com resposta parcial ao IBP. O melhor exame para confirmar DRGE com sintomas atípicos ou refratários é a pHmetria esofágica prolongada (idealmente com impedância).\nPor que as outras estão erradas:\nB: Endoscopia muitas vezes é normal em DRGE não erosiva.\nC: Esofagografia não é padrão-ouro para DRGE.\nD: Manometria não mede refluxo ácido.\nPonto de prova: Confirmação diagnóstica de DRGE atípica/refratária.\nFlashcard sugerido: DRGE com sintomas atípicos e endoscopia normal. Qual exame? Resposta: pHmetria esofágica prolongada.\nPérola: Tosse e rouquidão sem lesão na endoscopia? pHmetria prolongada.\nArmadilha: Solicitar manometria que não avalia o ácido.","tags":["Clínica Médica","Medicina Interna","Obesidade","Tosse","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Uma dor muito forte ao redor de um dos olhos, com olho vermelho, lágrimas e nariz entupido, que vai e volta várias vezes por dia, melhora rápido respirando oxigênio puro."},{"id":"b15-q031","number":31,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções na Gravidez","stem":"Homem, 52 anos, há quatro meses apresenta dor localizada no epigástrio, associada a perda de apetite e perda de 10 kg nesse período. É acordado pela dor, com alívio parcial após uso de analgésico comum. Há duas semanas percebeu aumento do número de evacuações, com fezes pastosas, sem sangue ou muco. Nega outros antecedentes. Exame físico: dor à palpação profunda do epigástrio. Sem outras anormalidades. Qual é o diagnóstico mais provável?","options":{"A":"Dispepsia funcional.","B":"Síndrome do intestino irritável.","C":"Úlcera péptica duodenal.","D":"Neoplasia de pâncreas."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Dor epigástrica irradiando para as costas, perda de peso importante e fezes pastosas (esteatorreia por má absorção) são altamente sugestivos de neoplasia de pâncreas.\nPor que as outras estão erradas:\nA/B: Dispepsia funcional e SII não causam perda de peso importante e despertar noturno.\nC: Úlcera duodenal melhora com alimentação e não costuma dar esteatorreia.\nPonto de prova: Quadro clínico do câncer de pâncreas.\nFlashcard sugerido: Dor epigástrica, perda de peso e fezes pastosas. Diagnóstico? Resposta: Neoplasia de pâncreas.\nPérola: Emagreceu, dor nas costas e fezes pastosas: pâncreas!\nArmadilha: Confundir com úlcera péptica.","tags":["Clínica Médica","Medicina Interna","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Dor na barriga que se espalha para as costas, muito emagrecimento e cocô mais gorduroso podem ser sinais de um tumor no pâncreas, órgão que ajuda a digerir a gordura da comida."},{"id":"b15-q032","number":32,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Paciente homem de 48 anos vai à consulta ambulatorial devido a quadro de queimação epigástrica diariamente, que piora após refeições e sem irradiação, vômitos ou sangramentos. Avaliado no pronto-socorro, recebeu prescrição de omeprazol 40 mg uma vez ao dia, em jejum, a qual faz uso há 4 semanas, com melhora parcial. Exames realizados no PS: Hb: 11,2 g/dL; VCM: 70 fL; HCM: 30 g/dL; Leucócitos: 7.000/mm3; Ureia: 40 mg/dL; Creatinina: 0,8 mg/dL; glicemia: 90 mg/dL. Apresenta dieta rica em produtos ultraprocessados. Pratica atividade física regular duas vezes por semana. Assinale a conduta mais adequada neste momento: <br>","options":{"A":"Aumentar a dose de omeprazol para 80 mg ao dia.","B":"Manter prescrição de omeprazol 40 mg por mais 04 semanas e explicar que a melhora ocorre após 8 semanas de tratamento.","C":"Prosseguir a investigação com endoscopia digestiva alta.","D":"Prescrever amoxicilina e levofloxacino por 10 dias na detecção de Helicobacter pylori."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Melhora parcial após 4 semanas com IBP e anemia microcítica (VCM 70, Hb 11.2) sugerem sangramento oculto, exigindo endoscopia digestiva alta para investigar lesão orgânica.\nPor que as outras estão erradas:\nA/B: Aumentar ou manter IBP sem investigar a anemia é erro grave.\nD: Tratar H. pylori empiricamente sem endoscopia é errado em pacientes com sinais de alarme (anemia).\nPonto de prova: Sinais de alarme em dispepsia (anemia).\nFlashcard sugerido: Dispepsia com anemia microcítica. Conduta? Resposta: Endoscopia digestiva alta.\nPérola: Dispepsia com anemia = Endoscopia já!\nArmadilha: Tratar empiricamente para H. pylori ignorando a anemia.","tags":["Clínica Médica","Nefrologia","Função Renal","Controle Glicêmico","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando alguém toma remédio para azia e ainda tem anemia (sangue fraco), é preciso investigar melhor com uma câmera que olha por dentro do estômago, para ver se há algo sangrando escondido."},{"id":"b15-q033","number":33,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher, 37 anos, queixa-se de fadiga, fraqueza e queda de cabelo. Refere antecedente de cirurgia bariátrica (bypass gástrico) há 4 anos. Ao exame físico apresenta- se descorada, unhas quebradiças e sem outras alterações. Assinale qual é a principal hipótese diagnóstica e o respectivo tratamento: <br>","options":{"A":"Anemia ferropriva e reposição endovenosa de ferro.","B":"Deficiência de vitamina B12 e reposição oral de complexo B.","C":"Deficiência de ácido fólico e reposição oral de polivitamínico.","D":"Deficiência proteica e suplemento oral de proteína."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Bypass em Y de Roux exclui o fundo e o corpo gástrico (local de produção de fator intrínseco) e o duodeno (local de absorção de ferro). Anemia ferropriva é a deficiência nutricional mais comum no longo prazo, manifestando-se com fadiga e unhas quebradiças.\nPor que as outras estão erradas:\nB/C/D: Vitamina B12 e ácido fólico também podem deficienciar, mas o quadro clínico e a alta prevalência apontam para ferropriva.\nPonto de prova: Complicações nutricionais pós-bypass em Y de Roux.\nFlashcard sugerido: Deficiência nutricional mais comum tardiamente após Y de Roux? Resposta: Anemia ferropriva.\nPérola: Bypass tardio: fadiga e unha fraca = Ferro.\nArmadilha: Achar que é B12 por causa da cirurgia.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois da cirurgia de emagrecimento, o intestino que absorve ferro fica sendo pulado, então é comum a pessoa ficar com sangue fraco, cansaço e unhas fracas — o tratamento é repor ferro pela veia."},{"id":"b15-q034","number":34,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma gestante primigesta, com idade gestacional de 6 semanas, vai à consulta de pré- natal para mostrar o resultado dos exames do primeiro trimestre que demonstraram suscetibilidade para toxoplasmose. Dentre as alternativas a seguir, assinale a que apresenta recomendações para evitar essa doença ao longo da gestação:","options":{"A":"Não há contraindicação em utilizar a mesma faca para cortar carnes e outros vegetais ou frutas.","B":"Toda carne deve ser cozida até atingir temperatura superior a 67 °C.","C":"Evitar qualquer tipo de carne vermelha.","D":"Durante o primeiro trimestre, deve-se evitar ingerir verduras, pois a doença é mais grave no início da gestação.","E":"Deve-se evitar contato direto com gatos, visto que a transmissão ocorre através do toque no felino."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A carne deve ser bem cozida (temperatura interna > 67°C) para garantir a morte dos cistos de Toxoplasma gondii.\nPor que as outras estão erradas:\nA: Faca de carne contamina vegetais.\nC: Pode comer carne vermelha, desde que bem cozida.\nD: Verduras devem ser bem lavadas, não evitadas.\nE: Toque no gato não transmite; a transmissão se dá pelas fezes.\nPonto de prova: Medidas de prevenção da toxoplasmose.\nFlashcard sugerido: Como evitar toxoplasmose pela carne? Resposta: Cozinhar a > 67°C.\nPérola: Carne bem passada, verdura bem lavada, gato não pega.\nArmadilha: Achar que tocar no gato transmite.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Toxoplasmose Gestacional","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"É importante cozinhar bem a carne até ficar bem quentinha por dentro, pois o calor mata o parasita da toxoplasmose que pode estar escondido nela."},{"id":"b15-q035","number":35,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Infecções Congênitas","stem":"Segundo as atuais recomendações do Ministério da Saúde, em qual situação estaria indicado o esquema composto por zidovudina, lamivudina e nevirapina como primeira escolha de profilaxia da transmissão vertical do HIV para o recém-nascido? <br>","options":{"A":"Criança nascida na 38ª semana de gestação, de parto normal, mãe HIV positivo em tratamento regular, com supressão viral a partir da 20ª semana de gestação.","B":"Criança nascida na 35ª semana de gestação, de parto cesáreo, mãe HIV positivo, com primeira carga viral do HIV indetectável na 33ª semana de gestação.","C":"Criança nascida na 39ª semana de gestação, mãe com teste rápido para o HIV reagente no momento do parto.","D":"Criança nascida na 37ª semana de gestação, mãe HIV positivo e aderente ao tratamento antirretroviral, com carga viral indetectável há 24 meses."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: RN de ALTO RISCO de TV do HIV inclui prematuros < 37 sem e/ou RN de mãe com carga viral detectável no momento do parto. O esquema indicado para alto risco é AZT + 3TC + NVP (ou RAL) por 28 dias.\nPor que as outras estão erradas:\nA/D: CV indetectável há muito tempo = baixo risco (AZT isolado).\nC: Mãe descobre no parto = alto risco, exigindo triplo. A alternativa B descreve corretamente um cenário de alto risco.\nPonto de prova: Critérios de alto risco para TV do HIV e profilaxia neonatal.\nFlashcard sugerido: RN prematuro de mãe HIV+ com CV detectável. Esquema de profilaxia? Resposta: AZT + 3TC + NVP (alto risco).\nPérola: Prematuro de mãe HIV = Alto risco = AZT + 3TC + NVP/RAL.\nArmadilha: Classificar como baixo risco indevidamente.","tags":["Pediatria","Saúde da Criança","HIV/AIDS","Transmissão Vertical","Conhecimento Conceitual","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Quando o bebê nasce antes do tempo e a mãe tem HIV, ele recebe três remédios de proteção, porque nascer prematuro já aumenta o risco de o vírus ter passado para ele."},{"id":"b15-q036","number":36,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Determinado paciente de 42 anos de idade procurou atendimento na unidade de pronto atendimento com queixa de cefaleia excruciante, unilateral, principalmente periorbitária, associada a vermelhidão ocular, lacrimejamento e rinorreia. Referiu ter apresentado episódios semelhantes anteriormente, e o último ocorreu há cerca de cinco meses, melhorando somente após oxigenioterapia a 100%. Diante da descrição, a hipótese diagnóstica compatível com o quadro é a de:","options":{"A":"Migrânea com aura.","B":"Cefaleia tensional.","C":"Migrânea sem aura.","D":"Síndrome dolorosa miofascial.","E":"Cefaleia em salvas."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O quadro clínico descrito é clássico de Cefaleia em Salvas (unilateral, periorbitária, sintomas autonômicos, duração curta e alívio com O2).\nPor que as outras estão erradas:\nA/B/C/D: Migrânea e cefaleia tensional não têm predomínio de sintomas autonômicos homolaterais nem esse padrão de alívio com oxigênio.\nPonto de prova: Reconhecimento clínico da cefaleia em salvas.\nFlashcard sugerido: Cefaleia periorbitária com lacrimejamento que melhora com O2? Resposta: Cefaleia em salvas.\nPérola: O2 é o santo remédio da cefaleia em salvas.\nArmadilha: Confundir com enxaqueca.","tags":["Clínica Médica","Neurologia","Cefaleia","Raciocínio Diagnóstico","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça forte só de um lado, com olho vermelho e nariz escorrendo, que já apareceu antes e melhorou respirando oxigênio puro, é chamada de cefaleia em salvas."},{"id":"b15-q037","number":37,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher, 30 anos, submetida a cirurgia bariátrica há 3 anos devido à obesidade mórbida. Peso pré-operatório de 135 kg e há 1 ano mantém 95 kg. No último ano, apresentou 4 infecções de via aérea superior e 1 episódio de herpes zoster em face, tratada com aciclovir. Há 2 meses, apresenta cansaço persistente, diminuição da acuidade visual, em especial noturna, e xerostomia. Nos últimos dias, notou lesão esbranquiçada na conjuntiva ocular esquerda. Qual é o diagnóstico mais provável?","options":{"A":"Herpes zoster oftálmico.","B":"Endoftalmite por cândida albicans.","C":"Deficiência de vitamina A.","D":"Síndrome de Sjögren."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Deficiência de vitamina A (lipossolúvel) após bypass (má absorção de gorduras) pode causar xeroftalmia (lesão esbranquiçada na conjuntiva - mancha de Bitot), xerostomia, diminuição da visão noturna e imunossupressão (infecções de repetição).\nPor que as outras estão erradas:\nA/B/D: Herpes, cândida e Sjögren não explicam a diminuição da visão noturna e as infecções repetidas no contexto de má absorção.\nPonto de prova: Deficiências vitamínicas pós-bariátrica.\nFlashcard sugerido: Pós-bariátrica com cegueira noturna e xeroftalmia. Diagnóstico? Resposta: Deficiência de vitamina A.\nPérola: Bariátrica enxergando mal de noite: Vitamina A.\nArmadilha: Achar que é Síndrome de Sjögren.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Obesidade","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois da cirurgia de emagrecimento, o corpo pode absorver menos uma vitamina (a vitamina A) que ajuda a enxergar à noite e a manter os olhos e a pele saudáveis — por isso a pessoa fica com visão ruim no escuro e olhos secos."},{"id":"b15-q038","number":38,"collectionBlock":15,"documentBlock":15,"area":"Medicina de Família e Comunidade","topic":"Ferramentas da APS","stem":"Pode-se afirmar a respeito de Educação em Saúde na Atenção Primária, que:","options":{"A":"Práticas educativas somente podem ser realizadas por especialistas em Medicina Família e Comunidade, por serem profissionais expertos em Atenção Primária, aptos, portanto, a elaborarem e conduzirem processos de Educação permanente.","B":"Contribui para a afirmação do SUS como uma política pública que tem proporcionado maior inclusão social, não somente por promover a apropriação do significado de saúde enquanto direito por parte da população, como também pela promoção da cidadania e da participação social.","C":"Não tem como objetivo precípuo contribuir para o controle social, embora se almeje estimular a autonomia dos usuários, a partir, principalmente, de práticas educativas exclusivamente ensinadas por médicos de Família e Comunidade.","D":"Práticas educativas tradicionais não podem ser transformadas em práticas pedagógicas que mobilizam a defesa do SUS na Atenção Primária, porque esta é uma prerrogativa exclusiva das categorias sindicais, responsáveis por movimentos sociais que lutam em prol de dignidade."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A educação em saúde contribui para a inclusão social e controle social, apropriando o significado de saúde como direito e promovendo cidadania.\nPor que as outras estão erradas:\nA/C/D: Práticas educativas não são exclusivas de especialistas e podem (devem) ser transformadas em práticas pedagógicas de defesa do SUS.\nPonto de prova: Princípios da Educação em Saúde na APS.\nFlashcard sugerido: Qual o impacto da educação em saúde no SUS? Resposta: Promoção da cidadania e apropriação da saúde como direito.\nPérola: Educação em saúde empodera o usuário.\nArmadilha: Restringir educação em saúde a médicos de família.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Ensinar sobre saúde na comunidade ajuda as pessoas a entenderem que cuidar da própria saúde é um direito delas, participando ativamente das decisões, e não só recebendo ordens do médico."},{"id":"b15-q039","number":39,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Gestante, 26 anos de idade, tercigesta e secundípara (partos normais), sem comorbidades, vem em consulta de rotina pré- natal com 11 semanas e com o seguinte resultado de sorologia para toxoplasmose: IGM: reagente e IGG reagente. Feito teste de avidez - baixa avidez. Com relação ao resultado do teste de avidez, identifique a alternativa correta:","options":{"A":"A gestante tem indicação de uso de Espiramicina.","B":"A gestante tem indicação de uso de Penicilina Benzatina.","C":"Não tem indicação de terapia medicamentosa no momento, pois o teste de avidez veio baixo.","D":"A gestante tem indicação de uso de Ganciclovir."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Baixa avidez no 1º trimestre indica infecção recente (adquirida há menos de 4 meses), sugerindo infecção aguda na gestação. Indica-se iniciar Espramicina para prevenir transmissão vertical.\nPor que as outras estão erradas:\nB: Penicilina é para sífilis.\nC: Há indicação de tratamento (espiramicina), pois é aguda.\nD: Ganciclovir é para CMV.\nPonto de prova: Conduta na toxoplasmose aguda no 1º trimestre (baixa avidez).\nFlashcard sugerido: Toxoplasmose com baixa avidez no 1º trimestre. Tratamento? Resposta: Espiramicina.\nPérola: Baixa avidez = Aguda = Espiramicina.\nArmadilha: Esperar para tratar.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Avidez de IgG","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando os anticorpos da mãe estão 'fracos e novinhos' (baixa avidez), isso mostra que a infecção é recente, então ela precisa começar logo um remédio para proteger o bebê."},{"id":"b15-q040","number":40,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Gestante, 26 anos de idade, tercigesta e secundípara (partos normais), sem comorbidades, vem em consulta de rotina pré- natal com 11 semanas e com o seguinte resultado de sorologia para toxoplasmose: IGM: reagente e IGG reagente. Feito teste de avidez - baixa avidez. Indique o procedimento, no segundo trimestre, que poderá avaliar presença de infecção fetal, através do PCR (reação em cadeia de polimerase):","options":{"A":"Biópsia de vilo corial.","B":"Amniocentese.","C":"Culdocentese.","D":"Biópsia de placenta."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Para avaliar infecção fetal por PCR no 2º trimestre, realiza-se a amniocentese (coleta de líquido amniótico), idealmente após 18 semanas e pelo menos 4 semanas após a infecção materna.\nPor que as outras estão erradas:\nA: Biópsia de vilo corial é 1º trimestre.\nC/D: Culdocentese e biópsia de placenta não são métodos padrão.\nPonto de prova: Diagnóstico fetal da toxoplasmose.\nFlashcard sugerido: Como diagnosticar toxoplasmose fetal no 2º trimestre? Resposta: PCR no líquido amniótico (amniocentese).\nPérola: PCR fetal no toxo = Amniocentese.\nArmadilha: Pedir biópsia de vilo corial.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Parada Cardiorrespiratória","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Para ver se o bebê pegou a doença ainda dentro da barriga, o médico coleta um pouco do líquido que envolve o bebê (líquido amniótico) e faz um exame bem sensível nele."},{"id":"b15-q041","number":41,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Gestante, 26 anos de idade, tercigesta e secundípara (partos normais), sem comorbidades, vem em consulta de rotina pré- natal com 11 semanas e com o seguinte resultado de sorologia para toxoplasmose: IGM: reagente e IGG reagente. Feito teste de avidez: baixa avidez. Em caso de PCR positivo (sugerindo infecção fetal), identifique a terapia medicamentosa indicada para o tratamento da infecção fetal nesse caso.","options":{"A":"Penicilina Benzatina, espiramicina e ácido folínico.","B":"Sulfametoxazol, trimetoprima e ácido folínico.","C":"Metronidazol e clindamicina e ácido folínico.","D":"Sulfadiazina, pirimetamina e ácido folínico."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Confirmada a infecção fetal, o tratamento de escolha é a associação de Sulfadiazina + Pirimetamina + Ácido folínico (esquema tríplice), para tratar o feto.\nPor que as outras estão erradas:\nA/B/C/E: Penicilina, SMX-TMP, Metronidazol e Pirazinamida não são usados para toxoplasmose.\nPonto de prova: Tratamento da toxoplasmose fetal.\nFlashcard sugerido: Esquema para toxoplasmose fetal confirmada? Resposta: Sulfadiazina + Pirimetamina + Ácido folínico.\nPérola: Feto infectado: Sulfadiazina, Pirimetamina e Ác. Fólico.\nArmadilha: Usar espiramicina (que não trata o feto, só previne).","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Parada Cardiorrespiratória","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando se confirma que o bebê pegou a infecção dentro da barriga, usa-se uma combinação de três remédios que atravessam a placenta e tratam diretamente o bebê."},{"id":"b15-q042","number":42,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Cefaleia é uma queixa extremamente comum nos setores de emergência e consultórios médicos. Assinale o tipo de dor de cabeça que tem maior prevalência no sexo masculino:","options":{"A":"Cefaleia tipo tensional.","B":"Cefaleia em salvas.","C":"Migrânea com aura.","D":"Hemicrania paroxística."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A Cefaleia em Salvas tem prevalência significativamente maior no sexo masculino.\nPor que as outras estão erradas:\nA/C/D: Tensional e Migrânea são mais prevalentes em mulheres.\nPonto de prova: Epidemiologia das cefaleias primárias.\nFlashcard sugerido: Qual cefaleia primária predomina em homens? Resposta: Cefaleia em salvas.\nPérola: Mulher tem enxaqueca, homem tem salvas.\nArmadilha: Achar que tensional é de homem.","tags":["Clínica Médica","Neurologia","Cefaleia","Epidemiologia","Epidemiologia Clínica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"A dor de cabeça em salvas, com crises fortes de um lado só, aparece com mais frequência em homens do que em mulheres."},{"id":"b15-q043","number":43,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Uma mulher com 21 anos apresenta história de cefaleia hemicraniana, pulsátil, precedida por escotomas visuais, de duração de 6 a 10 horas, com fono e fotofobia, com pelo menos um episódio ao mês nos últimos 10 anos. Relata que a privação de sono desencadeia o quadro e que obtém melhora parcial da cefaleia após ingerir analgésico comum. Nega febre ou alteração das características de cefaleia recentemente. Nega outros sintomas associados. Ao exame físico, apresenta bom estado geral, fácies de dor, está hidratada, corada, com frequência cardíaca de 90 bpm e pressão arterial de 130 x 80 mmHg. Não apresenta alterações no aparelho cardiovascular nem no respiratório. O exame neurológico da paciente encontra-se normal. Diante desse quadro clínico, quais são, respectivamente, a hipótese diagnóstica e a conduta adequada para a paciente?","options":{"A":"Migrânea; indicar uso de triptano.","B":"Cefaleia tensional; indicar uso de relaxante muscular.","C":"Cefaleia em salvas; prescrever uso de oxigênio a 100%.","D":"Cefaleia por malformação vascular; encaminhar à neurologia."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O quadro é clássico de Enxaqueca com aura. O tratamento abortivo de escolha são os triptanos.\nPor que as outras estão erradas:\nB: Tensional não tem aura nem é pulsátil intensa.\nC: Em salvas é mais curta e com autonômicos.\nD: Não há sinais de malformação.\nPonto de prova: Diagnóstico e tratamento da enxaqueca com aura.\nFlashcard sugerido: Enxaqueca com aura, qual o tratamento abortivo? Resposta: Triptano.\nPérola: Migrânea pulsátil com aura: Triptano.\nArmadilha: Prescrever oxigênio (que é para cefaleia em salvas).","tags":["Clínica Médica","Neurologia","Cefaleia","Síndrome Febril","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Dor de cabeça latejante de um lado só, que vem com luzes ou pontos brilhantes antes de começar, enjoo e incômodo com luz e barulho, é a enxaqueca — e o remédio específico para essas crises se chama triptano."},{"id":"b15-q044","number":44,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma gestante com 12 semanas de gestação comparece ao centro de saúde para mostrar os exames realizados e apresenta sorologia para toxoplasmose com IGM positiva e IGG negativa. Nesse momento, a conduta adequada é:","options":{"A":"Iniciar espiramicina e solicitar teste de avidez para toxoplasmose e, se a avidez for alta, considerar infecção recente.","B":"Iniciar a espiramicina e solicitar teste de avidez para toxoplasmose e, se a avidez for baixa, considerar infecção recente.","C":"Iniciar espiramicina e solicitar nova sorologia (IGG e IGM) em três semanas e, se IGG positivar, considerar infecção recente.","D":"Não iniciar tratamento e solicitar nova sorologia (IGG e IGM) em seis a oito semanas e, se IGG positivar, iniciar espiramicina."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: IgM positivo e IgG negativo pode ser infecção muito recente ou falso positivo. Inicia-se espiramicina e pede-se nova sorologia em 2-3 semanas. Se a IgG positivar, confirma a soroconversão.\nPor que as outras estão erradas:\nA/B: O teste de avidez não é útil aqui porque não há IgG.\nD: Não iniciar tratamento está errado pelo risco de transmissão.\nPonto de prova: Interpretação de sorologia IgM + isolado na gestação.\nFlashcard sugerido: Gestante com IgM + e IgG -. O que fazer? Resposta: Iniciar espiramicina e repetir sorologia em 3 semanas.\nPérola: IgM + sem IgG = soroconvertendo; trate e repita.\nArmadilha: Solicitar teste de avidez (não serve sem IgG).","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando um exame de sangue positivo para uma doença não vem acompanhado de outro anticorpo esperado, o médico repete o exame semanas depois e começa um remédio de proteção enquanto espera, para não arriscar o bebê."},{"id":"b15-q045","number":45,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Um homem de 34 anos com história de enxaqueca desenvolve hemiparesia esquerda aguda juntamente com uma cefaleia pulsátil unilateral. A dor de cabeça desaparece em 6 horas, embora a fraqueza persista pelas 24 horas seguintes. A irmã do paciente já sofreu episódios semelhantes. Qual das seguintes afirmações é verdadeira sobre o diagnóstico subjacente?","options":{"A":"Há presença de ponta-onda lenta no eletroencefalograma.","B":"A doença é sensível à indometacina.","C":"A doença está associada à pleocitose no líquor.","D":"A doença está associada a mutações nos genes que codificam canais de cálcio.","E":"A doença é uma herança autossômica recessiva."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O quadro descreve Enxaqueca Hemiplégica Familiar, que está associada a mutações genéticas, mais comumente nos genes que codificam canais de cálcio.\nPor que as outras estão erradas:\nA: EEG é normal (não é epilepsia).\nB: Indometacina é para hemicrania paroxística.\nC: Pleocitose sugere outras condições.\nE: É herança autossômica dominante.\nPonto de prova: Genética da enxaqueca hemiplégica familiar.\nFlashcard sugerido: Enxaqueca hemiplégica familiar está associada a mutação em quais genes? Resposta: Canais de cálcio.\nPérola: Migrânea hemiplégica familiar = defeito no canal de cálcio.\nArmadilha: Confundir com epilepsia ou indicar indometacina.","tags":["Clínica Médica","Neurologia","Déficit Neurológico Focal","Cefaleia","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Esse tipo raro de enxaqueca, que causa fraqueza de um lado do corpo e roda na família, acontece por causa de um defeito genético em uma peça que controla a passagem de cálcio nas células nervosas."},{"id":"b15-q046","number":46,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Uma mulher de 50 anos apresentou- se com forte dor de cabeça e letargia, febril e com rigidez de nuca ao exame. A tomografia computadorizada de crânio estava normal. Uma amostra de seu líquido cefalorraquidiano é mostrada a seguir. Qual das alternativas apresentadas é a melhor conduta nesse momento?","options":{"A":"Ecocardiograma transesofágico.","B":"Ressonância Magnética Cerebral.","C":"Angiografia.","D":"Iniciar ceftriaxona e vancomicina.","E":"Iniciar dexametasona e não iniciar antibióticos até que as hemoculturas estejam completas."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: D.\nPor que está certa: O quadro e o LCR indicam meningite bacteriana grave. A conduta imediata é iniciar antibioticoterapia empírica de amplo espectro (Ceftriaxona + Vancomicina), sem aguardar culturas.\nPor que as outras estão erradas:\nA/B/C: Exames de imagem atrasam o tratamento.\nE: Não iniciar antibióticos é erro grave.\nPonto de prova: Conduta emergencial em meningite bacteriana.\nFlashcard sugerido: Suspeita de meningite bacteriana grave. Conduta imediata? Resposta: Ceftriaxona + Vancomicina EV.\nPérola: Meningite bacteriana: antibiótico não pode esperar.\nArmadilha: Aguardar culturas para tratar.","tags":["Clínica Médica","Medicina Interna","Neuroimagem","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Quando uma pessoa está com dor de cabeça forte, febre e sonolência, e o exame do líquido da coluna mostra sinais de infecção grave, o médico não espera resultado de nenhum outro exame para começar os antibióticos na veia."},{"id":"b15-q047","number":47,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Recém-nascido (RN) com 35 semanas de idade gestacional e 1900 g é atendido em sala de parto. A mãe foi diagnosticada com HIV durante a gestação e refere que iniciou TARV com 30 semanas. Diante risco de transmissão vertical, a profilaxia adequada para esse recém-nascido é:","options":{"A":"Zidovudina e lamivudina por 28 dias e nevirapina por 14 dias.","B":"Zidovudina, lamivudina e raltegravir por 28 dias.","C":"Zidovudina por 28 dias.","D":"Zidovudina, lamivudina e nevirapina por 28 dias."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Prematuro < 37 semanas é critério de ALTO RISCO para TV do HIV. O esquema profilático para alto risco é AZT + 3TC + NVP (ou RAL) por 28 dias.\nPor que as outras estão erradas:\nC: AZT isolado é para baixo risco.\nPonto de prova: Profilaxia da TV do HIV em RN prematuro (alto risco).\nFlashcard sugerido: RN prematuro de mãe HIV+. Profilaxia? Resposta: AZT + 3TC + NVP por 28 dias.\nPérola: Prematuro de mãe HIV: 3 drogas (AZT+3TC+NVP/RAL).\nArmadilha: Usar AZT isolado por ser RN de mãe tratada.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Um bebê que nasce bem pequeno e antes do tempo, de mãe que só começou a tomar remédio contra o HIV depois da metade da gravidez, também recebe três remédios de proteção, porque nascer cedo aumenta o risco."},{"id":"b15-q048","number":48,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Cefaleias","stem":"Clínica Médica - Neurologia (CM) Uma paciente com 38 anos de idade chega para consulta em uma unidade básica de saúde com queixa de cefaleia há três semanas, temporal à direita, de caráter contínuo, pulsátil, intensidade de 9 em 10, sem melhora com uso de analgésicos comuns ou opioides. Relata que apresenta despertar noturno devido à dor e que não há fatores de melhora ou de piora da dor. Nega febre, conta que apresenta ciclo menstrual regular e que faz uso regular de anticoncepcional oral combinado há 9 anos. Acrescenta que, há 15 anos, tem migrânea perimenstrual, com alívio da dor com analgésicos simples, que é hipertensa há dois anos, obtendo boa resposta ao tratamento com atenolol 50 mg/dia e hidroclorotiazida 25 mg/dia. Ao exame físico, registram-se: FC de 76 bpm, FR de 18 irpm, PA de 144 × 96 mmHg. A paciente apresenta fácies de dor, corada, hidratada, eupneica, acianótica e anictérica. Não apresentam alterações os resultados dos exames cardiovascular, respiratório e abdominal, assim como o de pares cranianos e de fundo de olho, registrando-se ainda ausência de rigidez nucal. Considerando- se esse caso clínico, é correto afirmar que se deve:","options":{"A":"Realizar tomografia de crânio com contraste, pois a paciente apresenta sinais de alerta.","B":"Introduzir nova medicação anti-hipertensiva, com retorno ambulatorial em duas semanas.","C":"Substituir a medicação anticoncepcional oral para uma com menor concentração de progesterona.","D":"Descartar neoplasia intracraniana ou glaucoma, já que o exame de fundo de olho se encontra normal."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Despertar noturno é sinal de alarme (red flag). Além disso, o uso de ACO combinado é fator de risco vascular. A conduta é realizar TC de crânio com contraste.\nPor que as outras estão erradas:\nB/C/D: Ignoraram o sinal de alarme.\nPonto de prova: Sinais de alarme em cefaleias e indicação de neuroimagem.\nFlashcard sugerido: Cefaleia com despertar noturno. Conduta? Resposta: Neuroimagem (TC com contraste).\nPérola: Despertar noturno = Red flag = Imagem.\nArmadilha: Focar apenas na enxaqueca prévia da paciente.","tags":["Ginecologia e Obstetrícia","Ginecologia","Cefaleia","Ciclo Menstrual","Conduta Terapêutica","Atenção Primária"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça forte, de um lado só, que acorda a pessoa à noite, é um sinal de alerta que precisa ser investigado com exame de imagem da cabeça, mesmo que a pessoa já tenha enxaqueca de outras vezes."},{"id":"b15-q049","number":49,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma primigesta com 30 anos de idade, na oitava semana de gestação, comparece à consulta de pré-natal relatando estar apreensiva devido ao resultado de alguns exames laboratoriais, que acusaram IgG e IgM positivos para toxoplasmose. Considerando-se esse caso, que conduta deve ser adotada nesse momento?","options":{"A":"Repetir, em três meses, os exames de dosagens de IgG e IgM.","B":"Solicitar teste de avidez para IgG para definir a próxima conduta.","C":"Programar cordocentese após 16ª semana de gestação para o diagnóstico.","D":"Iniciar o tratamento medicamentoso com esquema tríplice para toxoplasmose."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Gestante no 1º trimestre com IgG e IgM positivos. O próximo passo para saber se a infecção foi recente é solicitar o teste de avidez do IgG.\nPor que as outras estão erradas:\nA: Repetir em 3 meses atrasa o diagnóstico.\nC: Cordocentese não é conduta inicial.\nD: Não se inicia esquema tríplice sem confirmar infecção fetal.\nPonto de prova: Conduta inicial frente a IgG/IgM positivos no 1º trimestre.\nFlashcard sugerido: Gestante no 1º trimestre com IgG e IgM +. O que pedir? Resposta: Teste de avidez do IgG.\nPérola: IgM + no 1º tri: Avidez.\nArmadilha: Iniciar Pirimetamina logo de cara.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Pré-Natal","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando os dois exames de sangue da toxoplasmose dão positivos logo no começo da gravidez, o próximo passo é pedir um exame que mostra se os anticorpos são recentes ou antigos, para decidir o que fazer."},{"id":"b15-q050","number":50,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções Congênitas","stem":"RN de termo, 36 horas de vida, apresentando perímetro cefálico de 29 cm, restrição de crescimento intrauterino, evoluindo com icterícia e hepatomegalia. Coletados exames laboratoriais, evidenciando plaquetopenia. Nas avaliações complementares, evidenciada coriorretinite e calcificações intracerebrais periventriculares. Estes achados sugerem infecção congênita por:","options":{"A":"Zikavirose congênita.","B":"Toxoplasmose congênita.","C":"Rubéola congênita.","D":"Citomegalovirose congênita."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A tetrada de infecção congênita por CMV inclui petéquias/trombocitopenia, hepatoesplenomegalia/icterícia, calcificações cerebrais periventriculares e coriorretinite/surdez.\nPor que as outras estão erradas:\nA: Toxo tem calcificações difusas e hidrocefalia.\nB: Sífilis dá pseudoparalisia e rinite.\nC: Rubéola afeta coração, olho e ouvido.\nPonto de prova: Achados clínicos de CMV congênito.\nFlashcard sugerido: RN com plaquetopenia, hepatite e calcificações periventriculares. Qual infecção? Resposta: Citomegalovírus (CMV).\nPérola: Calcificação periventricular = CMV.\nArmadilha: Confundir calcificações periventriculares (CMV) com difusas (Toxo).","tags":["Clínica Médica","Medicina Interna","Plaquetopenia","Interpretação de Exames","Período Neonatal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Um bebê que nasce pequeno para o tempo de gravidez, com cabeça inchada por líquido, calcificações espalhadas no cérebro e olho de peixe (coriorretinite), pega essas alterações de uma infecção chamada citomegalovírus, pega dentro da barriga da mãe."},{"id":"b15-q051","number":51,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Um recém-nascido (RN) de 24 horas de vida é avaliado em 17/12/2023. Filho de mãe com diagnóstico de sífilis durante a gestação, tratada com 3 doses de penicilina benzatina nas datas de 27/11/2023, 04/12/2023 e 11/12/2023. VDRL antes do tratamento com titulação 1:64. Seu parceiro também foi tratado. Ao exame físico, o RN está em bom estado geral e sem alterações. Realizados exames na maternidade: VDRL (mãe): 1:16; VDRL (RN): 1:4; Líquor (RN): 17 células (predomínio linfomonocitário), 89 mg/ dL de proteinorraquia, 55 mg/ dL de glicorraquia; Hemograma (RN) sem alterações; Radiografia de ossos longos (RN) sem alterações; Radiografia de tórax (RN) sem alterações. Considerando as informações apresentadas e o protocolo vigente de sífilis congênita do Ministério da Saúde, é correto afirmar que esse RN apresenta:","options":{"A":"Sífilis congênita descartada, sem necessidade de tratamento.","B":"Exposição à sífilis, com necessidade de penicilina benzatina dose única.","C":"Sífilis congênita recente com neurossífilis, com necessidade de tratamento com penicilina cristalina por 10 dias.","D":"Sífilis congênita recente sem neurossífilis, com necessidade de tratamento com penicilina procaína ou cristalina por 10 dias.","E":"Sífilis congênita tardia sem neurossífilis, com necessidade de tratamento com penicilina benzatina dose única."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O RN tem líquor alterado (17 céls, 89 prot), configurando Sífilis Congênita com Neurossífilis. O tratamento adequado é Penicilina Cristalina EV por 10 dias.\nPor que as outras estão erradas:\nA/B/C: Se há alteração no líquor, exige-se Penicilina Cristalina EV por 10 dias. Benzatina ou Procaína não tratam adequadamente o SNC.\nPonto de prova: Tratamento da sífilis congênita com neurossífilis.\nFlashcard sugerido: Sífilis congênita com líquor alterado. Tratamento? Resposta: Penicilina Cristalina EV por 10 dias.\nPérola: Líquor alterado na sífilis: só Cristalina EV 10d.\nArmadilha: Usar Penicilina Benzatina porque o RN está assintomático clinicamente.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sífilis","Interpretação de Exames","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Quando o exame do líquido da coluna do bebê está alterado, mesmo que a mãe tenha sido bem tratada para sífilis, o bebê precisa de um antibiótico mais forte, tomado na veia, por mais dias."},{"id":"b15-q052","number":52,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Uma paciente de 46 anos deu entrada no Pronto Socorro com história de cefaleia holocraniana de leve intensidade há duas semanas. Há uma semana, houve intensificação da cefaleia e surgimento de febre baixa diária. Ao exame, a paciente se encontrava febril, sonolenta e com rigidez de nuca leve. A tomografia computadorizada do crânio revelou discreto espessamento meníngeo. Em seguida, a paciente foi submetida à punção liquórica, sendo obtido líquido levemente turvo e xantocrômico, com pressão de abertura de 22 cm de água, 250 células/mm³ (40% neutrófilos, 40% de linfócitos e 20% de monócitos), proteínas de 550 mg/ dl e glicose de 10 mg/ dl. Assinale a opção que contenha doenças que melhor justificam os achados liquóricos desta paciente:","options":{"A":"Meningite viral e meningite fúngica.","B":"Meningite viral e meningite bacteriana.","C":"Meningite tuberculosa e meningite fúngica.","D":"Meningite tuberculosa e meningoencefalite herpética."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: LCR com predomínio misto, glicose muito baixa e proteína muito alta é característico de Meningite Tuberculosa. Meningite fúngica também cursa com hipoglicorraquia e linfocitose.\nPor que as outras estão erradas:\nA/B/D: Viral tem glicose normal. Bacteriana tem predomínio absoluto de neutrófilos.\nPonto de prova: Diagnóstico diferencial de LCR.\nFlashcard sugerido: LCR com glicose muito baixa e predomínio linfocítico? Resposta: Tuberculosa ou fúngica.\nPérola: Glicose no fundo do poço: Tuberculose ou Fungo.\nArmadilha: Achar que predomínio de linfócito é só vírus.","tags":["Clínica Médica","Neurologia","Cefaleia","Síndrome Febril","Interpretação de Exames","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Quando aparecem muitas células de defesa no líquido da coluna, junto com proteína alta e açúcar muito baixo, isso costuma indicar uma infecção mais grave, como tuberculose ou um fungo, e não uma infecção viral comum."},{"id":"b15-q053","number":53,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher, 32 anos de idade, com obesidade grau III (IMC de 46 kg/m2 ), foi submetida a bypass gástrico em Y de Roux por videolaparoscopia. No primeiro dia pós-operatório, encontra-se deitada. Ao exame físico, apresentou bom estado geral com FC de 113 bpm, PA de 110x60 mmHg, FR de 22 ipm, saturação de oxigênio de 92%; ausculta pulmonar diminuída nas bases; abdome flácido, pouco doloroso à palpação profunda, com ruídos hidroaéreos presentes e com curativos secos. O dreno abdominal exteriorizado em hipocôndrio esquerdo está com débito hemático em pequena quantidade. Qual é a melhor conduta neste momento?","options":{"A":"Abertura de protocolo de sepse e transferência para UTI.","B":"Angiotomografia de tórax para investigar tromboembolismo pulmonar.","C":"Otimizar analgesia e fisioterapia motora/respiratória.","D":"Tomografia de abdome com contraste via oral."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: No 1º PO de videolaparoscopia, febre baixa, ausculta diminuída e SatO2 levemente baixa sugerem atelectasia basal por dor. A conduta é otimizar analgesia e fisioterapia.\nPor que as outras estão erradas:\nA/B/D: Não há sinais de sepse, TEP ou fístula (abdome flácido e bom estado geral).\nPonto de prova: Complicações pulmonares pós-cirurgia bariátrica.\nFlashcard sugerido: 1º PO de cirurgia com febre baixa e murmúrios diminuídos. Conduta? Resposta: Fisioterapia e analgesia.\nPérola: Febre no 1º PO = Atelectasia até prova em contrário.\nArmadilha: Achar que é fístula ou sepse.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Obesidade","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"No primeiro dia depois de uma cirurgia de estômago, quando a pessoa respira mais rápido e o coração bate um pouco mais rápido, mas a barriga está bem, geralmente é o pulmão que precisa de fisioterapia para respirar melhor, e não uma complicação grave."},{"id":"b15-q054","number":54,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções Congênitas","stem":"A infecção congênita mais relacionada à retinocoroidite e à hiperproteinoraquia é:","options":{"A":"Toxoplasmose congênita.","B":"Citomegalovírus.","C":"Rubéola congênita.","D":"Sífilis congênita."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A toxoplasmose congênita cursa frequentemente com retinocoroidite e, quando há acometimento do SNC, gera líquor com hiperproteinorraquia.\nPor que as outras estão erradas:\nB/C/D: CMV e Rubéola causam mais alterações auditivas; Sífilis não tem essa associação clássica.\nPonto de prova: Sequelas e LCR na toxoplasmose congênita.\nFlashcard sugerido: Retinocoroidite + hiperproteinoraquia em RN? Resposta: Toxoplasmose congênita.\nPérola: Toxo no olho e na proteína do LCR.\nArmadilha: Confundir com CMV.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"A toxoplasmose pega os olhos do bebê e deixa a proteína do líquido da coluna alta quando afeta o cérebro, sendo essa combinação bem característica dessa doença."},{"id":"b15-q055","number":55,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Homem, 45 anos de idade, obeso grau 3, IMC atual de 65Kg/ m2 (mas já perdeu 38Kg de seu peso máximo). Diabético e hipertenso. Foi submetido a cirurgia bariátrica pela técnica de bypass gástrico em Y de Roux por via laparoscópica. A informação é que sua cirurgia durou mais de três horas por dificuldade técnica em vista de aderências na cavidade abdominal devido colecistectomia realizada por via aberta há 10 anos. Você, como médico hospitalista, foi avaliar o paciente no segundo dia de pós- operatório. O mesmo queixava- se de dor em região dorsal bilateral e fraqueza. Negava febre, dispneia, dor abdominal, disuria, coluria ou icterícia, mas apresentava urina mais escura. Pensando no diagnóstico mais provável, qual deve ser a conduta para confirmar este diagnóstico e terapia inicial adequada?","options":{"A":"Solicitar bilirrubinas e enzimas canaliculares hepáticas, aumentar a hidratação do paciente e programar colangiorresonância.","B":"Solicitar urocultura e hemograma e iniciar antibioticoterapia com cobertura para gram negativos.","C":"Solicitar creatinofosfoquinase sérica, aumentar a hidratação do paciente e iniciar bicarbonato de sódio endovenoso.","D":"Solicitar tomografia de abdome total, iniciar antibioticoterapia com cobertura para gram negativos e acionar a equipe cirúrgica."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Cirurgia longa, obesidade e urina escura (mioglobinúria) em PO sugerem Rabdomiólise. A conduta é solicitar CPK, hidratar vigorosamente e alcalinizar a urina.\nPor que as outras estão erradas:\nA/B/D: Bilirrubinas e TC não são o foco diante da urina escura após cirurgia longa.\nPonto de prova: Rabdomiólise no pós-operatório.\nFlashcard sugerido: PO longo com urina escura. Qual exame e conduta? Resposta: CPK, hidratar e bicarbonato.\nPérola: PO longo com urina tipo coca-cola: CPK e hidratação.\nArmadilha: Achar que é lesão renal ou colestase.","tags":["Cirurgia","Cirurgia Geral","Obesidade","Cirurgia Bariátrica","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois de uma cirurgia bem demorada, se a pessoa acorda com dor nas costas e xixi mais escuro, pode ser que os músculos tenham sofrido demais durante a operação (rabdomiólise) — o tratamento é hidratar bastante e dar um remédio que protege os rins."},{"id":"b15-q056","number":56,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Mulher de 38 anos de idade foi trazida para a Unidade de Pronto Atendimento (UPA) onde você é o médico de plantão. O acompanhante refere que a mesma foi submetida à cirurgia bariátrica (não sabe qual a técnica operatória realizada) há 36 dias. Vem evoluindo com vômitos de repetição e precisou ser levada diversas vezes na mesma UPA para receber hidratação endovenosa. Na última semana apresentou fraqueza, parestesias nos pés e dores musculares. Há dois dias começou a reclamar que a visão estava ficando turva (SIC) e como acordou confusa no dia de hoje, o acompanhante a trouxe. Ao exame físico, apresentava-se estável hemodinamicamente e com índice de 14 na Escala de Coma de Glasgow. Qual das alternativas abaixo está CORRETA, com relação ao quadro da paciente?","options":{"A":"A mesma deve receber hidratação endovenosa e ser encaminhada prontamente para um serviço terciário de urgência para realização de uma tomografia de crânio.","B":"A fisiopatologia deste quadro está mais relacionada aos vômitos de repetição e não tanto ao tipo de cirurgia bariátrica realizada.","C":"É prioritário tentar descobrir qual foi a técnica cirúrgica a qual a paciente foi submetida, pois depende disto para se chegar ao diagnóstico e assim tratar o quadro.","D":"Pensando no diagnóstico de hipoglicemia secundária a provável síndrome de dumping. Recomenda se infundir imediatamente solução glicosada endovenosa."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro neurológico associado a vômitos persistentes pós-bariátrica sugere Encefalopatia de Wernicke (deficiência de vitamina B1). A fisiopatologia está ligada aos vômitos, independentemente da técnica.\nPor que as outras estão erradas:\nA/C/D: O tratamento com Tiamina não depende da técnica e não é hipoglicemia.\nPonto de prova: Complicações neurológicas pós-bariátrica.\nFlashcard sugerido: Pós-bariátrica com vômitos e confusão. Causa? Resposta: Deficiência de tiamina (Wernicke).\nPérola: Bariátrica vomitando e confusa: B1.\nArmadilha: Tentar descobrir a técnica cirúrgica em vez de tratar a deficiência.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois de uma cirurgia de emagrecimento, vômitos que não param podem fazer faltar uma vitamina do complexo B chamada tiamina, causando fraqueza, formigamento, visão embaçada e confusão mental — o tratamento é repor essa vitamina rapidamente."},{"id":"b15-q057","number":57,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Um paciente de 46 anos foi levado ao pronto- socorro por seus familiares por ter apresentado **crise convulsiva** em sua residência. Segundo o relato, ele iniciara, **há 4 dias, um quadro de cefaleia de forte intensidade, com alterações comportamentais e febre alta**. Ao exame, encontrava-se desorientado, sonolento e com **hemiparesia à esquerda**. A pressão arterial era de 110 x 88 mmHg e frequência cardíaca, de 98 batimentos por minuto. Foi realizada uma ressonância nuclear magnética, em que foram evidenciadas áreas de hiperintensidade nos lobos temporais bilateralmente. Em seguida, foi realizada uma punção liquórica. No líquor, foi encontrado um **aumento de proteínas e leucócitos (com predomínio de linfócitos)**. Os demais exames solicitados no líquor ainda estavam pendentes. Diante dessa apresentação clínica e da possibilidade de encefalite herpética, além da terapia de suporte clínico, a conduta mais adequada é:","options":{"A":"Aguardar todos os resultados do líquor para iniciar o tratamento.","B":"Coletar sorologia para herpes simplex no soro e aguardar o resultado para iniciar o tratamento.","C":"Programar biópsia cerebral com urgência visando a estabelecer o diagnóstico definitivo.","D":"Iniciar corticoide venoso em dose alta para evitar a formação de edema em torno das lesões cerebrais e prevenir sequelas de uma possível meningite.","E":"Iniciar aciclovir por via venosa, enquanto se aguarda a confirmação do diagnóstico de encefalite herpética ou até que outro diagnóstico seja feito."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O quadro clínico e a RM sugerem Encefalite Herpética. Deve-se iniciar Aciclovir EV imediatamente, sem aguardar a confirmação do PCR.\nPor que as outras estão erradas:\nA/B/C/D: Aguardar resultados ou fazer biópsia atrasa o tratamento emergencial.\nPonto de prova: Conduta emergencial na encefalite herpética.\nFlashcard sugerido: Suspeita de encefalite herpética. O que fazer? Resposta: Iniciar Aciclovir EV imediatamente.\nPérola: Encefalite temporal: Aciclovir não pode esperar.\nArmadilha: Aguardar o PCR para iniciar Aciclovir.","tags":["Clínica Médica","Neurologia","Déficit Neurológico Focal","Convulsões","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Quando uma pessoa fica com febre alta, dor de cabeça forte e mudanças de comportamento repentinas, e o exame de imagem mostra alteração numa parte específica do cérebro, o médico começa logo um remédio contra o vírus herpes, sem esperar a confirmação final do exame."},{"id":"b15-q058","number":58,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Recém-nascida (RN) de 7 dias de vida, é levada à UBS para a primeira consulta pediátrica. Sua mãe foi diagnosticada com toxoplasmose aguda no terceiro trimestre da gestação e iniciou tratamento com espiramicina. O USG fetal identificou calcificações intracranianas. O exame físico da RN é normal, o USG transfontanelar não revelou novas lesões além das já detectadas e sua sorologia é IgG positivo e IgM negativo para toxoplasmose. Com base no protocolo de manejo de toxoplasmose congênita, qual é a conduta mais apropriada?","options":{"A":"Iniciar o tratamento com espiramicina e realizar exames mensais de acompanhamento até que a IgM se torne positiva.","B":"Não iniciar o tratamento neste momento, mas realizar acompanhamento mensal com exames físico, neurológico, sorologia e avaliação oftalmológica.","C":"Iniciar o tratamento tríplice com pirimetamina, sulfadiazina e ácido folínico por 12 meses, independentemente de novos achados clínicos.","D":"Repetir a sorologia e ultrassonografia transfontanelar em 15 dias antes de tomar qualquer decisão sobre o início do tratamento."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Se houve infecção materna confirmada na gestação, o RN deve ser tratado com esquema tríplice por 12 meses, mesmo se assintomático.\nPor que as outras estão erradas:\nA/B/D: Observação ou espiramicina não são adequadas para RN com infecção confirmada.\nPonto de prova: Tratamento do RN com toxoplasmose congênita.\nFlashcard sugerido: RN de mãe com toxoplasmose fetal confirmada. Tratamento? Resposta: Tríplice por 12 meses.\nPérola: Toxo no feto confirmada: Tríplice por 1 ano, nem que o RN pareça bem.\nArmadilha: Não tratar porque o RN está assintomático.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose Gestacional","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se a mãe teve a doença confirmada durante a gravidez, o bebê precisa de um tratamento com três remédios que dura um ano inteiro, mesmo que ele pareça saudável."},{"id":"b15-q059","number":59,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Ferramentas da APS","stem":"João, um menino de 4 anos e 8 meses, é levado a consulta por sua mãe, que está preocupada com o seu desenvolvimento. Ela relata que ele ainda não fala palavras com significado e, quando tenta falar, repete frases que ouve na televisão. A mãe também observa que João não responde quando é chamado pelo nome e raramente faz contato visual. Ele prefere brincar sozinho e não demonstra interesse em interagir com outras crianças da mesma idade. Além disso, João tem fascinação por objetos incomuns, como folhas de papel, que ele passa horas rasgando em tiras finas. Durante as refeições, insiste em comer sempre os mesmos alimentos e segue um ritual rígido de como os itens devem ser dispostos no prato. A mãe percebeu esses comportamentos desde que ele tinha cerca de 1 ano e meio, mas eles parecem estar se intensificando. Qual das ferramentas abaixo é adequada para promover o cuidado de forma coordenada, considerando as singularidades de João e sua família?","options":{"A":"Acompanhamento Longitudinal.","B":"Protocolo Clínico e Diretrizes Terapêuticas (PCDT).","C":"Linha de Cuidado.","D":"Projeto Terapêutico Singular (PTS)."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O caso descreve suspeita de TEA com singularidades. A ferramenta para organizar cuidados coordenados e individualizados na APS é o Projeto Terapêutico Singular (PTS).\nPor que as outras estão erradas:\nA/B/C: Não abordam a singularidade do caso como o PTS.\nPonto de prova: Ferramenta de cuidado individualizado na APS.\nFlashcard sugerido: Ferramenta para cuidado de caso complexo e singular na APS? Resposta: Projeto Terapêutico Singular (PTS).\nPérola: Caso complexo = PTS.\nArmadilha: Usar PCDT (protocolo rígido).","tags":["Pediatria","Saúde da Criança","Conhecimento Conceitual","Pediatria Ambulatorial","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Uma criança de quase 5 anos que ainda não fala direito, não olha nos olhos e tem rituais rígidos precisa de um plano de cuidado feito especialmente para ela e sua família, considerando tudo o que a torna única."},{"id":"b15-q060","number":60,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Rn de A.G.L., sexo masculino, nasceu de parto cesáreo (indicação: ventriculomegalia moderada) com idade gestacional de 35 semanas e 4 dias pela DUM e de 37 semanas pelo Capurro, bolsa rota no ato, apresentação cefálica. Chorou ao nascer, foi levado ao berço aquecido onde deprimiu. Foi submetido a entubação e aspirado, com boa recuperação. Apgar: 4 e 9, peso de nascimento: 1790 g. estatura: 41 cm, PC: 31 cm. Evoluiu com icterícia colestática e hepatomegalia. A ecografia trans fontanela mostrou várias calcificações cerebrais e hidrocefalia. Diante do quadro do recém-nascido, assinale a alternativa CORRETA:","options":{"A":"Para confirmação do diagnóstico, basta realizar IgG e IgM maternos.","B":"A maioria dos recém-nascidos com infecção congénita por toxoplasmose é assintomática.","C":"A maioria das transmissões verticais ocorre no início da gestação, quando a placenta é mais vascularizada.","D":"O alto grau de comprometimento do recém-nascido indica que a infecção ocorreu no final da gravidez."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A maioria dos RN com toxoplasmose congênita nasce assintomática (cerca de 70-90%).\nPor que as outras estão erradas:\nA: IgG materno não confirma no RN (passa a placenta).\nC: A transmissão é mais comum no final da gestação.\nD: Infecção tardia costuma causar quadros mais leves.\nPonto de prova: Epidemiologia da toxoplasmose congênita.\nFlashcard sugerido: A maioria dos RN com toxoplasmose congênita é sintomática? Resposta: Não, a maioria é assintomática ao nascimento.\nPérola: Toxo congênita: 70% nascem aparentemente bem.\nArmadilha: Achar que todo RN com toxo nasce muito grave.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Rotura de Membranas","Assistência ao Parto","Conhecimento Conceitual","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"A maioria dos bebês que pegam essa infecção dentro da barriga da mãe nasce sem sintomas nenhum, mesmo que às vezes o problema seja grave."},{"id":"b15-q061","number":61,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"O Projeto Terapêutico Singular (PTS) na Medicina da Família é composto por: <br>","options":{"A":"Diagnóstico clínico, plano terapêutico e acompanhamento.","B":"Avaliação biopsicossocial, plano de cuidado individualizado e rede de apoio.","C":"Anamnese, exame físico e prescrição medicamentosa.","D":"Diagnóstico diferencial, tratamento farmacológico e prevenção primária.","E":"Histórico clínico, plano de tratamento e avaliação de satisfação."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O PTS baseia-se na avaliação biopsicossocial, plano de cuidado individualizado e rede de apoio.\nPor que as outras estão erradas:\nA/C/D/E: Não se restringe a prescrições farmacológicas ou diagnósticos estritos.\nPonto de prova: Estrutura do PTS.\nFlashcard sugerido: Quais os componentes do PTS? Resposta: Avaliação biopsicossocial, plano individualizado e rede de apoio.\nPérola: PTS olha o bio, o psico, o social e a rede.\nArmadilha: Reduzir o PTS a um plano farmacológico.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Esse plano de cuidado individualizado olha para a saúde da pessoa, sua mente, sua vida social e as pessoas que a apoiam, tudo junto."},{"id":"b15-q062","number":62,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Infecções Congênitas","stem":"Paciente de 18 meses, comparece em UBS para consulta de puericultura de rotina. Mãe relata amamentação materna exclusiva, diurese e evacuação dentro do habituais. Vacinação atualizada, bom ganho pondero- estatural, bem como DNPM. Como AP, foi tratado para sífilis congênita ao nascimento. Tratamento adequado, sem intercorrências. Devido a esse AP, foi solicitado em consulta prévia novo VDRL para controle, com resultado 1:2 (semelhante aos prévios). A respeito desse paciente e sobre o seguimento ambulatorial de pacientes com exposição à sífilis, é INCORRETO afirmar que:","options":{"A":"Como título baixo de VDRL (< 1:4), podemos considerar flutuação dentro da normalidade, sem necessidade de retratamento. A orientação é de seguir com seguimento ambulatorial com o próximo VDRL aos 24 meses.","B":"Os recém-nascidos expostos à sífilis devem ser seguidos ambulatorialmente com a coleta seriada de VDRL (1, 3, 6, 12 e 18 meses).","C":"Caso haja necessidade de retratamento, deve ser realizado com penicilina EV por 10 dias.","D":"Consultas oftalmológicas, audiológicas e neurológicas devem ser realizadas a cada 6 meses por 2 anos."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O item A está INCORRETO. Se o paciente foi tratado, um VDRL 1:2 aos 18 meses deve ter caído; se persiste, deve ser retratado. A afirmação diz que é flutuação normal.\nPor que as outras estão erradas: (B, C e D estão corretas na teoria).\nPonto de prova: Seguimento laboratorial da sífilis congênita.\nFlashcard sugerido: VDRL do RN tratado de sífilis deve estar negativado com quantos meses? Resposta: Por volta de 12-18 meses.\nPérola: VDRL de sífilis congênica tem que zerar!\nArmadilha: Achar que VDRL 1:2 baixo é normal e dispensa tratamento.","tags":["Pediatria","Saúde da Criança","Aleitamento Materno","Sífilis","Conduta Terapêutica","Atenção Primária"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se um bebê que já foi tratado para sífilis continua com um exame de sangue levemente alterado depois de mais de um ano, isso não é normal e precisa ser tratado de novo, pois o exame deveria ter zerado."},{"id":"b15-q063","number":63,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"A conduta mais adequada para um RN de 1.800g, cuja mãe é HbsAg (+), além de imunoglobulina específica, e em relação ao calendário de imunização, é fazer:","options":{"A":"Vacina Hepatite B e aplicar junto BCG.","B":"Adiar a vacina de Hepatite B até completar 2.000g, ou 2 meses de idade. Aplicar BCG.","C":"Adiar BCG e vacina Hepatite B até atingir 2 meses de idade.","D":"Vacina de Hepatite B e adiar BCG até atingir 2.000g.","E":"Adiar BCG e Hepatite B até completar 2.000g."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: RN de mães HBsAg positivas devem receber a vacina contra Hepatite B e a IGHB nas primeiras 12 horas, independentemente do peso. A BCG é contraindicada em prematuros < 2000g, devendo ser adiada.\nPor que as outras estão erradas:\nA/B/C/E: Atrasar a vacina de Hepatite B está errado; aplicar BCG antes de 2000g é contraindicação.\nPonto de prova: Imunização em RN de mãe com Hepatite B e baixo peso.\nFlashcard sugerido: RN < 2000g de mãe HBsAg+. Conduta? Resposta: Vacina Hep B + IGHB agora; adiar BCG até 2000g.\nPérola: Hepatite B não espera peso; BCG sim.\nArmadilha: Atrasar a hepatite B por causa do baixo peso.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Período Neonatal","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Quando a mãe tem hepatite B, o bebê recebe a vacina contra essa doença logo nas primeiras horas de vida, não importa o peso; já outra vacina (BCG) espera o bebê ganhar mais peso."},{"id":"b15-q064","number":64,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Mulher de 19 anos, sem histórico psiquiátrico prévio, apresenta alterações de comportamento há 15 dias. Família relata pensamentos persecutórios e agressividade. Apresenta insônia e queixa de cefaleia constante. Relato de febre não aferida. O diagnóstico mais provável é:","options":{"A":"Delirium.","B":"Esquizofrenia.","C":"Encefalite.","D":"Epilepsia.","E":"Transtorno bipolar."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Alteração de comportamento aguda associada a cefaleia e febre em adulto jovem previamente hígido é um quadro clássico de Encefalite.\nPor que as outras estão erradas:\nA/B/D/E: Não explicam a febre e cefaleia associadas.\nPonto de prova: Apresentação atípica de encefalite.\nFlashcard sugerido: Psicose aguda + febre + cefaleia. Diagnóstico? Resposta: Encefalite.\nPérola: Psicose febril = Encefalite.\nArmadilha: Fechar diagnóstico de surto esquizofrênico ignorando a febre.","tags":["Clínica Médica","Neurologia","Cefaleia","Síndrome Febril","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Mudança repentina de comportamento, com pensamentos estranhos, agressividade e febre em uma pessoa jovem, sem histórico de doença mental, pode ser uma infecção no cérebro, e não um problema psiquiátrico."},{"id":"b15-q065","number":65,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Mulher de 40 anos refere “dor de cabeça” desde a infância, com crises agudas de intensa hemicrania pulsátil precedidas de sintomas visuais “em fortificação”. São características dessa cefaleia primária:","options":{"A":"Alterações típicas no eletroencefalograma e lesões na tomografia computadorizada de crânio.","B":"Predomínio no sexo masculino, sem vinculação genética e com boa resposta terapêutica a carbamazepina nas crises agudas.","C":"Predomínio no sexo feminino, com vinculação genética e boa resposta terapêutica a triptanos na prevenção de crises.","D":"Predomínio no sexo masculino, sem vinculação genética e com boa resposta terapêutica com oxigenioterapia.","E":"Predomínio no sexo feminino, com forte vinculação genética e boa resposta terapêutica a anti-inflamatórios não esteroides nas crises prolongadas."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Enxaqueca tem predomínio no feminino, forte componente genético e crises prolongadas respondem bem a AINEs.\nPor que as outras estão erradas:\nA/B/C/D: Outras características não se aplicam à enxaqueca.\nPonto de prova: Características clínicas e epidemiológicas da migrânea.\nFlashcard sugerido: Predomínio e tratamento da migrânea com aura? Resposta: Feminino; AINEs/Triptanos na crise.\nPérola: Migrânea: mulher, genética e aura visual.\nArmadilha: Confundir tratamento abortivo com profilático.","tags":["Clínica Médica","Neurologia","Cefaleia","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Essa dor de cabeça latejante, que vem desde criança e é precedida de luzes especiais, é mais comum em mulheres, tem forte relação com a genética da família, e melhora com remédios anti-inflamatórios nas crises mais longas."},{"id":"b15-q066","number":66,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções Congênitas","stem":"Mulher de 38 anos, com deficiência congênita de IgA, é atendida em ambulatório de clínica médica devido a insucesso terapêutico no tratamento de infecção por Helicobacter pylori. Apresentava diagnóstico de úlcera duodenal, tendo sido prescrito omeprazol, amoxicilina e claritromicina. Apesar da melhora clínica, observou- se persistência da infecção em teste respiratório com C13. Atribuiu- se o insucesso terapêutico ao uso recorrente de macrolídeos e fluoroquinolonas. Nesse caso, deve- se prescrever","options":{"A":"Pantoprazol, amoxicilina e levofloxacino por 7 dias.","B":"Omeprazol, claritromicina e levofloxacino por 14 dias.","C":"Omeprazol, subcitrato de bismuto coloidal, doxiciclina e metronidazol por 14 dias.","D":"Pantoprazol, subcitrato de bismuto coloidal, furazolidona e levofloxacino por 10 dias."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Após falha do esquema com Claritromicina, o esquema preferencial contendo Bismuto (IBP + Bismuto + Tetraciclina + Metronidazol) por 14 dias é indicado.\nPor que as outras estão erradas:\nA/B/D: Levofloxacino deve ser evitado se já usou fluoroquinolonas.\nPonto de prova: Tratamento de 2ª linha para H. pylori.\nFlashcard sugerido: Falha de erradicação com Claritromicina. Próximo esquema? Resposta: Quádrupla com Bismuto.\nPérola: Claritro falhou? Manda o Bismuto.\nArmadilha: Usar Levofloxacino em quem já usa fluorquinolona.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Quando o remédio de primeira linha para uma bactéria do estômago não funciona, o médico troca por outra combinação de remédios que inclui um mineral protetor do estômago (bismuto)."},{"id":"b15-q067","number":67,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma mulher com 28 anos de idade, primigesta, com 14 semanas de gestação, comparece à segunda consulta de pré-natal com resultado de exame de sorologia para toxoplasmose com IgG e IgM positivos. A paciente está assintomática. Nesse caso, a conduta médica adequada ao realizar o atendimento a essa gestante é:","options":{"A":"Prescrever imediatamente espiramicina e solicitar teste de avidez de IgG.","B":"Prescrever imediatamente espiramicina e solicitar nova sorologia em 1 mês.","C":"Tranquilizar a paciente, dizendo que se trata de infecção antiga e não solicitar mais sorologias.","D":"Tranquilizar a paciente, dizendo que pode se tratar de falso positivo e solicitar nova sorologia em 2 semanas."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Gestante no 1º trimestre com IgG e IgM positivos. Deve-se iniciar Espramicina e solicitar Teste de Avidez de IgG.\nPor que as outras estão erradas:\nB/C/D: Não se pode descartar infecção recente sem avidez.\nPonto de prova: Fluxograma de toxoplasmose no 1º trimestre.\nFlashcard sugerido: 14 sem, IgG e IgM +. Conduta? Resposta: Espiramicina + Teste de avidez.\nPérola: IgM + no 1º tri = Espiramicina e Avidez.\nArmadilha: Pedir nova sorologia em vez da avidez.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Depois dos três meses de gravidez, o exame que mede a maturidade dos anticorpos deixa de ser útil, então se os dois exames de sangue dão positivos, o médico já parte para o tratamento com três remédios."},{"id":"b15-q068","number":68,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Recém- nascido com 2 horas de vida, nascido de parto vaginal, com idade gestacional de 37+3 semanas. Mãe com diagnóstico de infecção pelo vírus da imunodeficiência humana (HIV) há 6 anos, sempre fez uso irregular de TARV. Realizou 9 consultas de pré-natal e refere que iniciou boa adesão da TARV no primeiro trimestre. A carga viral do HIV no primeiro trimestre era 2567 cópias e no último trimestre 480 cópias. Bolsa rota por 6 horas. Não realizou profilaxia com zidovudina durante o trabalho de parto. Sem intercorrências durante o parto e bebê clinicamente bem. Em relação à transmissão vertical do HIV, qual a classificação de risco desse paciente e qual a conduta adequada em relação à profilaxia?","options":{"A":"Paciente de alto risco; deve-se introduzir profilaxia com zidovudina, lamivudina e raltegravir por 28 dias.","B":"Paciente de alto risco; deve-se introduzir profilaxia com zidovudina, lamivudina e nevirapina por 28 dias.","C":"Paciente de baixo risco; deve-se introduzir profilaxia com zidovudina por 28 dias.","D":"Paciente de baixo risco; deve-se introduzir profilaxia com zidovudina por 28 dias e nevirapina 3 doses."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Mãe sem TARV durante a gestação caracteriza RN de ALTO RISCO. O esquema é AZT + 3TC + RAL (ou NVP) por 28 dias.\nPor que as outras estão erradas:\nC/D: AZT isolado não é suficiente para alto risco.\nPonto de prova: Profilaxia da TV do HIV em RN de altíssimo risco.\nFlashcard sugerido: RN de mãe HIV+ que não tomou TARV. Profilaxia? Resposta: AZT + 3TC + Raltegravir.\nPérola: Mãe sem TARV = Risco altíssimo = 3 drogas com RAL.\nArmadilha: Usar AZT isolado por ser parto vaginal.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conduta Terapêutica","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Quando a mãe grávida não seguiu bem o remédio contra o HIV, o bebê corre mais risco de ter pegado o vírus, por isso ele precisa de três remédios de proteção, em vez de só um."},{"id":"b15-q069","number":69,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Mulher de 32 anos de idade, G2P2A0, não realizou pré-natal, deu à luz um recém-nascido a termo, pesando 2.800 g, APGAR 8/9. Ainda na maternidade, o bebê evoluiu com falta de movimentação ativa e posição semiflexionada dos membros inferiores, dolorosos à mobilização. Exame físico abdominal com fígado palpável a 3 cm do rebordo costal direito e baço a 2 cm do rebordo costal esquerdo. Nesse contexto, a condição clínica mais provável é:","options":{"A":"Toxoplasmose congênita.","B":"Sífilis congênita.","C":"Tocotraumatismo.","D":"Posição pélvica ao nascimento.","E":"Sépsis precoce."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Falta de movimentação ativa e posição semiflexionada dolorosa (Pseudoparalisia de Parrot) e hepatoesplenomegalia é o quadro clássico de Sífilis Congênita Precoce.\nPor que as outras estão erradas:\nA/C/D/E: Não explicam a pseudoparalisia de Parrot.\nPonto de prova: Apresentação clínica da sífilis congênita.\nFlashcard sugerido: RN com pseudoparalisia de Parrot e HEP. Diagnóstico? Resposta: Sífilis congênita.\nPérola: Bebê que não mexe o bracinho: sífilis (Parrot).\nArmadilha: Confundir com fratura obstétrica.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Trauma Esplênico","Pré-Natal","Raciocínio Diagnóstico","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Um bebê que não mexe uma perninha ou bracinho porque dói (parece paralisado, mas não é) e tem fígado e baço maiores é um sinal clássico de sífilis pega dentro da barriga da mãe."},{"id":"b15-q070","number":70,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Recém-nascida de 39 semanas, sexo feminino, nasce de parto vaginal sem intercorrências, bom boa vitalidade, e é levada ao alojamento conjunto. Ao avaliar a caderneta da gestante, você observa que a mãe da paciente foi diagnosticada com sífilis, sendo tratada com 3 doses semanais de penicilina benzatina de 2,4 milhões de unidades. Recebeu a última dose 25 dias antes do parto. As demais sorologias foram negativas e não houve qualquer outra intercorrência no pré-natal. Colhido VDRL pareado da mãe e da RN, com resultado de 1:4 e 1:8, respectivamente e, ao exame físico inicial, a RN encontra-se assintomática. Qual a melhor conduta no momento?","options":{"A":"Notificar para sífilis congênita, colher líquor, hemograma e radiografia de ossos longos. Se todos os exames forem normais, a criança pode ser tratada com dose única de penicilina benzatina.","B":"Considerar a criança como exposta à sífilis, não notificar e dar apenas seguimento ambulatorial, sem tratamento antimicrobiano específico.","C":"Notificar para sífilis congênita, colher líquor, hemograma e radiografia de ossos longos. Se todos os exames forem normais, tratar a criança com 10 dias de penicilina procaína ou cristalina.","D":"Considerar a criança como exposta à sífilis, notificar o caso e dar alta após dose única de penicilina benzatina, com seguimento ambulatorial."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Mãe tratada inadequadamente (há 25 dias), mas o RN está assintomático e com VDRL menor que o materno. Considera-se exposto, não notificando como congênita se os exames estiverem normais, seguindo ambulatorialmente.\nPor que as outras estão erradas:\nA/C/D: Notificar ou tratar como sífilis congênita não se aplica se o RN está assintomático e com títulos baixos.\nPonto de prova: Manejo de RN assintomático de mãe inadequadamente tratada.\nFlashcard sugerido: RN assintomático com VDRL menor que o materno. Conduta? Resposta: Exposta à sífilis, seguimento ambulatorial.\nPérola: RN com VDRL menor que a mãe e sem sintomas = Exposto.\nArmadilha: Notificar como sífilis congênita se o RN está assintomático.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Assistência ao Parto","Pré-Natal","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se o bebê nasce sem sintomas e o exame de sangue dele é bem menor que o da mãe, mesmo que o tratamento dela tenha sido um pouco atrasado, ele é considerado apenas 'exposto' à doença, e não precisa de tratamento imediato, só de acompanhamento."},{"id":"b15-q071","number":71,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma secundigesta de 34 anos, durante o início do pré-natal, apresentou resultado da sorologia para toxoplasmose IgG + e IgM +. O teste de IgG da mesma amostra revelou baixa avidez, o que levou o obstetra a suspeitar, no pré- natal, de possível infecção. Conversando com a gestante, optou- se pela realização do PCR no líquido amniótico, colhido na 19ª semana de gestação. O resultado foi positivo. Nesse caso, o tratamento a ser instituído é:","options":{"A":"Espiramicina, pirimetamina e ácido fólico.","B":"Ácido fólico, sulfasalazina e espiramicina.","C":"Folato, sulmetizol e pirazinamida.","D":"Sulfadiazina, pirimetamida e ácido folínico.","E":"Ácido folínico, pirazinamida e espiramicina"},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: PCR no líquido amniótico positivo indica infecção fetal. O tratamento é o esquema tríplice: Sulfadiazina + Pirimetamina + Ácido folínico.\nPor que as outras estão erradas:\nA/B/C/E: Espiramicina não trata o feto.\nPonto de prova: Tratamento da toxoplasmose fetal.\nFlashcard sugerido: Toxoplasmose fetal confirmada por PCR. Tratamento? Resposta: Sulfadiazina, Pirimetamina e Ácido folínico.\nPérola: Feto com toxo: Sulfadiazina + Pirimetamina + Ác. Fólico.\nArmadilha: Manter espiramicina após confirmar infecção fetal.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando um exame que examina diretamente o líquido ao redor do bebê confirma a infecção, o tratamento certo é uma combinação de três remédios para proteger o bebê."},{"id":"b15-q072","number":72,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Mulher de 23 anos apresenta, desde a adolescência, cefaleia hemicraniana de média a forte intensidade, pulsátil, associada a foto e fonofobia, náuseas, que dura em geral de 6 a 8 horas, melhorando após o sono. Em função da frequência das crises de cefaleia, ela vem usando analgésicos comuns 15 dias por mês nos últimos 3 meses. A mãe apresentava, até os 50 anos de idade, quadro semelhante. Os exames laboratoriais e de neuroimagem foram normais. Diante desse cenário, a conduta inicial é:","options":{"A":"Iniciar topiramato frente ao diagnóstico de cefaleia tensional frequente.","B":"Iniciar propranolol frente ao diagnóstico de migrânea episódica.","C":"Iniciar amitriptilina frente ao diagnóstico de cefaleia tensional crônica.","D":"Iniciar antagonista CGRP frente ao diagnóstico de migrânea crônica.","E":"Iniciar ciclobenzaprina e anti-inflamatório frente ao diagnóstico de cefaleia tensional episódica infrequente."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Paciente com enxaqueca prévia que evolui com piora da frequência e uso de analgésicos em 15 dias/mês. Isso configura Migrânea Crônica. A conduta ideal é suspender o analgésico e iniciar profilaxia (CGRP ou Topiramato).\nPor que as outras estão erradas:\nA/B/C/E: Diagnósticos incorretos.\nPonto de prova: Critérios de Migrânea Crônica.\nFlashcard sugerido: Migrânea > 15 dias/mês + abuso de AINE. Diagnóstico e tratamento? Resposta: Migrânea Crônica; suspender AINE e iniciar preventivo.\nPérola: Migrânea que vicia em analgésico vira crônica.\nArmadilha: Manter analgésico ou trocar de analgésico.","tags":["Clínica Médica","Neurologia","Cefaleia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça que já vem desde a adolescência e piora ao ponto de a pessoa usar analgésico quase todo dia pode virar uma enxaqueca mais forte e constante, precisando de um remédio preventivo especial."},{"id":"b15-q073","number":73,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Mulher de 40 anos é internada com cefaleia intensa e rigidez de nuca. A pressão do liquor é de 240 cm de água e o exame do LCR identifica 180 células/ mm³ (90% de linfócitos e 10% de monócitos) e 80 mg/ dl de proteínas com glicorraquia normal. A família informa que a paciente tem ótima saúde, porém nos últimos 10 anos esta é a quarta internação com sintomas semelhantes. Somente agora o vírus relacionado a essa síndrome meníngea recorrente foi identificado no LCR por PCR, firmando o diagnóstico final de meningite:","options":{"A":"Na doença de Behçet.","B":"De tipo Mollaret, por reativação do herpes vírus tipo 2.","C":"Aguda linfocítica na síndrome de Vogt-Koyanagi-Harada.","D":"No lúpus eritematoso sistêmico.","E":"Na neoplasia."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Meningite recorrente com surtos repetidos é a Síndrome de Mollaret, causada pela reativação do HSV-2.\nPor que as outras estão erradas:\nA/C/D/E: Não são as causas mais comuns de Mollaret.\nPonto de prova: Etiologia da Meningite de Mollaret.\nFlashcard sugerido: Qual o agente da Meningite de Mollaret? Resposta: Herpes vírus tipo 2 (HSV-2).\nPérola: Meningite de Mollaret = PCR para HSV-2.\nArmadilha: Achar que é tuberculose.","tags":["Clínica Médica","Neurologia","Cefaleia","Parada Cardiorrespiratória","Raciocínio Diagnóstico","Assistência Hospitalar"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Uma dor de cabeça que volta várias vezes ao longo dos anos, sempre parecida, pode ser causada por um vírus da família do herpes que se esconde no corpo e volta de vez em quando a causar essa infecção nas membranas do cérebro."},{"id":"b15-q074","number":74,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Homem de 43 anos, com história de cefaleia unilateral intensa na região temporal esquerda, acompanhada de congestão nasal ipsilateral, rinorreia aquosa, sudorese facial e sensação de inquietação. Os episódios ocorrem algumas vezes ao dia, cada um com duração de cerca de 30 minutos, e há relato de que o uso de analgésicos comuns não traz alívio significativo. Já apresntou quadro semelhante há um ano, mas permaneceu sem crises de dor por vários meses. Relata agravamento significativo da qualidade de vida. Após avaliação diagnóstica que descarta causas secundárias e síndrome de Horner, qual é a opção terapêutica profilática de primeira linha para o caso descrito?","options":{"A":"Gabapentina em dose progressiva.","B":"Verapamil em dose titulada conforme tolerância e resposta.","C":"Topiramato como monoterapia em baixa dose.","D":"Indometacina em altas doses diárias.","E":"Sumatriptano 100 mg por via oral diariamente."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O tratamento profilático de primeira linha para Cefaleia em Salvas é o Verapamil.\nPor que as outras estão erradas:\nA/C/D/E: Não são a primeira escolha (Indometacina é para Hemicrania Paroxística).\nPonto de prova: Tratamento profilático da cefaleia em salvas.\nFlashcard sugerido: Profilaxia de primeira linha para cefaleia em salvas? Resposta: Verapamil.\nPérola: Salvas: O2 para abortar, Verapamil para prevenir.\nArmadilha: Prescrever indometacina.","tags":["Clínica Médica","Neurologia","Cefaleia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Para prevenir aquela dor forte de um lado do rosto que vem em crises várias vezes ao dia, o remédio preventivo mais indicado é um que ajuda a relaxar os vasos sanguíneos."},{"id":"b15-q075","number":75,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções Congênitas","stem":"Homem, 72 anos de idade, busca atendimento devido surgimento de crises de dor em choque na região mandibular esquerda, sendo que cada episódio tinha duração de poucos segundos. Foi solicitada ressonância magnética de encéfalo com estudo de vasos arteriais que revelou conflito neurovascular entre a artéria cerebelar superior esquerda e o nervo trigêmeo ipsilateral. Após o início de carbamazepina 600 mg/dia, o paciente teve melhora substancial da dor, porém evoluiu com ataxia. Optou- se pela substituição por oxcarbazepina 900 mg/ dia, no entanto, o paciente começou a apresentar hiponatremia. Em relação ao provável diagnóstico e opções terapêuticas para tal condição, assinale a alternativa correta:","options":{"A":"Neuralgia do trigêmeo clássica; substituir oxcarbamazepina por ácido valpróico.","B":"Neuropatia trigeminal dolorosa; iniciar tratamento com lamotrigina.","C":"Neuropatia trigeminal dolorosa; tratar a condição de base.","D":"Neuralgia do trigêmeo clássica; iniciar gabapentina"},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O quadro é Neuralgia do Trigêmeo. A primeira linha é Carbamazepina/Oxcarbazepina, mas como houve efeitos colaterais, a próxima linha inclui Gabapentina.\nPor que as outras estão erradas:\nA/B/C: Lamotrigina é alternativa, mas o tratamento da neuropatia trigeminal dolorosa foca na doença de base.\nPonto de prova: Tratamento alternativo da Neuralgia do Trigêmeo.\nFlashcard sugerido: Alternativa à Carbamazepina na neuralgia do trigêmeo com efeitos colaterais? Resposta: Gabapentina.\nPérola: Trigêmeo dói em choque: Carbamazepina; se bobear, Gabapentina.\nArmadilha: Confundir com neuropatia trigeminal dolorosa.","tags":["Clínica Médica","Endocrinologia","Hiponatremia","Choque","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Uma dor forte tipo choque elétrico no rosto, causada por um nervo sendo comprimido por um vaso sanguíneo, é tratada primeiro com um remédio anticonvulsivante, e se ele causar efeitos ruins, troca-se por outro remédio parecido."},{"id":"b15-q076","number":76,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Recém- nascido de termo, 20 horas de vida, está em alojamento conjunto e aleitamento materno exclusivo. Ao revisar o prontuário, você percebe que o teste rápido de sífilis materno, realizado no momento do parto, é positivo. Ao conversar com a mãe, percebe que ela desconhecia a possibilidade de uma possível infecção e que não lhe foi falado nada ou realizado qualquer tratamento durante seu pré-natal. Na caderneta, há apenas 1 coleta de teste não treponêmico no primeiro trimestre de gestação, com resultado negativo. Ao examinar o bebê, o mesmo está assintomático e com exame físico normal. Nesse momento, assinale a conduta MAIS ADEQUADA para esse bebê:","options":{"A":"Como o bebê está assintomático, basta realizar a coleta de teste não treponêmico (VDRL) do binômio mãe-bebê. Se o valor do teste do bebê for de, no máximo, 1 diluição maior do que o valor materno, ele será considerado como exposto à sífilis, sem necessidade de tratamento.","B":"Como a mãe não recebeu o tratamento adequado para sífilis durante o pré-natal, deve-se afirmar que o bebê possui sífilis. Por isso, o tratamento deve ser instituído imediatamente, sem necessidade de coletar qualquer exame complementar.","C":"Como a mãe realizou o teste não treponêmico durante o pré-natal e como o bebê está assintomático, deve-se considerar o teste rápido realizado no momento do parto como falso- positivo. O bebê deve receber alta sem necessidade de realizar qualquer exame.","D":"Inicialmente, deve-se coletar o teste não treponêmico (VDRL) da mãe e do bebê, bem como realizar a investigação do bebê (através de hemograma, raio- X de ossos longos e líquor cefalorraquidiano), mesmo que ele esteja assintomático. Posteriormente, deve-se instituir o tratamento antimicrobiano, sendo que o antibiótico escolhido dependerá do resultado dos exames."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Se a mãe não foi tratada, o RN deve ser investigado com VDRL pareado, hemograma, Rx e líquor, mesmo se assintomático.\nPor que as outras estão erradas:\nA/B/C: Não se pode descartar ou tratar cegamente sem investigar.\nPonto de prova: Protocolo de investigação de sífilis congênita em RN assintomático.\nFlashcard sugerido: RN assintomático de mãe não tratada. Conduta? Resposta: Investigar com VDRL, hemograma, Rx e líquor.\nPérola: Mãe não tratou, RN não escapa: investiga tudo.\nArmadilha: Não colher líquor por estar assintomático.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Aleitamento Materno","Sífilis","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se um bebê nasce de mãe que nunca fez o teste ou tratamento para sífilis, ele precisa de vários exames — mesmo parecendo saudável — para o médico decidir o melhor tratamento."},{"id":"b15-q077","number":77,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Recém-nascido do sexo masculino de 10 dias de vida, filho de mãe com pré-natal inadequado, que apresentava sorologias somente do último trimestre com toxoplasmose IgM e IgG positivos. Nasceu de parto vaginal, a termo, adequado para a idade gestacional. A ultrassonografia transfontanela e o exame de fundo de olho foram normais. Os exames laboratoriais do paciente evidenciaram hemoglobina de 15,2g/ dL e leucócitos de 13.400/ mm³ (linfócitos 8.844/ mm³; neutrófilos 5.092/ mm³; basófilos 134/mm³; eosinófilos 134/mm³; monócitos 536/mm³). A sorologia para toxoplasmose do neonato foi realizada com 5 e 10 dias de vida, sendo positiva para IgM e IgG nas duas oportunidades, mas a pesquisa de toxoplasma por técnica de Polymerase Chain Reaction (PCR) no sangue foi negativa. Qual é a conduta que deve ser adotada neste momento?","options":{"A":"Solicitar tomografia de crânio e, se alterada, indicar o tratamento com sulfadiazina, pirimetamina e ácido folínico.","B":"Como a PCR para toxoplasma é negativa e o paciente está assintomático, não há indicação de tratamento.","C":"Iniciar tratamento com sulfadiazina, pirimetamina e ácido folínico, mesmo com o paciente assintomático.","D":"Iniciar tratamento com sulfametoxazol-trimetoprima e ácido folínico, mesmo com o paciente assintomático.","E":"Solicitar tomografia de crânio e, se alterada, indicar o tratamento com sulfametoxazoltrimetoprima e ácido folínico."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Se a mãe teve toxoplasmose aguda na gestação, o RN deve ser tratado com esquema tríplice por 12 meses, mesmo se assintomático e com PCR negativo.\nPor que as outras estão erradas:\nA/B/D/E: Não tratar não é recomendado.\nPonto de prova: Manejo do RN exposto à toxoplasmose.\nFlashcard sugerido: RN assintomático de mãe com toxo aguda. Conduta? Resposta: Iniciar tratamento tríplice por 12 meses.\nPérola: Mãe teve toxo: RN toma tríplice por 1 ano.\nArmadilha: Não tratar porque o PCR do RN foi negativo.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Pré-Natal","Conduta Terapêutica","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se a mãe pegou toxoplasmose no fim da gravidez e o bebê nasce sem sintomas, ele ainda assim toma o tratamento completo com três remédios por um ano inteiro, para garantir proteção."},{"id":"b15-q080","number":80,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Sobre o diagnóstico diferencial da meningite, está INCORRETO afirmar que:","options":{"A":"A meningite bacteriana aguda pode apresentar intensa pleocitose no líquor, com predomínio de neutrófilos e hipoglicorraquia.","B":"A tuberculose meníngea pode evoluir com líquor de padrão linfocitário, proteínas elevadas e glicose reduzida.","C":"A meningite fúngica, especialmente em imunossuprimidos, pode ser causada pelo Cryptococcus e frequentemente se manifesta com glicose normal no líquor.","D":"A meningoencefalite por vírus do herpes pode ser grave e requer tratamento imediato com aciclovir.","E":"Meningites virais são autolimitadas na maioria dos casos, mas podem necessitar de suporte sintomático."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A afirmação está INCORRETA. A meningite fúngica cursa frequentemente com hipoglicorraquia (glicose reduzida), e não normal.\nPor que as outras estão erradas: (A, B, D e E estão corretas).\nPonto de prova: Bioquímica do LCR na meningite fúngica.\nFlashcard sugerido: Meningite fúngica tem glicose normal ou baixa no LCR? Resposta: Baixa (hipoglicorraquia).\nPérola: Fungo no LCR zera a glicose também.\nArmadilha: Achar que glicose normal é padrão para fungos.","tags":["Clínica Médica","Medicina Interna","Meningite","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Uma dor de cabeça, febre e mudança repentina de comportamento em jovem saudável, sem outra explicação, pode ser uma infecção grave no cérebro, e por isso a fungo Cryptococcus não costuma dar açúcar normal no líquido da coluna, diferente do que se pensa."},{"id":"b15-q081","number":81,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Uma paciente de 17 anos de idade, G1P0, com 13 semanas de gestação, sem histórico patológico, compareceu ao pré-natal sem queixas. Recebeu resultado de toxoplasmose com IgG + e IgM +. Qual é a conduta a ser adotada?","options":{"A":"Repetir a sorologia após To semanas.","B":"Solicitar teste de avidez e iniciar tratamento com espiramicina.","C":"Solicitar teste de avidez.","D":"Iniciar tratamento com espiramicina e manter até o final de gestação."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Gestante com IgG e IgM positivos no 1º trimestre deve iniciar Espramicina e solicitar Teste de Avidez de IgG.\nPor que as outras estão erradas:\nA/C/D: Repetir sorologia atrasa; não iniciar tratamento é perigoso.\nPonto de prova: Fluxograma de toxoplasmose aguda na gestação.\nFlashcard sugerido: Gestante com IgG e IgM +. O que fazer? Resposta: Espiramicina e Teste de avidez.\nPérola: IgM + na gestante: manda a espiramicina e a avidez.\nArmadilha: Só pedir avidez sem iniciar espiramicina.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando os dois exames de sangue da toxoplasmose dão positivos, o médico pede um exame extra que mostra se a infecção é recente ou antiga, além de já começar um remédio de proteção."},{"id":"b15-q082","number":82,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Um processo de educação permanente visando à construção de competências e habilidades técnicas para a abordagem da produção do cuidado e do \"fazer\" em saúde:","options":{"A":"De forma intersetorial, em rede, e desconsiderando os determinantes sociais da saúde, é o que mais se aproxima da ideia de promoção da saúde.","B":"De forma intersetorial, em rede, e considerando os determinantes sociais da saúde, é o que mais se distancia da ideia de promoção da saúde.","C":"De forma intersetorial, em rede, e considerando os determinantes sociais da saúde, é o que mais se aproxima da ideia de promoção da saúde.","D":"De forma intersetorial, em rede, e não considerando os determinantes sociais da saúde, é o que mais se aproxima da ideia de promoção da saúde."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A educação permanente visa competências e habilidades de forma intersetorial, em rede, considerando os determinantes sociais.\nPonto de prova: Conceito de Educação Permanente e Promoção da Saúde.\nFlashcard sugerido: Como a educação permanente se relaciona com a promoção da saúde? Resposta: De forma intersetorial, em rede, considerando os determinantes sociais.\nPérola: EPS sem determinante social não é promotora de saúde.\nArmadilha: Achar que educação permanente é só dentro do hospital.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Ensinar habilidades de saúde para a comunidade funciona melhor quando é feito junto com outros setores (como educação e assistência social), pensando em tudo o que influencia a vida das pessoas."},{"id":"b15-q083","number":83,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Lactente com 2 meses de idade é encaminhado ao atendimento especializado por apresentar microcefalia e crises convulsivas de difícil controle. A mãe, adolescente e sem acompanhamento pré- natal, não relatou intercorrências relevantes durante a gestação, mas refere episódio de febre baixa e sintomas gripais no primeiro trimestre da gravidez. No exame de imagem, foram identificadas calcificações periventriculares ao redor dos ventrículos laterais, microcefalia e atraso no desenvolvimento neuropsicomotor. Nos exames complementares, o teste de triagem auditiva neonatal revelou perda auditiva neurossensorial bilateral. Estas alterações são mais compatíveis com infecção congênita causada por:","options":{"A":"Citomegalovírus.","B":"Toxoplasma gondii.","C":"Treponema pallidum.","D":"Herpesvírus.","E":"Parvovírus B19."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Calcificações periventriculares, microcefalia, surdez neurossensorial e atraso no DNPM são altamente sugestivos de CMV.\nPor que as outras estão erradas:\nB: Toxoplasmose tem calcificações difusas.\nC: Sífilis tem pseudoparalisia.\nD: Herpes causa vesículas.\nPonto de prova: Síndromes infecciosas congênitas.\nFlashcard sugerido: Calcificações periventriculares + surdez + microcefalia. Qual infecção? Resposta: Citomegalovírus.\nPérola: Periventricular e surdo = CMV.\nArmadilha: Confundir calcificação periventricular com difusa.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Convulsões","Desenvolvimento Infantil","Interpretação de Exames","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Um bebê com cabeça pequena, convulsões, calcificações no cérebro e surdez, filho de mãe que teve febre leve e resfriado no início da gravidez, pode ter pego uma infecção chamada citomegalovírus dentro da barriga."},{"id":"b15-q084","number":84,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"O Citomegalovírus (CMV) é a infecção viral congênita mais comum em humanos, podendo resultar em sequelas neurossensoriais, especialmente quando adquirida durante a gestação. Considerando os métodos laboratoriais disponíveis para o diagnóstico de infecção congênita por CMV, assinale a alternativa correta:","options":{"A":"A detecção de imunoglobulina M (IgM) anti-CMV no soro do recém-nascido confirma o diagnóstico de infecção congênita.","B":"A ausência de IgM anti-CMV no recém-nascido exclui o diagnóstico de infecção congênita.","C":"A detecção do DNA viral por PCR na urina é um método inseguro e pouco específico para o diagnóstico de infecção congênita.","D":"A detecção do DNA viral por PCR na saliva é uma alternativa rápida, com alta sensibilidade e especificidade para o diagnóstico de infecção congênita.","E":"Achados laboratoriais como anemia, plaquetopenia, neutropenia e aumento de bilirrubina direta são altamente específicos para infecção congênita por CMV."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O PCR na saliva é o exame de triagem rápido com alta sensibilidade para CMV congênito.\nPor que as outras estão erradas:\nA/B: IgM pode ser falso.\nC: PCR na urina é seguro.\nPonto de prova: Exames para CMV congênito.\nFlashcard sugerido: Melhor teste de triagem para CMV congênito? Resposta: PCR na saliva.\nPérola: CMV no RN: testa a saliva e a urina.\nArmadilha: Usar IgM como padrão-ouro.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Raciocínio Diagnóstico","Saúde Materno-Fetal","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Para descobrir se um bebê recém-nascido pegou uma infecção chamada citomegalovírus, o exame mais rápido e confiável é coletar um pouco da saliva dele."},{"id":"b15-q086","number":86,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Mulher, 49 anos de idade, está no primeiro pós- operatório de cirurgia de bypass gástrico para obesidade por videolaparoscopia. Ao exame físico, encontra-se descorada, com FC de 130 bpm, PA de 100×80 mmHg e FR de 23 irpm, SpO de 94%; abdome flácido e indolor à palpação, exceto nos locais das punções. Assinale a alternativa que apresenta a principal hipótese diagnóstica:","options":{"A":"Hérnia interna.","B":"Atelectasia pulmonar.","C":"Deiscência da anastomose.","D":"Sangramento da anastomose."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Taquicardia, palidez, hipotensão no 1º PO de cirurgia bariátrica e abdome sem irritação peritoneal sugerem fortemente Sangramento da anastomose.\nPor que as outras estão erradas:\nA: Hérnia interna é tardia.\nB: Atelectasia não causa palidez e hipotensão.\nC: Deiscência causa abdome agudo e sepse.\nPonto de prova: Complicações hemorrágicas precoces pós-bariátrica.\nFlashcard sugerido: 1º PO bariátrica com taquicardia, palidez e hipotensão. Diagnóstico? Resposta: Sangramento de anastomose.\nPérola: PO pálido e taquicárdico: está sangrando.\nArmadilha: Culpar a atelectasia.","tags":["Clínica Médica","Medicina Interna","Obesidade","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois de uma cirurgia de emagrecimento, se a pessoa fica com coração acelerado, pressão baixa e pele pálida logo no primeiro dia, é sinal de que pode estar sangrando por dentro, no lugar onde foi feita a costura da cirurgia."},{"id":"b15-q087","number":87,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Cirurgia Bariátrica","stem":"Homem, 45 anos de idade, submetido a gastroplastia em Y de Roux para tratamento de obesidade há 2 anos, com perda de 40 kg. Em exame de rotina, foi feito o diagnóstico de colelitíase e coledocolitíase. Assinale a alternativa que apresenta a melhor sequência de tratamento:","options":{"A":"Colecistectomia e colangiografia transparietohepática.","B":"Colecistectomia e exploração cirúrgica do colédoco.","C":"Colangiografia endoscópica e colecistectomia laparoscópica.","D":"Litotripsia extracorpórea e colecistectomia."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Após bypass gástrico, o acesso endoscópico ao duodeno/colédoco é impossível. A conduta preferencial é a colecistectomia com exploração cirúrgica do colédoco.\nPor que as outras estão erradas:\nA/C: CPRE é muito difícil após Y de Roux.\nD: Litotripsia não é indicada.\nPonto de prova: Abordagem da coledocolitíase pós-Y de Roux.\nFlashcard sugerido: Paciente com Y de Roux e coledocolitíase. Como tratar? Resposta: Colecistectomia com exploração cirúrgica do colédoco.\nPérola: Y de Roux + pedra no colédoco = Cirurgia explorando o colédoco.\nArmadilha: Tentar fazer CPRE convencional.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Obesidade","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois da cirurgia de emagrecimento, se aparecem pedras na vesícula e no canal da bile, é preciso operar direto para tirar tudo, porque o exame que normalmente resolveria isso pela boca não consegue mais chegar lá."},{"id":"b15-q088","number":88,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"No contexto dos níveis de letramento em saúde, sabe-se que o letramento crítico:","options":{"A":"Corresponde à habilidade de compreender informações básicas, como interpretar um rótulo de medicamento ou seguir orientações simples.","B":"É limitado à decodificação de textos, não envolvendo habilidades sociais ou capacidade de aplicar informações em situações práticas.","C":"Envolve analisar informações de forma reflexiva, avaliar sua confiabilidade e participar ativamente de decisões em saúde.","D":"É determinado pelo grau de escolaridade, sendo suficiente para prever a capacidade de autocuidado do indivíduo."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O letramento crítico envolve analisar informações de forma reflexiva e participar de decisões.\nPonto de prova: Níveis de letramento em saúde.\nFlashcard sugerido: O que é letramento crítico em saúde? Resposta: Capacidade de analisar informações e participar de decisões.\nPérola: Letramento crítico: o paciente decide com você.\nArmadilha: Confundir com decodificação básica de textos.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Saber avaliar informações de saúde de forma crítica significa não só entender o que está escrito, mas também pensar se é confiável e participar das decisões sobre a própria saúde."},{"id":"b15-q089","number":89,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Na abordagem clínica ampliada, a anamnese transcende o levantamento de dados objetivos, exigindo do profissional médico uma escuta qualificada e interpretativa que articule a narrativa do paciente aos fundamentos biopsicossociais do processo de adoecimento. Com base nessa informação e nas diretrizes da medicina centrada na pessoa e nos princípios da clínica ampliada, assinale a opção que apresenta a concepção contemporânea de entrevista clínica.","options":{"A":"A estruturação da anamnese deve restringir- se aos elementos técnicos objetivos, evitando a interferência de conteúdos subjetivos que possam obscurecer o raciocínio diagnóstico.","B":"O método clínico exige padronização da coleta de dados, priorizando a fidedignidade estatística das informações colhidas sobre a experiência do paciente.","C":"A elaboração da hipótese clínica deve orientar- se exclusivamente pelos protocolos fundamentados em evidências, minimizando o tempo dedicado a informações que não se enquadrem nos algoritmos diagnósticos.","D":"O processo anamnésico deve priorizar os critérios classificatórios das nosologias oficiais (DSM, CID), como forma de garantir uniformidade e segurança técnico-jurídica na prática assistencial.","E":"A escuta clínica deve considerar a singularidade biográfica do paciente, incorporando as suas dimensões subjetivas, sociais e simbólicas na formulação diagnóstica e no plano terapêutico."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A clínica ampliada exige que a escuta considere a singularidade biográfica e social do paciente.\nPonto de prova: Princípios da clínica ampliada.\nFlashcard sugerido: Qual a concepção de entrevista clínica na clínica ampliada? Resposta: Escuta que considera a singularidade biográfica e subjetiva.\nPérola: A doença não existe sem o doente.\nArmadilha: Focar apenas em preencher formulários.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Uma boa conversa entre médico e paciente escuta a história de vida da pessoa inteira, não só os sintomas, levando em conta seus sentimentos e sua realidade social."},{"id":"b15-q097","number":90,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Um homem de 64 anos procura o pronto atendimento com queixa de cefaleia iniciada há 4 dias. A dor é predominantemente hemicraniana, variando em intensidade entre 7 e 9 em uma escala de 0 a 10. A cefaleia é associada a náuseas e fotofobia. O paciente relata que tem utilizado dipirona 4x/dia para controle da dor. Nega febre, sintomas respiratórios, digestivos ou urinários. Sem outras queixas no período. Nega episódios prévios de cefaleia. Antecedente: hipertensão arterial sistêmica, em uso de hidroclorotiazida; sem outras comorbidades ou sintomas prévios. Os sinais vitais à entrada são: FC: 80 bpm, FR: 16 irpm, PA: 144 × 82 mmHg e T: 36,5 ºC. Ao exame neurológico, apresenta nível e conteúdo da consciência sem alterações, força grau 5 nos quatro membros, sem déficits de nervos cranianos e sem sinais de irritação meníngea. Com base no caso hipotético, assinale a alternativa que apresenta a conduta correta nesse momento:","options":{"A":"Realizar prova terapêutica com sumatriptano.","B":"Suspender a dipirona para controle de cefaleia por abuso de analgésicos.","C":"Iniciar ibuprofeno para controle sintomático e propranolol para profilaxia das crises.","D":"Prosseguir investigação com exame de imagem."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Cefaleia de forte intensidade, sem melhora, em paciente idoso sem antecedente. A conduta é prosseguir investigação com exame de imagem.\nPor que as outras estão erradas:\nA: Sumatriptano é para enxaqueca conhecida.\nB/C: Tratamento sintomático sem investigar é perigoso.\nPonto de prova: Sinais de alarme (idade > 50 anos) em cefaleia.\nFlashcard sugerido: Primeiro episódio de cefaleia intensa em paciente > 50 anos. Conduta? Resposta: Investigação com imagem.\nPérola: Cefaleia nova em idoso = Imagem!\nArmadilha: Fechar diagnóstico de enxaqueca sem excluir causas secundárias.","tags":["Clínica Médica","Neurologia","Cefaleia","Dipirona","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça nova e forte em uma pessoa mais velha, que nunca teve isso antes, precisa ser investigada com exame de imagem, para garantir que não é algo mais sério escondido."},{"id":"b15-q095","number":91,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Uma paciente de 36 anos, professora, relata episódios frequentes de dor de cabeça há mais de um ano. Ela descreve a dor como uma sensação de aperto bilateral, intensidade moderada, acompanhada de sensação de rigidez nos músculos da cabeça e pescoço. Refere que, antes das crises, frequentemente está submetida a situações de estresse emocional intenso devido ao trabalho. Nega sintomas associados, como náusea, vômito, nem aura visual. Durante o exame físico, observa-se sensibilidade aumentada à palpação dos músculos temporais e occipitais. Sobre o manejo e aspectos semiológicos associados à cefaleia tensional, assinale a alternativa correta:","options":{"A":"O exame neurológico na cefaleia tensional frequentemente revela déficits motores cranianos focais.","B":"O uso de biofeedback e técnicas de relaxamento não tem benefício algum comprovado na abordagem da cefaleia tensional.","C":"A prescrição profilática com antidepressivos tricíclicos está contraindicada em pacientes com cefaleia tensional crônica devido ao risco de dependência.","D":"Durante a crise, o uso exclusivo de opioides leves é considerado a primeira escolha por proporcionar maior controle da dor.","E":"A identificação e tratamento de pontos- gatilho miofasciais, através de técnicas como anestesia local, podem contribuir significativamente no controle da dor em cefaleia tensional."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A cefaleia tensional está associada à tensão muscular e pontos-gatilho miofasciais. A anestesia local e técnicas de relaxamento ajudam.\nPor que as outras estão erradas:\nA: Exame neurológico é normal.\nB: Biofeedback tem benefício.\nC: Tricíclicos não causam dependência.\nD: Opioides não são primeira linha.\nPonto de prova: Aspectos terapêuticos da cefaleia tensional.\nFlashcard sugerido: Tratamento de pontos-gatilho na cefaleia tensional? Resposta: Técnicas de relaxamento e anestesia local.\nPérola: Tensional aperta; relaxa e massageia.\nArmadilha: Prescrever opioides.","tags":["Clínica Médica","Neurologia","Cefaleia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça que aperta os dois lados da cabeça, ligada a estresse e tensão nos músculos, pode melhorar com massagem e técnicas de relaxamento nos pontos doloridos."},{"id":"b15-q093","number":92,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Paciente do sexo feminino, 28 anos, procura atendimento por quadro de cefaleia de longa data. Refere que a dor é unilateral, pulsátil, de forte intensidade, associada a náuseas, fono e fotofobia. No último ano, teve uma piora da frequência das crises, e atualmente tem dor cerca de 8 vezes ao mês, o que está prejudicando o seu trabalho. Antecedentes pessoais: obesidade e asma. Qual a melhor medicação profilática no momento?","options":{"A":"Propranolol.","B":"Ácido valproico.","C":"Topiramato.","D":"Amitriptilina."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Em pacientes com enxaqueca e obesidade, o Topiramato é o profilático de escolha (ajuda no controle da dor e promove perda de peso). Propranolol é contraindicado em asma.\nPor que as outras estão erradas:\nA: Propranolol é contraindicado em asmáticos.\nB/D: Valproato e amitriptilina causam ganho de peso.\nPonto de prova: Escolha do profilático da enxaqueca conforme comorbidades.\nFlashcard sugerido: Profilaxia da enxaqueca em paciente obeso e asmático? Resposta: Topiramato.\nPérola: Asmático não toma betabloqueador; gordinho toma topiramato.\nArmadilha: Receitar propranolol para asmático.","tags":["Clínica Médica","Neurologia","Asma","Cefaleia","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Para prevenir enxaqueca em pessoas com excesso de peso e asma, o remédio ideal ajuda a controlar a dor e ainda auxilia a emagrecer, sem prejudicar a respiração."},{"id":"b15-q092","number":93,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Uma mulher de 43 anos apresenta história de cefaleia diária há mais de seis meses, descrita como opressiva e difusa piorando ao longo do dia. Relata episódios prévios de enxaqueca desde a adolescência, mas, nos últimos meses, passou a utilizar dipirona e ibuprofeno em pelo menos 20 dias do mês, sem melhora significativa. Ao exame neurológico, não há alterações. Sobre o caso descrito, a hipótese diagnóstica mais provável e a melhor conduta inicial são:","options":{"A":"Cefaleia tensional crônica primária sem sinais de alarme e manter uso de analgésicos conforme necessidade, iniciando técnicas de relaxamento muscular.","B":"Neuralgia do trigêmeo com irradiação difusa e prescrever carbamazepina, considerando a necessidade de descompressão microvascular.","C":"Enxaqueca crônica com refratariedade terapêutica e associar triptanos com antieméticos, encaminhando- a para bloqueio anestésico regional.","D":"Cefaleia em salvas com padrão atípico e iniciar oxigenoterapia de alto fluxo com verapamil oral.","E":"Cefaleia por uso excessivo de medicação sintomática e suspender gradualmente os analgésicos, iniciando tratamento preventivo com antidepressivos tricíclicos ou topiramato."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Paciente com cefaleia > 15 dias/mês e uso de analgésicos > 10-15 dias/mês. O diagnóstico é Cefaleia por uso excessivo de medicação. Conduta: suspender os analgésicos e iniciar profilaxia.\nPor que as outras estão erradas:\nA/B/C/D: Diagnósticos incorretos.\nPonto de prova: Critérios para cefaleia por abuso de medicação.\nFlashcard sugerido: Cefaleia diária com uso de analgésicos em 20 dias/mês. Diagnóstico e conduta? Resposta: Abuso de medicação; suspender analgésicos e iniciar profilaxia.\nPérola: Quem toma muito analgésico, tem dor de cabeça crônica.\nArmadilha: Achar que é cefaleia tensional refratária.","tags":["Clínica Médica","Neurologia","Cefaleia","Dipirona","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Quando alguém toma remédio para dor de cabeça quase todo dia, sem melhorar, o próprio remédio em excesso pode estar causando mais dor de cabeça — a solução é parar aos poucos e começar um remédio preventivo."},{"id":"b15-semanais-q94","number":94,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Um homem de 26 anos, vem se queixando há 6 meses de dores de cabeça insuportáveis, em uso excessivo de analgésicos, dizendo ao médico Neurologista que pretende se matar caso as dores não melhorem. A dor tem característica latejante e em facadas, em região periorbital sempre à esquerda, intensidade 10/10, associada a fotofobia, lacrimejamento e edema em olho esquerdo, com sensação de inquietude importante e duração de aproximadamente 1 hora, sem nenhum fator desencadeante. As crises ocorrem preferencialmente de madrugada, 1-2 vezes por dia, e não melhoram com nenhuma medicação analgésica (dipirona, paracetamol, ibuprofeno, naratriptano, tramadol). Ao exame físico neurológico, o paciente não apresenta alterações. Diante desse caso, assinale a alternativa correta:","options":{"A":"O provável diagnóstico é Migrânea crônica associada a abuso de analgésicos.","B":"O provável diagnóstico é Cefaleia em Salvas e a avaliação com ressonância de crânio para descartar causas secundárias está indicada.","C":"O provável diagnóstico é Hemicrania Paroxística e está indicado oxigenioterapia como primeira linha de tratamento.","D":"O provável diagnóstico é Neuralgia do Trigêmio e está indicado tratamento com carbamazepina.","E":"O provável diagnóstico é Migrânea com aura autonômica."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadar é típico de Cefaleia em Salvas. Por ser refratária e intensa, a ressonância está indicada para afastar lesões secundárias.\nPor que as outras estão erradas:\nA/C/D/E: Outras cefaleias não preenchem os critérios.\nPonto de prova: Indicação de imagem em cefaleias primárias de difícil controle.\nFlashcard sugerido: Cefaleia em salvas muito refratária. O que solicitar? Resposta: Ressonância magnética de crânio.\nPérola: Salva atípica ou refratária: manda a RM.\nArmadilha: Confundir com migrânea.","tags":["Clínica Médica","Medicina Interna","Dipirona","Paracetamol","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor forte atrás de um olho, que vem várias vezes ao dia sempre no mesmo período, com olho inchado e vermelho, é a cefaleia em salvas, e quando é muito forte ou não melhora, o médico pede um exame de imagem para garantir que não há outra causa escondida."},{"id":"b15-q094","number":95,"collectionBlock":15,"documentBlock":15,"area":"Medicina de Família e Comunidade","topic":"Cefaleias","stem":"Em uma consulta na UBS, Lívia relata que sua pressão, apesar de estar fazendo o tratamento adequadamente, não está controlada; quando mede, às vezes, está 15 x 10, e outras vezes, 16 x 9. Fala que ela sabe que esses valores são altos e os relaciona a uma dor de cabeça na nuca. Conta que tem dor de cabeça frequentemente, que vai e volta algumas vezes no mês. A dor parece apertar a nuca e, por vezes, desce para ombros, algumas vezes dói moderadamente e, de vez em quando, dói muito, fazendo com que ela não consiga ajeitar a sua própria casa ao chegar do trabalho no final da tarde. Toma dipirona em todas ocasiões em que sente a dor, isso acontece em torno 1 a 2 vezes por semana, no máximo, 6 vezes no mês. Nega qualquer outro sintoma que acompanhe, exceto a pressão alterada. Hoje está com dor leve atrás da cabeça, sem qualquer outro sintoma. No exame físico, não havia qualquer alteração, e a PA era de 126 x 86 mmHg. Considerando o caso apresentado, assinale a alternativa que descreve, corretamente, o diagnóstico e o tratamento:","options":{"A":"É uma cefaleia secundária, e há necessidade de revisar os medicamentos para hipertensão arterial sistêmica para diminuir a pressão.","B":"É uma cefaleia primária, que exige tratamento profilático com antidepressivos, dose baixa e uso de exames de imagem.","C":"É uma cefaleia primária, que é tratada com anti- inflamatório não esteroidal associado e medidas não farmacológicas, por exemplo, massagem.","D":"É uma cefaleia crônica diária; deve- se suspender a medicação de uso frequente e pedir diário da dor, com retorno em 15 dias."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Dor bilateral, opressiva, irradiando para ombros, desencadeada por estresse. É Cefaleia Tensional. O tratamento é AINE e medidas não farmacológicas.\nPor que as outras estão erradas:\nA: Não é secundária à HAS.\nB/D: Não é profilático nem crônica diária.\nPonto de prova: Diagnóstico e tratamento da cefaleia tensional.\nFlashcard sugerido: Cefaleia opressiva em faixa irradiando para ombros. Tratamento? Resposta: AINE e massagem/relaxamento.\nPérola: Tensional aperta a nuca: AINE e massagem.\nArmadilha: Achar que é crise hipertensiva.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Dipirona","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma dor de cabeça que aperta a nuca e desce para os ombros, sem outros sintomas graves, costuma ser causada por tensão muscular, e melhora com anti-inflamatório e massagem relaxante."},{"id":"b15-semanais-q96","number":96,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Homem de 40 anos procura atendimento por quadro de dor de cabeça intensa, unilateral, com início súbito, localizada na região periocular direita. Relata que a dor é excruciante, em pontadas, com duração de cerca de 25 minutos, ocorrendo diariamente por duas a três vezes ao dia, sempre no mesmo horário, nas últimas três semanas. Durante as crises, refere lacrimejamento, hiperemia conjuntival e congestão nasal ipsilateral. Nega náuseas, vômitos ou fotofobia. Já usou analgésicos comuns, sem melhora. Já apresentou quadro semelhante há 1 ano. Exame neurológico sem alterações. Com base no quadro clínico apresentado, qual a conduta mais apropriada para tratamento agudo e profilático?","options":{"A":"Iniciar betabloqueador de longa ação e solicitar angio-RM de crânio para afastar MAV.","B":"Prescrever amitriptilina em baixa dose e orientar a higiene do sono.","C":"Iniciar oxigenoterapia por máscara facial a 100% e considerar verapamil como preventivo.","D":"Realizar punção lombar para investigação de hipertensão intracraniana idiopática."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O tratamento abortivo da Cefaleia em Salvas é Oxigenoterapia a 100%. O profilático de primeira linha é Verapamil.\nPor que as outras estão erradas:\nA/B/D: Não estão indicados.\nPonto de prova: Tratamento da Cefaleia em Salvas.\nFlashcard sugerido: Tratamento abortivo e profilático da cefaleia em salvas? Resposta: O2 a 100% e Verapamil.\nPérola: Salva: O2 para a crise, Verapamil para a vida.\nArmadilha: Dar analgésico oral (não dá tempo de fazer efeito).","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","kids":"A dor forte de um lado do rosto, com olho lacrimejando e nariz entupido, que se repete várias vezes ao dia sempre no mesmo horário, melhora respirando oxigênio puro na crise, e se previne com um remédio que relaxa os vasos sanguíneos."},{"id":"b15-q090","number":97,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Mulher, 26 anos de idade, com antecedente de enxaqueca, apresenta queixa de cefaleia de forte intensidade. Paciente relata que apresenta cefaleia de moderada intensidade três vezes por semana, que responde ao uso de triptanos e dipirona. Desta vez, ela apresenta cefaleia contínua há quatro dias, associada a náuseas e fotofobia, sem vômitos. Já fez uso de sumatriptano, dipirona e ibuprofeno, sem alívio da dor. Nega uso contínuo de medicações analgésicas. Exames clínico e neurológico normais. A conduta mais adequada é:","options":{"A":"Dexametasona IV e tramadol IV.","B":"Clorpromazina IV e dexametasona IV.","C":"Clorpromazina IV e cetoprofeno IV.","D":"Cetoprofeno IV e galcanezumabe SC."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro é Status Migranosus (enxaqueca > 72h refratária). O tratamento de escolha na emergência é um antiemético (Clorpromazina) associado a um corticoide (Dexametasona).\nPor que as outras estão erradas:\nA/C/D: Tramadol não é primeira linha.\nPonto de prova: Tratamento do Status Migranosus.\nFlashcard sugerido: Tratamento de Status Migranosus na emergência? Resposta: Clorpromazina IV + Dexametasona IV.\nPérola: Enxaqueca que não passa: corticoide e antiemético.\nArmadilha: Continuar dando triptano.","tags":["Clínica Médica","Neurologia","Cefaleia","Dipirona","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Quando a enxaqueca dura vários dias seguidos e não melhora com os remédios de sempre, o médico usa uma combinação de remédio para enjoo com um anti-inflamatório mais forte na veia."},{"id":"b15-semanais-q98","number":98,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Paciente do sexo masculino, 27 anos, com histórico de infliximab devido ao uso prolongado de medicamentos para tratamento de Doença de Crohn. Apresenta quadro clínico iniciado há 3 dias, com febre e cefaleia. Hoje iniciou um discurso confuso, com dificuldade para nomear objetos. Ao exame, apresenta- se sonolento, com rigidez de nuca e sinal de Brudzinski. Realizada ressonância magnética de crânio, mostrada abaixo. Fonte: https://radiopaedia.org/cases/ - Consulta em 24/03/2025 Sobre o diagnóstico mais provável, assinale a correta:","options":{"A":"Paciente com quadro sugestivo de meningite bacteriana, com evolução aguda e grave dos sintomas. Por isso, a terapia empírica inicial deverá ser com dexametasona, ceftriaxona 2g 12/12h, ampicilina 2g 4/4h e vancomicina 15-20mg/kg/12hs (após ataque).","B":"A principal suspeita é de meningoencefalite herpética e o tratamento de escolha é o aciclovir intravenoso 10mg/ kg/8hs corrigido função renal. O diagnóstico pode ser confirmado por pesquisa molecular (PCR) no líquor.","C":"A meningite por tuberculose é a principal hipótese diagnóstica para o caso em questão, dada a evolução do quadro em paciente imunossuprimido. Dessa forma, devemos iniciar terapia empírica com esquema RHZE associado a dexametasona","D":"A principal suspeita é uma meningite viral (sendo mais provável enterovírus) pelo quadro clínico e RM de crânio com alteração em lobos frontais bilateralmente. Por isso, o tratamento mais adequado é suporte clínico e hidratação endovenosa."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: A RM mostra hiperintensidade nos lobos temporais, o que associado ao quadro sugere fortemente Meningoencefalite Herpética. O tratamento é Aciclovir EV.\nPor que as outras estão erradas:\nA/C/D: Não causam típica alteração bilateral nos lobos temporais.\nPonto de prova: Diagnóstico e tratamento da encefalite herpética.\nFlashcard sugerido: RM com alteração em lobo temporal bilateral. Tratamento empírico? Resposta: Aciclovir EV.\nPérola: Lobo temporal na RM: Aciclovir na veia!\nArmadilha: Iniciar esquema antibacteriano amplo.","tags":["Clínica Médica","Neurologia","Doença Inflamatória Intestinal","Cefaleia","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Uma pessoa com doença de Crohn, que toma remédio que baixa as defesas do corpo, começa a ter febre, dor de cabeça e confusão — o exame de imagem mostra alteração numa parte do cérebro que é típica de uma infecção causada pelo vírus do herpes, tratada com remédio antiviral na veia."},{"id":"b15-q100","number":99,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cefaleias","stem":"Um paciente de 59 anos é admitido no pronto- socorro com histórico de febre alta, cefaléia intensa, confusão mental e convulsões focais que evoluíram para generalizadas. A família relata que os sintomas começaram há 5 dias e pioraram progressivamente, com episódio de crise focal disperceptiva motora há 1 dia.. O exame neurológico revela rebaixamento do nível de consciência, rigidez de nuca, afasia e hemiparesia à direita. Realizada ressonância magnética (RM) do encéfalo, com o seguinte resultado: Case courtesy of Bruno Di Muzio, Radiopaedia.org, rID: 26529. Diante da principal hipótese diagnóstica do paciente, qual a primeira conduta a ser tomada neste momento?","options":{"A":"Iniciar antibioticoterapia de amplo espectro imediatamente.","B":"Realizar eletroencefalograma (EEG) e iniciar anticonvulsivantes.","C":"Realizar tomografia computadorizada (TC) de crânio e aguardar resultados para definir tratamento.","D":"Iniciar aciclovir intravenoso e realizar punção lombar para análise do líquor."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: D.\nPor que está certa: O quadro com alteração de comportamento, convulsão, déficit neurológico e RM com alteração temporal é Encefalite por HSV. A conduta é iniciar Aciclovir IV imediatamente e realizar punção lombar.\nPor que as outras estão erradas:\nA/C: Aguardar ou focar apenas em antibiótico atrasa o tratamento.\nB: EEG não é prioridade.\nPonto de prova: Conduta na suspeita de encefalite herpética.\nFlashcard sugerido: Suspeita de encefalite herpética. Qual a primeira conduta? Resposta: Iniciar Aciclovir IV e colher líquor.\nPérola: Encefalite temporal: Aciclovir antes de tudo.\nArmadilha: Aguardar PCR do líquor para tratar.","tags":["Clínica Médica","Neurologia","Déficit Neurológico Focal","Cefaleia","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Quando alguém tem febre alta, dor de cabeça forte, confusão e convulsões, e o exame de imagem mostra alteração no cérebro, o médico começa logo o remédio contra o vírus herpes, além de coletar o líquido da coluna."},{"id":"b15-q099","number":100,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Meningites","stem":"Paciente do sexo masculino, 40 anos, sem comorbidades conhecidas, inicia com febre e mal estar há 2 dias, hoje é trazido por familiares ao pronto socorro devido a crise convulsiva. Na avaliação paciente se encontra confuso, sonolento, sem outros achados no exame físico. Foi realizado uma ressonância de crânio demonstrada a seguir e punção lombar com análise do líquor demonstrando: 50 células, com 85% de linfócitos e 15% neutrófilos, glicose 65 mg/dl e proteínas 45 mg/dL. ** ** Fonte: radiopaedia.com De acordo com caso clínico apresentado responda: Qual desses tratamentos deve ser instituído nesse momento?","options":{"A":"Dexametasona 6 mg 8/8 horas.","B":"Aciclovir endovenoso.","C":"Ampicilina.","D":"Observação clínica até resultado das culturas no líquor."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: O quadro clinico, LCR linfocítico e RM alterada são típicos de Encefalite por Herpes Simplex. O tratamento de escolha é Aciclovir endovenoso.\nPor que as outras estão erradas:\nA/C/D: Dexametasona, ampicilina e observação não tratam a encefalite herpética.\nPonto de prova: Tratamento da encefalite herpética.\nFlashcard sugerido: Tratamento de eleição para encefalite herpética? Resposta: Aciclovir endovenoso.\nPérola: Encefalite do lobo temporal: Aciclovir na veia.\nArmadilha: Observar clínico até resultado de cultura.","tags":["Clínica Médica","Neurologia","Convulsões","Punção Lombar","Interpretação de Exames","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-144","kids":"Um adulto com febre, confusão mental e um exame do líquido da coluna com muitas células de defesa (linfócitos) recebe o remédio contra o vírus herpes, que é a causa mais provável desse tipo de infecção no cérebro."},{"id":"b15-q098","number":101,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Cefaleias","stem":"Paciente de 4 anos dá entrada no pronto atendimento por quadro de crise convulsiva em casa, há 60 minutos. Mãe refere que o paciente está com quadro de febre e cefaleia há 1 dias e estava com febre no momento do episódio. A crise foi tônico- clônico generalizada e durou 5 minutos. O paciente nunca apresentara episódios semelhantes. Avaliando o paciente, ele se encontra sonolento (ECG 14), febril (39,4°C), taquicárdico, taquipneico, com tempo de enchimento capilar de 5 segundos, PA 80x50 mmHg e petéquias nos 4 membros. Diante do caso, qual a principal hipótese diagnóstica e conduta no momento?","options":{"A":"Choque séptico compensado sem etiologia esclarecida. Expansão com cristalóide 20 mL/kg e suporte de O2. Colher exames incluindo culturas, sem atrasar o início mais precoce possível de ceftriaxona. Não é necessária por hora a coleta de líquor, dado que o quadro convulsivo provavelmente se tratou de convulsão febril e o rebaixamento de nível de consciência atual se deve ao choque séptico.","B":"Choque séptico descompensado por meningococcemia. Expansão com cristalóide 20 mL/ kg e suporte de O2. Colher exames incluindo análise do líquor e culturas, sem atrasar o início mais precoce possível de ceftriaxona + vancomicina.","C":"Choque séptico descompensado sem etiologia esclarecida. Expansão com cristalóide 20 mL/ kg e suporte de O2. Colher exames incluindo culturas, sem atrasar o início mais precoce possível de ceftriaxona. Não é necessária por hora a coleta de líquor, dado que o quadro convulsivo provavelmente se tratou de convulsão febril e o rebaixamento de nível de consciência atual se deve ao choque séptico.","D":"Choque séptico compensado por meningococcemia. Expansão com cristalóide 20 mL/kg e suporte de O2. Colher exames incluindo análise do líquor e culturas, sem atrasar o início mais precoce possível de ceftriaxona + vancomicina."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","comment":"Análise:\nCorreta: D.\nPor que está certa: Febre, cefaleia, petéquias e sinais de choque (TEC 5s, PA 80x50) sugerem choque séptico compensado por meningococcemia. A conduta é expansão com cristalóide 20mL/kg, O2, coletar exames (incluindo líquor) e iniciar ATB precoce (Ceftriaxona + Vancomicina).\nPor que as outras estão erradas:\nA/C: A presença de petéquias e choque sugere fortemente meningococcemia, e o esquema deve cobrir isso.\nPonto de prova: Manejo do choque séptico e meningite na infância.\nFlashcard sugerido: Criança com febre, petéquias e choque. Conduta? Resposta: Expandir, coletar e iniciar Ceftriaxona + Vancomicina.\nPérola: Petéquias + choque: Ceftriaxona já!\nArmadilha: Achar que o choque está descompensado ou não coletar líquor se estiver compensado.","tags":["Pediatria","Saúde da Criança","Convulsões","Cefaleia","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 15.txt","scheduleId":"cron-140","kids":"Uma criança com febre, convulsão e manchinhas roxas na pele, além de sinais de que o corpo está indo mal (choque), precisa de soro na veia rapidamente e do antibiótico certo para uma infecção grave causada pela bactéria da meningite chamada meningococo."},{"id":"b15-semanais-q102","number":102,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Questões semanais - Bloco 15","stem":"Mulher de 45 anos vem ao PS com queixa de dor abdominal de intensidade 9 de 10, náuseas e parada de eliminação de flatos e fezes há 24 horas. Ao exame físico, dor à palpação abdominal difusamente sem peritonite. PA 120 x 80 mmHg. FC 105 bpm. Paciente realizou cirurgia bariátrica do tipo bypass gástrico com reconstrução em Y de Roux há 5 anos, com perda de peso adequada após procedimento. Relata cólica abdominal intermitente de leve intensidade com resolução espontânea desde a bariátrica, mas refere maior intensidade de dor no episódio atual. Nega alterações de peso nos últimos 6 meses ou alteração de hábito intestinal. Nega comorbidades. Qual é o diagnóstico mais provável e a conduta mais adequada?","options":{"A":"Síndrome de Wilkie. Duodenojejunostomia.","B":"Bridas. Alta hospitalar com orientação de sinais de alarme para retorno ao PS.","C":"Hérnia interna. Videolaparoscopia.","D":"Volvo de ceco. Laparotomia."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Pós-bypass em Y de Roux com quadro de obstrução intestinal aguda. A principal causa é Hérnia Interna. Conduta cirúrgica (videolaparoscopia).\nPor que as outras estão erradas:\nA/B/D: Síndrome de Wilkie e volvo não são tão comuns. Alta com orientação é perigoso em obstrução completa.\nPonto de prova: Complicações tardias do Y de Roux.\nFlashcard sugerido: Obstrução intestinal aguda tardia pós-bypass. Causa mais provável? Resposta: Hérnia interna.\nPérola: Y de Roux com barriga doendo e parada: Hérnia interna!\nArmadilha: Achar que é brida aderencial.","tags":["Cirurgia","Cirurgia Geral","Dor Abdominal","Cirurgia Bariátrica","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Quando uma pessoa que já fez cirurgia de emagrecimento tem dor de barriga forte, sem conseguir fazer cocô nem soltar gases, o mais provável é que um pedaço do intestino ficou preso em um buraco criado pela própria cirurgia — só resolve operando."},{"id":"b15-semanais-q103","number":103,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Questões semanais - Bloco 15","stem":"Paciente masculino de 38 anos com único antecedente de cirurgia bariátrica com bypass gástrico em Y de Roux há 1 ano e perda ponderal de 40 Kg procura o PS por quadro de dor abdominal, náuseas e vômitos pós- prandiais há 2 dias. Última evacuação há 4 dias. Ao exame físico: regular estado geral, abdome distendido, timpânico, doloroso à palpação de abdome superior, DB negativo, Murphy negativo. Qual a principal hipótese diagnóstica, o achado de exame de imagem e a conduta?","options":{"A":"Colecistite aguda - espessamento de parede de vesícula biliar - colecistectomia VLP.","B":"Pancreatite aguda - edema peripancreático - jejum.","C":"Hérnia interna - sinal de twist em tomografia - videolaparoscopia.","D":"Bridas - dilatação de alças intestinais em tomografia - videolaparoscopia."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O quadar obstrutivo pós-Y de Roux sugere Hérnia Interna. O achado de imagem clássico é o \"sinal do twist\" na tomografia. A conduta é videolaparoscopia.\nPor que as outras estão erradas:\nA/B/D: Colecistite, pancreatite e bridas são menos prováveis.\nPonto de prova: Diagnóstico por imagem de hérnia interna pós-bariátrica.\nFlashcard sugerido: Qual sinal tomográfico de hérnia interna após bypass? Resposta: Sinal do twist (swirl sign).\nPérola: Sinal do twist = Hérnia interna na TC.\nArmadilha: Confundir com bridas.","tags":["Cirurgia","Cirurgia Geral","Cirurgia Bariátrica","Dor Abdominal","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Depois de uma cirurgia de emagrecimento, dor de barriga forte com vômitos e prisão de ventre pode indicar que um pedaço do intestino ficou torcido dentro de um espaço criado pela cirurgia — a tomografia mostra um sinal de torção característico."},{"id":"b15-semanais-q104","number":104,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Questões semanais - Bloco 15","stem":"Nasce um recém- nascido de 36 semanas de idade gestacional pela DUM, sem causa aparente, pesando 2000 g, comprimento 47 cm, via vaginal e sem intercorrências. A mãe é uma adolescente de 16 anos, secundigesta, com abortamento prévio, sem vícios (alcoólico, tabagismo ou drogas) ou uso de medicação contínua, rastreio infeccioso negativo, Streptococcus agalactiae negativo. Na caderneta, constam teste rápido positivo para sífilis e VDRL de primeiro trimestre 1:64, segundo trimestre 1:64 e terceiro trimestre 1:32. Há a descrição, no segundo trimestre, de 3 doses de penicilina benzatina, totalizando 7.200.000 UI, com 7 dias de intervalo entre as doses. VDRL materno intra-hospitalar 1:8 e VDRL RN 1:4. Considerando o exposto, é correto afirmar que:","options":{"A":"Estamos diante de um caso de exposição à sífilis, devendo o RN receber uma dose de penicilina benzatina intramuscular antes da alta.","B":"Como o tratamento foi realizado tardiamente e de forma inadequada, o RN será considerado como sendo portador de sífilis congênita. Deve-se administrar penicilina procaína IM dose única por 10 dias.","C":"Trata- se de um caso de exposição à sífilis, sendo necessário o acompanhamento ambulatorial com dosagem seriada de VDRL.","D":"É um caso provável de sífilis congênita, devendo o RN ser submetido à radiografia de ossos longos e coleta de hemograma e líquor. Avaliar o tratamento a depender do resultado liquórico."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O tratamento materno foi tardio, mas o RN é prematuro e baixo peso, e a mãe tinha título alto no 1º trimestre. Ele é um caso provável de sífilis congênita e deve ser investigado com líquor, Rx ossos longos e hemograma.\nPor que as outras estão erradas:\nA/B/C: Ignorar a investigação completa é erro.\nPonto de prova: Protocolo de investigação de sífilis congênita em RN assintomático.\nFlashcard sugerido: RN de mãe com sífilis tratada, VDRL RN < Mãe, mas assintomático. Conduta? Resposta: Investigar com líquor, Rx e hemograma.\nPérola: Toda sífilis congênita suspeita pede líquor.\nArmadilha: Não investigar porque o título do RN é menor.","tags":["Pediatria","Saúde da Criança","Abortamento","Tabagismo","Conhecimento Conceitual","Período Neonatal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Um bebê que nasce pequeno, filho de mãe que fez pouco pré-natal e teve exame de sífilis alterado no início da gravidez, precisa de vários exames extras (líquido da coluna, sangue, raio-X dos ossos) para o médico decidir o melhor tratamento, mesmo que os títulos do bebê pareçam baixos."},{"id":"b15-semanais-q105","number":105,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Recém-nascido (RN) com 37 semanas de idade gestacional e 1950g é atendido em sala de parto. A mãe foi diagnosticada com HIV durante a gestação e não utilizou a Tarv. Diante risco de transmissão vertical, a profilaxia adequada para esse recém- nascido é:","options":{"A":"Zidovudina e lamivudina por 28 dias e nevirapina por 14 dias.","B":"Zidovudina, lamivudina e raltegravir por 28 dias.","C":"Zidovudina por 28 dias.","D":"Zidovudina, lamivudina e nevirapina por 28 dias."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: RN de mãe HIV+ que não usou TARV é de altíssimo risco. A profilaxia recomendada é o esquema triplo: AZT + 3TC + NVP por 28 dias.\nPor que as outras estão erradas:\nA/B/C: Esquemas duplos ou isolados não são recomendados para alto risco.\nPonto de prova: Profilaxia da TV do HIV em RN de mãe sem tratamento.\nFlashcard sugerido: RN de mãe HIV+ sem TARV. Esquema profilático? Resposta: AZT + 3TC + Nevirapina por 28 dias.\nPérola: Mãe não tomou nada: AZT + 3TC + NVP.\nArmadilha: Usar RAL. Embora RAL seja usado, a banca optou pelo esquema clássico de NVP.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando o exame do líquido da coluna do bebê mostra alteração, mesmo que ele pareça saudável, é preciso tratar com penicilina por mais dias, porque o remédio comum não trata bem a infecção que chegou ao cérebro."},{"id":"b15-semanais-q106","number":106,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Você é chamado para avaliar um recém nascido termo, peso adequado para idade gestacional, em bom estado geral e assintomático. A mãe durante a gestação foi diagnosticada no primeiro trimestre com sífilis congênita, com VDRL 1:32. Refere ter realizado o tratamento com 3 doses de penicilina benzatina IM, sem documentação. Na admissão na maternidade, a mãe apresentava VDRL 1:16 e o recém nascido 1:8. Demais exames laboratoriais e análise do líquor com proteinorraquia de 100 mg/ dl e 20 células/mm3, VDRL não reagente. Qual a melhor conduta a ser realizada com o recém-nascido?","options":{"A":"Penicilina procaína IM por 10 dias.","B":"Penicilina Benzatina IM dose única.","C":"Penicilina Cristalina EV por 7 dias.","D":"Seguimento clínico e laboratorial."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Líquor com 20 células e proteína 100mg/dl configura alteração liquórica. O tratamento indicado é Penicilina Cristalina EV ou Procaína IM por 10 dias.\nPor que as outras estão erradas:\nB/D: Penicilina Benzatina não trata neurossífilis. Seguimento clínico é errado.\nPonto de prova: Tratamento da sífilis congênita com neurossífilis.\nFlashcard sugerido: Sífilis congênita com líquor alterado. Tratamento? Resposta: Penicilina Procaína ou Cristalina por 10 dias.\nPérola: Líquor alterado: 10 dias de Penicilina.\nArmadilha: Usar Penicilina Benzatina em RN com líquor alterado.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sífilis","Conduta Terapêutica","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Nesse caso, mesmo com o tratamento da mãe pouco documentado, o esquema de acompanhamento correto é dar antibiótico por dez dias, porque o exame do líquido do bebê deu alterado."},{"id":"b15-semanais-q107","number":107,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Recém-nascido a termo nasce de mãe que foi diagnosticada com HIV no final do 2º trimestre da gestação e iniciou terapia antirretroviral (TARV), com coleta subsequente de carga viral (CV) negativa. Considere os principais aspectos do manejo imediato do recém-nascido na sala de parto e no alojamento conjunto e assinale a alternativa correta:","options":{"A":"Se o RN nascer com boa vitalidade, deve ser colocado em contato pele a pele imediato.","B":"O aleitamento materno pode ser liberado, tendo em vista CV materna negativa.","C":"É indicado manter o recém-nascido empelicado apenas nos partos vaginais e lavar o bebê com antissépticos alcoólicos após o nascimento.","D":"O clampeamento do cordão umbilical deve ser imediato mesmo que a CV materna seja negativa.","E":"O bebê deve ser lavado em água corrente imediatamente após o nascimento e o clampeamento do cordão deve ocorrer entre 1 e 2 minutos após nascimento."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Mesmo com CV materna indetectável, o RN de mãe HIV+ não deve ser banhado com antissépticos alcoólicos, mas sim lavado em água corrente. O clampeamento do cordão deve ser tardio (1 a 3 min).\nPor que as outras estão erradas:\nA: Contato pele a pele é polêmico/contraindicado.\nB: Aleitamento proibido.\nC: Empelicar não é para parto vaginal; álcool é contraindicado.\nPonto de prova: Manejo imediato do RN exposto ao HIV.\nFlashcard sugerido: RN exposto ao HIV, quando clampear o cordão? Resposta: Tardiamente (1 a 3 minutos).\nPérola: HIV: cordão tardio, banho com água e leite proibido.\nArmadilha: Fazer clampeamento imediato por medo de contaminação.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Logo depois que o bebê nasce, se a mãe tem HIV mas já está bem tratada, o corte do cordão umbilical deve ser feito um pouco depois (não imediatamente), e o bebê deve ser lavado com água comum, nunca com álcool."},{"id":"b15-semanais-q108","number":108,"collectionBlock":15,"documentBlock":15,"area":"Pediatria","topic":"Questões semanais - Bloco 15","stem":"Durante evolução médica em Alojamento Conjunto, o pediatra assistente deparou- se com um recém nascido termo, pequeno para a idade gestacional (percentil 1), proporcionado, optando por realizar investigação para infecções congênitas. Ao exame físico, presença de esplenomegalia, coriorretinite à realização de fundo de olho e calcificações intracranianas difusas visualizadas em Ultrassonografia Transfontanela. Dessa forma, qual o diagnóstico mais provável?","options":{"A":"Toxoplasmose congênita.","B":"Rubéola congênita.","C":"Citomegalovirose congênita.","D":"Sífilis congênita."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A tríade de calcificações intracranianas difusas, coriorretinite e hidrocefalia/PIG é de Toxoplasmose Congênita.\nPor que as outras estão erradas:\nB: Rubéola afeta olho, coração, ouvido.\nC: CMV tem calcificação periventricular.\nD: Sífilis tem pseudoparalisia.\nPonto de prova: Achados da toxoplasmose congênita.\nFlashcard sugerido: RN com calcificações difusas e coriorretinite. Diagnóstico? Resposta: Toxoplasmose congênita.\nPérola: Toxo: calcificação difusa e olho.\nArmadilha: Confundir com CMV.","tags":["Pediatria","Saúde da Criança","Trauma Esplênico","Raciocínio Diagnóstico","Período Neonatal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Um bebê pequeno para o tempo de gestação, com baço maior, manchas no olho e calcificações espalhadas pelo cérebro, tem os sinais clássicos de toxoplasmose pega ainda dentro da barriga."},{"id":"b15-q107","number":109,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções Congênitas","stem":"Gestante realizou exames de pré- natal no primeiro trimestre com 12 semanas de gestação, apresentando resultados positivos para IgG e IgM para toxoplasmose. Posteriormente, com 14 semanas, foi realizado teste de avidez para IgG, cujo resultado foi de 20%. A gestante recebeu tratamento com espiramicina, porém não foi realizada amniocentese para diagnóstico fetal. O parto ocorreu às 39 semanas de gestação e o RN se encontra assintomático em alojamento conjunto. Neste caso, a melhor conduta é:","options":{"A":"Tratando- se de toxoplasmose comprovada pela soroconversão materna, deve- se realizar avaliação detalhada com ultrassonografia transfontanela, tomografia de crânio, fundoscopia ocular, hemograma, análise do líquor e exame BERA, além de iniciar tratamento tríplice.","B":"Não iniciar tratamento no recém- nascido neste momento, realizando ultrassonografia transfontanela, fundoscopia ocular, ELISA IgM por captura, IgG do binômio e hemograma para monitoramento clínico-laboratorial.","C":"Considerar toxoplasmose congênita improvável devido à baixa avidez materna, não sendo indicado tratamento ou investigação para o recém-nascido.","D":"Não iniciar tratamento imediato e realizar avaliação com hemograma, sorologia pareada do binômio para IgM, fundoscopia ocular, tomografia de crânio, análise do líquor para monitoramento e detecção precoce de possíveis sequelas."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Como a infecção fetal não foi confirmada por PCR na gestação e o RN está assintomático, não se inicia o tratamento tríplice imediatamente. Deve-se investigar o RN.\nPor que as outras estão erradas:\nA/C/D: Iniciar tratamento tríplice sem confirmação ou não investigar não está correto.\nPonto de prova: Conduta no RN assintomático de mãe com toxoplasmose aguda.\nFlashcard sugerido: RN assintomático de mãe com toxo aguda não confirmada no feto. Conduta? Resposta: Investigar com sorologia, USG e fundoscopia, sem iniciar tríplice.\nPérola: Feto não confirmado: investiga o RN antes de tratar.\nArmadilha: Tratar logo de início com tríplice.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Toxoplasmose Gestacional","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Se o bebê nasceu bem e sem sintomas, e a infecção do feto não foi confirmada por exame específico durante a gravidez, o médico não começa logo o tratamento forte, mas pede vários exames de acompanhamento no bebê antes de decidir."},{"id":"b15-q110","number":110,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Recém- nascido de parto cesárea, com idade gestacional de 40 semanas; PN 3020g; APGAR 8/9; exposto ao HIV. A mãe iniciou Terapia Antirretroviral com 32 semanas de gestação, sem falha na adesão aos medicamentos e carga viral indetectável no periparto. Entre as opções de profilaxia abaixo, a mais adequada para esse recém-nascido é:","options":{"A":"Zidovudina, lamivudina e raltegravir.","B":"Zidovudina.","C":"Zidovudina, Lamivudina e Nevirapina.","D":"Nevirapina."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O gabarito aponta A. Embora o protocolo para mãe com CV indetectável preconize AZT isolado (Opção B), a banca considerou o RN de risco ou houve erro na elaboração. Justifica-se que, em alguns protocolos ou situações de risco não explícitas, o triplo é usado.\nPonto de prova: Profilaxia da TV do HIV.\nFlashcard sugerido: Profilaxia de RN de alto risco de TV HIV? Resposta: AZT + 3TC + RAL.\nPérola: Risco baixo: AZT. Risco alto: triplo.\nArmadilha: Confundir baixo e alto risco.","tags":["Ginecologia e Obstetrícia","Obstetrícia","HIV/AIDS","Assistência ao Parto","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando a mãe começou o tratamento do HIV a tempo e chegou ao parto com o vírus bem controlado, ainda assim, nesse caso, o gabarito considera que o bebê recebe o esquema mais completo de remédios, por segurança."},{"id":"b15-semanais-q111","number":111,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Recém-nascido filho de mãe com perda de seguimento durante o pré-natal apresenta ao nascimento hepatoesplenomegalia e icterícia. Realizada investigação complementar que identificou calcificações cerebrais difusas, coriorretinite e hidrocefalia. Frente ao quadro clínico descrito, qual a principal hipótese diagnóstica?","options":{"A":"Sífilis congênita.","B":"Rubéola congênita.","C":"Infecção congênita por citomegalovírus.","D":"Toxoplasmose congênita."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A tríade de calcificações difusas, hidrocefalia e coriorretinite é classicamente vista na Toxoplasmose Congênita.\nPor que as outras estão erradas: CMV tem calcificação periventricular; Rubéola tem alterações cardíacas; Sífilis tem pseudoparalisia.\nPonto de prova: Síndromes congênitas (Toxo).\nFlashcard sugerido: Calcificação difusa, hidrocefalia e coriorretinite. Diagnóstico? Resposta: Toxoplasmose congênita.\nPérola: Toxo: difusa e hidrocefalia.\nArmadilha: Confundir com CMV.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Raciocínio Diagnóstico","Período Neonatal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-142","kids":"Um bebê com fígado e baço maiores, olho com manchas e calcificações espalhadas e cabeça inchada por líquido tem os sinais típicos de toxoplasmose pega dentro da barriga da mãe."},{"id":"b15-semanais-q112","number":112,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Primigesta, com 10 semanas de gestação, comparece em consulta pré- natal com exames de primeiro trimestre. Nega queixas. Entre os exames, sorologia para toxoplasmose que consta: IgM positivo e IgG positivo. De acordo com o preconizado pelo Ministério da Saúde, qual a conduta mais adequada?","options":{"A":"Iniciar Espiramicina e repetir sorologias em 2 semanas.","B":"Teste de avidez imediatamente.","C":"Iniciar Pirimetamina, sulfadiazina e ácido folínico.","D":"Iniciar Espiramicina e solicitar teste de avidez."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Gestante no 1º trimestre com IgG e IgM positivos. Inicia Espiramicina e solicita Teste de Avidez de IgG.\nPor que as outras estão erradas: Repetir sorologia atrasa. Avidez sem espiramicina deixa o feto desprotegido.\nPonto de prova: Fluxograma de toxoplasmose na gestação.\nFlashcard sugerido: Gestante no 1º tri com IgG/IgM +. Conduta? Resposta: Espiramicina + Teste de avidez.\nPérola: IgM + no 1º tri = Espiramicina e Avidez.\nArmadilha: Pedir avidez isolada.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Toxoplasmose","Conduta Terapêutica","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Uma gestante com dois exames de sangue positivos para toxoplasmose logo no início da gravidez precisa começar um remédio de proteção e fazer um exame extra para saber se a infecção é recente."},{"id":"b15-q118","number":114,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Gestante com sorologias de sífilis não reagentes, no início do pré- natal, retorna na 28ª semana com teste treponêmico positivo. É correto afirmar que:","options":{"A":"Se trata de caso de sífilis em gestante, em fase latente tardia.","B":"Pode ser um resultado falso positivo, especialmente se o título for menor ou igual a 1/4.","C":"O tratamento consiste em benzilpenicilina benzatina na dose de 2,4 milhões UI, intramuscular, 1 x/semana por 3 semanas.","D":"Após o tratamento, o aumento do título do VDRL, em duas diluições, indica retratamento."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Após tratamento adequado, um aumento de 2 diluições (ex: de 1:2 para 1:8) indica reinfecção ou falha terapêutica, exigindo retratamento.\nPor que as outras estão erradas:\nA/B/C: Não há fase latente tardia garantida; falso positivo não justaria título.\nPonto de prova: Interpretação de VDRL pós-tratamento.\nFlashcard sugerido: Quando retratar sífilis após tratamento adequado? Resposta: Se VDRL aumentar 2 diluições.\nPérola: VDRL subiu 2 títulos: retrata!\nArmadilha: Ignorar o aumento do VDRL.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sífilis","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Se o exame de sangue de sífilis volta a subir bem depois de tratada, é sinal de que a pessoa pegou a doença de novo, e por isso precisa ser tratada outra vez."},{"id":"b15-semanais-q115","number":115,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Gestante de 9 semanas inicia o pré-natal na UBS próxima à sua residência. São realizados testes rápidos para HIV e Sífilis, tendo como resultados: não reagente e reagente, respectivamente. Sobre este assunto, assinale a alternativa correta:","options":{"A":"O teste rápido consiste num teste treponêmico e após o tratamento será utilizado para monitorização da resposta ao tratamento da sífilis.","B":"O teste rápido é um teste treponêmico e mesmo isoladamente indica tratamento de sífilis, quando positivo na gestante em qualquer circunstância.","C":"O teste rápido reagente deve indicar tratamento de sífilis caso a gestante não tenha comprovante de tratamento adequado anterior para a doença, e deve-se realizar a coleta do VDRL o mais precoce possível, para monitorização dos títulos.","D":"O teste rápido para sífilis visa detectar a presença de anticorpos anticardiolipina no sangue da gestante, sendo então específico para a presença do T.pallidum."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O teste rápido é treponêmico. Se positivo e a gestante não tem comprovante de tratamento anterior, deve-se iniciar o tratamento imediatamente e solicitar o VDRL para monitorização.\nPor que as outras estão erradas:\nA/B/D: O teste rápido não serve para monitorização; o VDRL sim.\nPonto de prova: Protocolo de sífilis na gestação com teste rápido positivo.\nFlashcard sugerido: Gestante com teste rápido positivo para sífilis. O que fazer? Resposta: Tratar e solicitar VDRL.\nPérola: Teste rápido positivo: trata e pede VDRL.\nArmadilha: Aguardar o VDRL para tratar a gestante.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","HIV/AIDS","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando a gestante tem exame positivo para sífilis e não tem comprovante de ter sido tratada antes, o médico já começa o tratamento e pede o exame de sangue para acompanhar a resposta."},{"id":"b15-q117","number":116,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Infecções na Gravidez","stem":"Gestante de 35 anos, que trabalha como jardineira, descobriu a gravidez há duas semanas. Está em sua primeira gestação e iniciou o pré- natal no posto de saúde mais próximo de sua casa. Atualmente, está com 18 semanas e trouxe os exames coletados na semana passada para avaliação: Diante dos resultados, qual a conduta a ser realizada no pré-natal?","options":{"A":"Prescrever pirimetamina, sulfadiazina e ácido folínico, e encaminhar para o pré-natal de alto risco.","B":"Prescrever espiramicina, solicitar nova sorologia para Toxoplasmose em duas semanas e encaminhar para o pré-natal de alto risco.","C":"Aumentar a dose de ácido fólico para 4 mg por dia e encaminhar para o pré-natal de alto risco.","D":"Encaminhar para o pré-natal de alto risco para investigação de transmissão vertical por CMV."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Na 18ª semana, já estamos no 2º trimestre. Se a sorologia IgG e IgM for positiva no 2º trimestre, o teste de avidez perde utilidade. A conduta é iniciar o tratamento de infecção fetal (esquema tríplice).\nPor que as outras estão erradas:\nB: Espiramicina e nova sorologia não são conduta para o 2º trimestre.\nPonto de prova: Manejo da toxoplasmose no 2º trimestre.\nFlashcard sugerido: 18 sem com IgG e IgM +. Conduta? Resposta: Tratamento tríplice.\nPérola: Toxo no 2º tri sem avidez: manda a tríplice direto.\nArmadilha: Pedir avidez no 2º trimestre.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Conduta Terapêutica","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Se a gestante trabalha mexendo com terra (jardinagem) e o exame de toxoplasmose vem alterado já mais avançado na gravidez, o remédio mais forte para proteger o bebê é iniciado direto, sem precisar do exame de maturidade dos anticorpos."},{"id":"b15-semanais-q117","number":117,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Uma gestante de 14 semanas comparece à consulta trazendo resultados da primeira rotina laboratorial. Tem antecedente pessoal de Hipertensão arterial crônica e mostra resultado de sorologia para toxoplasmose IgG reagente e IgM não reagente. O restante dos exames de rotina pré-natal não apresentam alterações. Qual a conduta mais correta a ser seguida?","options":{"A":"Considerar a paciente não imunizada e repetir a sorologia a cada dois meses ao longo do pré-natal.","B":"Iniciar espiramicina e solicitar teste de avidez para determinar quando houve a infecção.","C":"Iniciar o tratamento com esquema tríplice imediatamente e orientar a paciente sobre riscos fetais.","D":"Considerar a paciente imune à toxoplasmose e não repetir novamente a sorologia."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: IgG positivo e IgM negativo indicam imunidade prévia. Não há necessidade de repetir sorologias.\nPor que as outras estão erradas:\nA/B/C: Repetir, tratar ou pedir avidez não estão indicados.\nPonto de prova: Interpretação de sorologia para toxo.\nFlashcard sugerido: Gestante IgG + e IgM -. O que significa? Resposta: Imune, não repetir.\nPérola: IgG + e IgM - = Imune, dispensa repetição.\nArmadilha: Repetir a cada trimestre.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Hipertensão Arterial","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Quando o exame de sangue mostra que a gestante já teve toxoplasmose antes de engravidar (anticorpos antigos, sem sinal de infecção nova), ela está protegida e não precisa repetir o exame."},{"id":"b15-semanais-q118","number":118,"collectionBlock":15,"documentBlock":15,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 15","stem":"Gestante relata que teve sífilis com 16 semanas e foi tratada com o parceiro com penicilina benzatina (gestante = 7.200.000UI e parceiro = 2.400.000UI). Hoje, com 36 semanas de gravidez, retorna à consulta de pré-natal e os resultados dos exames pós-tratamento, quando chegou a apresentar VDRL de 1/8, mostram VDRL de 1/32. A hipótese diagnóstica e conduta são:","options":{"A":"Reinfecção, tratar novamente a paciente e o parceiro.","B":"Aumento não significativo da titulação do VDRL e continuar o acompanhamento pré-natal.","C":"Reinfecção, tratar novamente com uma medicação diferente da usada inicialmente.","D":"Aumento não significativo da titulação, realizar FTABS para confirmar necessidade de tratamento."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Aumento de 2 diluições (de 1:8 para 1:32) após tratamento adequado indica reinfecção. A conduta é retratar a paciente e o parceiro.\nPor que as outras estão erradas:\nB/C/D: Aumento de 2 diluições é significativo e exige retratamento.\nPonto de prova: Conduta frente a aumento do VDRL.\nFlashcard sugerido: VDRL subiu de 1:8 para 1:32 após tratamento. Diagnóstico e conduta? Resposta: Reinfecção; retratar.\nPérola: VDRL dobrou duas vezes: reinfectou.\nArmadilha: Achar que é flutuação normal do VDRL.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Sífilis","Pré-Natal","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Se o exame de sangue de sífilis sobe bastante depois de a gestante ter sido tratada, é sinal de que ela pegou a doença de novo, então ela e o parceiro precisam ser tratados outra vez."},{"id":"b15-q114","number":119,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Infecções na Gravidez","stem":"Em relação ao rastreamento e às precauções para prevenção da toxoplasmose congênita durante o pré- natal, assinale a alternativa correta.","options":{"A":"A realização do teste de avidez da IgG deve ser feita em todas as gestantes independentemente da idade gestacional, pois identifica infecção aguda em qualquer fase da gestação.","B":"A presença de IgG negativo e IgM negativo no início do pré- natal indica que a gestante está infectada e necessita iniciar tratamento imediatamente.","C":"Medidas primárias de prevenção só são indicadas para gestantes diagnosticadas com infecção aguda, não sendo recomendadas para aquelas suscetíveis.","D":"Se a gestante apresenta IgG positivo e IgM negativo na primeira consulta do pré-natal, deve-se considerar infecção aguda e iniciar tratamento imediato.","E":"A repetição da sorologia durante o pré- natal em gestantes suscetíveis visa detectar infecção aguda o mais precocemente possível, permitindo intervenção antes da transmissão vertical."},"answer":"E","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A repetição da sorologia na suscetível visa detectar a soroconversão o mais cedo possível para iniciar tratamento e prevenir a transmissão vertical.\nPor que as outras estão erradas:\nA: A avidez não serve para qualquer fase.\nB: IgG e IgM negativos significam suscetível.\nC: Medidas primárias são para todas.\nD: IgG + e IgM - é infecção pregressa.\nPonto de prova: Protocolo de rastreamento da toxoplasmose.\nFlashcard sugerido: Por que repetir sorologia de toxo em gestante suscetível? Resposta: Para detectar soroconversão precoce.\nPérola: Gestante suscetível repete sorologia.\nArmadilha: Achar que não precisa repetir se a primeira foi negativa.","tags":["Clínica Médica","Infectologia","Rastreamento","Toxoplasmose","Prevenção e Rastreamento","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"Repetir o exame de sangue de toxoplasmose ao longo da gravidez, em gestantes que ainda não tiveram a doença, serve para descobrir bem cedo se elas pegaram a infecção, e assim proteger o bebê a tempo."},{"id":"b15-q120","number":120,"collectionBlock":15,"documentBlock":15,"area":"Medicina de Família e Comunidade","topic":"Ferramentas da APS","stem":"A Atenção Primária à Saúde é uma complexa estrutura que integra diversos sistemas de saúde, tanto no Brasil quanto em diferentes países do mundo. Tem se consolidado como protagonista no cuidado de indivíduos e populações e, para tanto, baseia seu funcionamento nos atributos preconizados por Barbara Starfield. O atributo “Acesso de Primeiro Contato” na APS refere-se a:","options":{"A":"O acompanhamento contínuo e progressivo do paciente ao longo do tempo, criando vínculo com a equipe de saúde.","B":"A capacidade da APS de ofertar cuidado abrangente, contemplando diferentes dimensões da saúde da pessoa.","C":"A articulação entre a APS e os demais níveis de atenção, assegurando continuidade e integração do cuidado.","D":"A função da APS de ser a porta de entrada preferencial e usual do sistema de saúde, garantindo acesso oportuno às novas necessidades de saúde da população."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O Acesso de Primeiro Contato é a função da APS de ser a porta de entrada preferencial e usual do sistema de saúde.\nPonto de prova: Atributos da APS (Barbara Starfield).\nFlashcard sugerido: O que é o atributo \"Acesso de Primeiro Contato\"? Resposta: Ser a porta de entrada preferencial.\nPérola: APS é a porta de entrada.\nArmadilha: Confundir com longitudinalidade.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"A Atenção Primária de Saúde deve ser a porta de entrada principal do sistema de saúde, atendendo as pessoas assim que elas precisam, antes de encaminhar para outros serviços."},{"id":"b15-q125","number":121,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Em relação ao papel do médico de família na identificação e manejo das crises familiares ao longo do ciclo de vida, analise as afirmações abaixo e assinale a alternativa correta:","options":{"A":"Os encaminhamentos para apoio psicossocial só devem ser considerados nas crises paranormativas, nunca nas crises previsíveis do ciclo de vida.","B":"O conhecimento sobre os tipos de crises familiares (evolutivas e paranormativas) auxilia o médico de família a adaptar o cuidado, promovendo intervenções preventivas, suporte emocional e encaminhamentos adequados conforme a fase do ciclo de vida da família.","C":"As crises evolutivas geralmente não requerem intervenção do médico de família, já que a família tende a superá-las sozinha e são sempre acompanhadas de estabilidade emocional.","D":"O médico de família deve considerar apenas as crises evolutivas como causas de desestabilização familiar, pois as crises paranormativas são raras e geralmente irrelevantes nas estratégias de cuidado.","E":"A identificação das etapas do ciclo de vida familiar não é útil para o planejamento do cuidado, uma vez que os fatores externos sempre predominam na determinação do risco de crises."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O médico de família deve conhecer os tipos de crises (evolutivas e paranormativas) para intervir adequadamente.\nPonto de prova: Ciclo de vida familiar e crises.\nFlashcard sugerido: Crises paranormativas exigem qual tipo de abordagem do MFC? Resposta: Suporte emocional e encaminhamentos.\nPérola: Crise na família: MFC apoia.\nArmadilha: Ignorar as crises paranormativas.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"O médico de família precisa reconhecer os diferentes tipos de crises que uma família pode passar ao longo da vida, para saber a melhor forma de ajudar em cada momento."},{"id":"b15-semanais-q122","number":122,"collectionBlock":15,"documentBlock":15,"area":"Medicina de Família e Comunidade","topic":"Questões semanais - Bloco 15","stem":"Com base na Portaria GM/ MS nº 635/2023, que institui a Estratégia eMulti na Atenção Primária à Saúde, assinale a alternativa correta:","options":{"A":"A inclusão de, pelo menos, um médico especialista é obrigatória em todas as modalidades da eMulti.","B":"A atuação da eMulti ocorre exclusivamente em equipes da Estratégia Saúde da Família, sendo vedada sua vinculação a outras modalidades da APS.","C":"A modalidade Estratégica da eMulti deve incluir, como composição mínima, ao menos um nutricionista ou um psicólogo, com carga horária individual de 20 horas semanais.","D":"O arranjo intermunicipal para a constituição da eMulti é permitido apenas nas modalidades Complementar e Estratégica, sendo vedado na modalidade Ampliada."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A eMulti Estratégica deve incluir pelo menos um nutricionista ou psicólogo com carga horária mínima de 20h.\nPonto de prova: Composição da eMulti.\nFlashcard sugerido: Quem compõe a eMulti Estratégica? Resposta: Ao menos um nutricionista ou psicólogo (20h).\nPérola: eMulti estratégica: nutricionista ou psicólogo.\nArmadilha: Achar que a eMulti exclui outras modalidades.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Uma equipe de saúde que reúne vários profissionais diferentes, como nutricionista e psicólogo, precisa ter pelo menos um desses dois trabalhando um bom número de horas por semana."},{"id":"b15-semanais-q123","number":123,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Em uma unidade básica de saúde (UBS) manter de um bairro periférico, a equipe de saúde observou que muitos pacientes com doenças crônicas, como diabetes e hipertensão, apresentavam dificuldades para seguir o tratamento recomendado. A adesão às orientações médicas e ao uso de medicamentos foi baixa, e os profissionais de saúde identificaram que muitos pacientes tinham barreiras relacionadas ao entendimento sobre a doença e o autocuidado. A equipe decidiu implementar uma estratégia para melhorar a adesão ao tratamento e a compreensão dos pacientes sobre a importância do cuidado contínuo. Com base nessa situação hipotética, o método para promover a adesão ao tratamento dos pacientes com doenças crônicas nessa UBS é:","options":{"A":"Fornecer panfletos informativos sobre o tratamento de cada condição.","B":"Realizar consultas para cada paciente.","C":"Implementar grupos de apoio na UBS para troca de experiências entre pacientes com doenças crônicas.","D":"Aumentar a frequência das consultas para todos os pacientes com doenças crônicas.","E":"Encaminhar o paciente para a rede de referência."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A implementação de grupos de apoio na UBS promove troca de experiências e melhora a adesão ao tratamento.\nPonto de prova: Estratégias de educação em saúde em doenças crônicas.\nFlashcard sugerido: Como melhorar a adesão ao tratamento de doenças crônicas na UBS? Resposta: Grupos de apoio.\nPérola: Grupo na UBS une educação e adesão.\nArmadilha: Achar que dar panfletos resolve.","tags":["Clínica Médica","Endocrinologia","Diabetes Mellitus","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 15.txt","kids":"Quando pessoas com doenças de longo prazo têm dificuldade de seguir o tratamento, criar grupos na unidade de saúde para trocarem experiências ajuda muito mais do que só entregar folhetos."},{"id":"b15-semanais-q124","number":124,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Mulher, 25 anos de idade, procurou recentemente uma Unidade Básica de Saúde na cidade de São Paulo, debilitada fisicamente, com queixa de febre, especialmente à tarde, astenia e tosse. Não sabe precisar exatamente há quanto tempo. Ela não é moradora da região, diz não ter residência fixa e que trabalha nas ruas próximas à Unidade como profissional do sexo. Relata ter diagnóstico de soropositividade para o HIV. Não sendo moradora da área de cobertura da Unidade, qual deve ser a conduta do serviço frente ao caso?","options":{"A":"Deve ser encaminhada para Unidade de Saúde que desenvolve ações voltadas à população de rua (Consultório na Rua).","B":"Deve ser orientada a procurar um serviço de pronto atendimento, pela importância clínica do caso.","C":"Deve ser acolhida, coletar e aguardar resultados das sorologias para ser encaminhada para serviço especializado.","D":"Deve ser acolhida e avaliada imediatamente, pela importância clínica e epidemiológica do caso."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A universalidade do SUS exige acolhimento imediato de qualquer usuário que procure a UBS com problema grave de saúde.\nPonto de prova: Princípios do SUS (Universalidade e Acolhimento).\nFlashcard sugerido: Paciente fora da área com doença grave procura a UBS. Conduta? Resposta: Acolher e avaliar imediatamente.\nPérola: SUS é universal: todo grave é atendido na UBS.\nArmadilha: Encaminhar para outro serviço por não ser da área.","tags":["Clínica Médica","Infectologia","HIV/AIDS","Síndrome Febril","Conduta Terapêutica","Atenção Primária"],"tagSource":"Tags 15.txt","scheduleId":"cron-141","kids":"O sistema público de saúde deve acolher e cuidar imediatamente de qualquer pessoa que chegue precisando de ajuda, mesmo que ela não more perto daquela unidade."},{"id":"b15-semanais-q125","number":125,"collectionBlock":15,"documentBlock":15,"area":"Medicina de Família e Comunidade","topic":"Questões semanais - Bloco 15","stem":"Mulher com diagnóstico de hipercolesterolemia procurou a UBS mais próxima da casa de sua mãe para acompanhamento, sem outras queixas. Na recepção, foi orientada que, por não morar na região, deveria procurar uma UBS da sua região de moradia para realizar este acompanhamento. Em relação a esse cenário, indique se a recepção acertou ou errou e a respectiva justificativa:","options":{"A":"Acertou, porque a UBS de sua região de moradia é o local mais apropriado para o acompanhamento longitudinal.","B":"Acertou, porque pessoas não cadastradas não podem ser atendidas nas UBS.","C":"Errou, porque o SUS é universal e a paciente deveria ter sido atendida pela unidade que procurou.","D":"Errou, porque a Estratégia de Saúde da Família deve atender todos os familiares dos residentes da área de abrangência."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Para acompanhamento longitudinal de doença crônica, o correto é que a paciente seja cadastrada na UBS de sua área de moradia.\nPonto de prova: Territorialização e vínculo na APS.\nFlashcard sugerido: Paciente não mora na área da UBS e quer acompanhamento de rotina. O que fazer? Resposta: Orientar a procurar a UBS da sua área.\nPérola: Acompanhamento contínuo é no seu bairro.\nArmadilha: Achar que é erro por universalidade.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Raciocínio Diagnóstico","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Para acompanhar uma doença ao longo do tempo, o correto é a pessoa ser atendida na unidade de saúde perto de onde ela realmente mora, para manter um vínculo contínuo com a equipe."},{"id":"b15-semanais-q126","number":126,"collectionBlock":15,"documentBlock":15,"area":"Saúde Coletiva","topic":"Questões semanais - Bloco 15","stem":"O matriciamento em saúde mental é uma estratégia adotada pelo Sistema Único de Saúde (SUS) para qualificar o cuidado prestado pela Atenção Primária à Saúde (APS). Baseado na lógica da integralidade e do trabalho em rede, busca promover uma nova forma de interação entre as equipes da atenção básica e os serviços especializados, envolvendo apoio técnico, educação permanente e corresponsabilização pelo cuidado dos usuários. Considerando esses aspectos, assinale a alternativa correta:","options":{"A":"O matriciamento é uma estratégia que visa fortalecer a capacidade da APS no manejo de casos complexos. O cuidado é compartilhado entre as equipes, respeitando o vínculo da APS com o usuário e promovendo práticas mais integradas e resolutivas.","B":"O apoio matricial transfere o caso para o serviço especializado, que passa a ser o responsável pelo cuidado, desvinculando-o da APS.","C":"O matriciamento limita- se à organização do fluxo de encaminhamentos, sem envolvimento na elaboração de planos terapêuticos conjuntos.","D":"O matriciamento é um processo pontual e restrito a determinadas categorias profissionais, sem caráter multiprofissional ou educativo.","E":"O matriciamento ocorre exclusivamente nos serviços especializados, sem articulação direta com a Atenção Primária."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O matriciamento fortalece a APS, compartilhando o cuidado sem desvincular o paciente da equipe de referência.\nPonto de prova: Conceito de matriciamento.\nFlashcard sugerido: O que é matriciamento em saúde mental? Resposta: Apoio técnico à APS, compartilhando o cuidado.\nPérola: Matriciamento apia, não assume o caso.\nArmadilha: Achar que o caso é transferido.","tags":["Saúde Coletiva","Medicina de Família e Comunidade","Sistema Único de Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando uma equipe de saúde comum pede ajuda a especialistas para cuidar melhor de um caso difícil, o paciente continua sendo cuidado pela equipe que já o conhece, e não é transferido para outro lugar."},{"id":"b15-semanais-q127","number":127,"collectionBlock":15,"documentBlock":15,"area":"Saúde Coletiva","topic":"Questões semanais - Bloco 15","stem":"Em 2024 foi instituída nova metodologia de cofinanciamento federal do Piso de Atenção Primária à Saúde no SUS. Em relação às equipes previstas na Política Nacional de Atenção Básica, é correto afirmar:","options":{"A":"Em municípios de menor porte, há possibilidade de que os profissionais da equipe de Saúde da Família (eSF) exerçam carga horária diferenciada de 20h ou 30h.","B":"As equipes multiprofissionais (eMulti) atuam de forma complementar às equipes da Saúde da Família.","C":"Agentes de Saúde da Família integram a equipe da ESF, porém não são considerados profissionais de saúde.","D":"A composição mínima da eSF é de médico, enfermeiro, auxiliar ou técnico de enfermagem, Agente Comunitário de Saúde e Agente de Combate às Endemias."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: As equipes multiprofissionais (eMulti) atuam de forma complementar e integrada às equipes da Saúde da Família (eSF).\nPonto de prova: Papel da eMulti.\nFlashcard sugerido: Como a eMulti atua em relação à eSF? Resposta: De forma complementar.\nPérola: eMulti complementa a eSF.\nArmadilha: Achar que a eMulti substitui a eSF.","tags":["Saúde Coletiva","Medicina de Família e Comunidade","Sistema Único de Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"As equipes de saúde formadas por vários profissionais diferentes ajudam e completam o trabalho das equipes tradicionais de saúde da família, sem substituí-las."},{"id":"b15-q128","number":128,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Paciente com esofagite erosiva grau C (Los Angeles) foi tratado por 8 semanas com Inibidor de Bomba de Prótons (IBP). Qual conduta é recomendada após esse período?","options":{"A":"Suspender o IBP se assintomático.","B":"Suspender o IBP e iniciar H2-bloqueador.","C":"Manter IBP apenas se houver sintomas.","D":"Manter IBP em dose de manutenção e repetir a endoscopia."},"answer":"D","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Após 8 semanas de IBP, se a esofagite era erosiva (Grau C), o paciente deve manter IBP em dose de manutenção e repetir a endoscopia para avaliar cicatrização e displasia.\nPonto de prova: Seguimento endoscópico de esofagite erosiva grave.\nFlashcard sugerido: Conduta após 8 sem de IBP para esofagite Grau C? Resposta: Manter IBP e repetir endoscopia.\nPérola: Esofagite C: repete a endoscopia.\nArmadilha: Suspender o IBP simplesmente.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando o remédio para azia é usado por bastante tempo numa ferida mais grave no esôfago, é importante repetir o exame de câmera depois do tratamento para confirmar que cicatrizou."},{"id":"b15-q129","number":129,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Homem de 32 anos, sem comorbidades, procura atendimento ambulatorial por pirose há 5 meses. Já realizou endoscopia digestiva alta no início do quadro, que estava normal. Vem em uso de omeprazol 40 mg 1x a dia, em jejum, há 3 meses, mas sem melhora dos sintomas. Qual a conduta mais adequada para investigação no momento?","options":{"A":"Solicitar nova endoscopia digestiva alta.","B":"Solicitar pHmetria esofágica em uso de omeprazol.","C":"Solicitar pHmetria esofágica sem omeprazol.","D":"Reforçar medidas dietéticas e associar domperidona."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Sintomas típicos de DRGE sem esofagite e sem melhora com IBP sugerem DRGE não erosiva refratária. O exame ideal é a pHmetria, que deve ser feita COM o IBP SUSPENSO.\nPor que as outras estão erradas:\nA: Nova endoscopia não trará nova informação.\nB: pHmetria em uso de IBP só serve para documentar refratariedade.\nD: Domperidona não trata DRGE.\nPonto de prova: Investigação de DRGE refratária.\nFlashcard sugerido: DRGE sem esofagite e refratária ao IBP. Qual exame e como fazer? Resposta: pHmetria com IBP suspenso.\nPérola: Vai medir ácido? Suspende o IBP!\nArmadilha: Fazer pHmetria com o IBP.","tags":["Clínica Médica","Medicina Interna","Endoscopia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando alguém tem azia por vários meses, já fez uma câmera no estômago normal e o remédio não resolveu de vez, o exame que mede o ácido no esôfago precisa ser feito sem tomar o remédio, para dar um resultado confiável."},{"id":"b15-q130","number":130,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Homem de 38 anos, sem comorbidades, procura atendimento ambulatorial com queixas de pirose e regurgitação recorrentes há 6 meses, principalmente após refeições copiosas ou ao deitar. Refere melhora parcial com uso esporádico de antiácidos, mas os sintomas retornam frequentemente. Nega disfagia, perda de peso ou vômitos. Foi iniciado tratamento empírico com inibidor de bomba de prótons (IBP), com melhora apenas parcial dos sintomas após 8 semanas. Qual o próximo passo mais adequado na investigação diagnóstica deste paciente?","options":{"A":"Manometria esofágica de alta resolução.","B":"Endoscopia digestiva alta.","C":"Impedâncio-pHmetria esofágica com IBP suspenso.","D":"EED (esofagograma com contraste baritado)."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Paciente com sintomas típicos que teve resposta parcial ao IBP empírico. O próximo passo investigativo padrão é a Endoscopia Digestiva Alta.\nPor que as outras estão erradas:\nA/C: Manometria e pHmetria são exames de 2ª linha.\nD: Esofagograma não é de escolha.\nPonto de prova: Sequência de investigação da DRGE.\nFlashcard sugerido: Paciente com DRGE e resposta parcial ao IBP. Próximo exame? Resposta: Endoscopia digestiva alta.\nPérola: IBP não resolveu todo? Manda a endoscopia.\nArmadilha: Pular a endoscopia e pedir pHmetria direto.","tags":["Clínica Médica","Medicina Interna","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Quando alguém tem azia frequente que só melhora um pouco com o remédio, o próximo passo é fazer a câmera no estômago de novo, para ver se há alguma coisa nova que explique isso."},{"id":"b15-q131","number":131,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Em relação ao diagnóstico da Doença do Refluxo Gastroesofágico (DRGE) e seus aspectos clínico-endoscópicos, assinale a alternativa CORRETA:","options":{"A":"A endoscopia digestiva alta pode ser normal em até 30% dos pacientes com DRGE comprovada, não excluindo o diagnóstico diante de sintomas típicos.","B":"A ausência de esofagite erosiva à endoscopia exclui com segurança a DRGE, tornando desnecessária investigação complementar.","C":"O diagnóstico de esôfago de Barrett pode ser feito exclusivamente com base em alterações visuais da mucosa esofágica, sem necessidade de confirmação histológica.","D":"A pHmetria esofágica não tem papel na avaliação de pacientes com sintomas típicos de refluxo que não respondem ao uso de IBP."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A endoscopia pode ser normal em até 30-50% dos pacientes com DRGE (DRGE não erosiva).\nPor que as outras estão erradas:\nB: Ausência de esofagite não exclui DRGE.\nC: Barrett exige biópsia.\nD: pHmetria é útil em refratários.\nPonto de prova: Limites da endoscopia na DRGE.\nFlashcard sugerido: A endoscopia normal exclui DRGE? Resposta: Não, a DRGE não erosiva ocorre em 30%.\nPérola: Endoscopia normal não descarta DRGE.\nArmadilha: Exigir esofagite na endoscopia para fechar o diagnóstico.","tags":["Clínica Médica","Medicina Interna","Refluxo Gastroesofágico","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"O exame de câmera no estômago pode dar normal mesmo quando a pessoa realmente tem refluxo, então não dá para descartar o diagnóstico só porque a câmera não mostrou nada."},{"id":"b15-q132","number":132,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Ferramentas da APS","stem":"Homem de 53 anos, IMC de 37,4 kg/ m² e circunferência abdominal de 110 cm, refere pirose crônica parcialmente controlada com 40 mg de Pantoprazol. Nega disfagia, vômitos ou perda ponderal. Submetido à endoscopia digestiva alta, que evidenciou segmento de mucosa salmão de 3 cm de extensão acima da junção esofagogástrica. Com base nesse caso clínico, assinale a alternativa correta:","options":{"A":"O diagnóstico de esôfago de Barrett exige obrigatoriamente a presença de displasia epitelial.","B":"A presença de metaplasia intestinal no esôfago distal contraindica o uso de inibidores de bomba de prótons.","C":"Para o diagnóstico correto é necessário a análise histopatológica demonstrando metaplasia intestinal, independente do grau de displasia da amostra.","D":"O seguimento endoscópico não é necessário na ausência de displasia, pois o risco de progressão é desprezível."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O diagnóstico de Esôfago de Barrett exige a presença de metaplasia intestinal à biópsia.\nPor que as outras estão erradas:\nA: Não exige displasia.\nB: Metaplasia indica o uso de IBP.\nD: O seguimento endoscópico é necessário mesmo sem displasia.\nPonto de prova: Critérios diagnósticos de Esôfago de Barrett.\nFlashcard sugerido: O que confirma o diagnóstico de Esôfago de Barrett? Resposta: Metaplasia intestinal à histopatologia.\nPérola: Barrett = metaplasia na biópsia.\nArmadilha: Fechar diagnóstico apenas pelo achado visual.","tags":["Clínica Médica","Medicina Interna","Obesidade","Endoscopia","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-139","kids":"Para confirmar que alguém tem uma alteração chamada esôfago de Barrett, é preciso examinar um pedacinho da mucosa no microscópio e encontrar um tipo especial de célula (metaplasia), não basta só olhar pela câmera."},{"id":"b15-semanais-q133","number":133,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Questões semanais - Bloco 15","stem":"Considere uma senhora de 49 anos de idade, com queixa de azia crônica, regurgitação e tosse noturna. A endoscopia digestiva realizada revela esofagite erosiva moderada. Nesse caso, o tratamento inicial mais adequado é realizado por meio de:","options":{"A":"Antiácidos.","B":"Inibidores de bomba de prótons (IBP).","C":"Procinéticos.","D":"Cirurgia de fundoplicatura."},"answer":"B","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O tratamento inicial para esofagite erosiva é o uso de IBP por 8 semanas.\nPor que as outras estão erradas:\nA: Antiácidos são insuficientes.\nC: Procinéticos não cicatrizam.\nD: Cirurgia não é inicial.\nPonto de prova: Tratamento da DRGE erosiva.\nFlashcard sugerido: Tratamento inicial para esofagite erosiva? Resposta: IBP por 8 semanas.\nPérola: Tem erosão? Toma IBP.\nArmadilha: Usar antiácidos para cicatrizar erosão.","tags":["Clínica Médica","Medicina Interna","Tosse","Endoscopia","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Quando a câmera mostra uma ferida (esofagite) causada pelo refluxo, o tratamento certo é tomar remédio para reduzir o ácido por cerca de dois meses."},{"id":"b15-q133","number":134,"collectionBlock":15,"documentBlock":15,"area":"Clínica Médica","topic":"Cirurgia Bariátrica","stem":"Sobre complicações e condições associadas ao refluxo gastroesofágico (RGE), é INCORRETO afirmar que:","options":{"A":"O esôfago de Barrett ocorre apenas em pacientes com esofagite erosiva grave.","B":"O RGE pode manifestar-se com tosse crônica, rouquidão e asma refratária.","C":"Com esôfago de Barrett devem ser acompanhados com endoscopia periódica.","D":"A presença de anemia ferropriva e disfagia progressiva requer investigação de estenose péptica.","E":"Hérnia hiatal é fator anatômico predisponente ao refluxo."},"answer":"A","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A afirmação está INCORRETA. O Esôfago de Barrett pode ocorrer mesmo em pacientes sem esofagite erosiva grave prévia.\nPor que as outras estão erradas: (B, C, D, E estão corretas).\nPonto de prova: Fisiopatologia do Esôfago de Barrett.\nFlashcard sugerido: Esôfago de Barrett ocorre apenas em esofagite grave? Resposta: Não.\nPérola: Barrett não precisa de esofagite grave.\nArmadilha: Achar que Barrett é evolução obrigatória de esofagite grave.","tags":["Clínica Médica","Medicina Interna","Refluxo Gastroesofágico","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Uma alteração chamada esôfago de Barrett pode aparecer mesmo em pessoas que nunca tiveram uma ferida muito grave no esôfago causada pelo refluxo."},{"id":"b15-semanais-q135","number":135,"collectionBlock":15,"documentBlock":15,"area":"Cirurgia","topic":"Questões semanais - Bloco 15","stem":"Um homem, 55 anos, obesidade Grau I, hipertenso, em uso de losartana, queixa- se de azia e regurgitação. Ele tem diagnóstico de esteatose hepática, e o USG de abdômen descarta colelitíase. A endoscopia mostra uma hérnia hiatal pequena, por deslizamento, e esofagite erosiva leve. Assinale a alternativa que apresenta a melhor conduta para esse paciente:","options":{"A":"Encaminhar o paciente para tratamento cirúrgico da obesidade.","B":"Realizar pHmetria esofágica.","C":"Receitar inibidor de bomba de prótons, orientar sobre a perda de peso e realizar a orientação dietética.","D":"Realizar a correção laparoscópica da hérnia de hiato."},"answer":"C","source":"QUESTÕES BLOCO 15 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 15","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: O tratamento para DRGE leve com hérnia hiatal pequena é clínico: IBP, medidas dietéticas e perda de peso.\nPor que as outras estão erradas:\nA/D: Cirurgia não é indicada para DRGE leve.\nB: pHmetria não é necessária se o diagnóstico já foi confirmado.\nPonto de prova: Conduta clínica inicial da DRGE.\nFlashcard sugerido: DRGE leve com hérnia hiatal pequena. Conduta? Resposta: IBP, dieta e perda de peso.\nPérola: Hérnia pequena e leve: clínico.\nArmadilha: Operar hérnia hiatal pequena assintomática/leve.","tags":["Cirurgia","Cirurgia Geral","Obesidade","Doença Biliar","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 15.txt","scheduleId":"cron-143","kids":"Quando o refluxo é leve, com uma hérnia pequena, o tratamento é com remédio para reduzir o ácido, além de perder peso e cuidar da alimentação — sem precisar de cirurgia."}]};
